quests[10832] = { id = 10832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Zauberfeuerschneider wird", description = "Ich kann Euch die Kunst der Zauberfeuerschneiderei beibringen, aber seid gewarnt, es ist eine gefährliche Kunst.\n\nDie Herstellung von Zauberstoff im Nethersturm lockt mächtige Nethergespenster an. Ich bin auf der Suche nach einem Weg, um den Effekt zu mildern, aber dazu brauche ich noch mehr Essenzen der Nethergespenster für meine Forschungen.\n\nBringt dieses Signal zum Nethersturm und benutzt es, um ein Nethergespenst zu rufen. Bringt mir seine Essenz, dann werde ich Euch unterrichten. Als Zauberfeuerschneider werdet Ihr doppelt so viel Stoff erhalten und Zugang zu exklusiven Mustern bekommen.", sourceObjective = "Bringt eine Probe einer Nethergespenstessenz zu Gidge Spruchwirker im Unteren Viertel von Shattrath.\n\nACHTUNG! Ihr könnt nur eine Schneidereispezialisierung auswählen.", progress = "Habt Ihr die Nethergespenstprobe?", completion = "<Gidge untersucht die Nethergespenstessenz.>\n\nSogar in dieser kleinen Probe der Essenz ist seine Macht deutlich sichtbar. Vielleicht habe ich missverstanden, was vor sich geht. Wir erzürnen die Gespenster nicht, wenn wir der Umwelt die Energie nehmen. Die Umwelt und die Geister sind vielmehr eins!\n\nZögert nicht, mich zu informieren, wenn Ihr weitere Entdeckungen machen solltet... nun, da Ihr ein Zauberfeuerschneider seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[10833] = { id = 10833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Schattenzwirnschneider wird", description = "Wenn Ihr Euch auf die Schattenzwirnschneiderei spezialisiert, werdet Ihr doppelt so viel Schattenstoff wie ein gewöhnlicher Schneider herstellen können und Zugang zu exklusiven Mustern erhalten.\n\nNatürlich kann jeder Schneider den Altar der Schatten benutzen, aber ein Schattenzwirnschneider hat eine tiefere Verbindung zu dem Altar und entfesselt dadurch Mächte, die sich nur wenige vorstellen können.\n\nBringt diesen Kristall in das östliche Schattenmondtal und sucht den Netherschwingenpass, der von den Netherschwingenfeldern aus nach Süden führt. Nahe am Ende der Welt findet Ihr den Altar der Schatten. Benutzt dort den Kristall.", sourceObjective = "Benutzt den Kristall der tiefen Schatten in der Nähe des Altars der Schatten, um Eure Verbindung zu dem Altar zu stärken. Kehrt danach zu Andrion Dunkelweber im Unteren Viertel in Shattrath zurück.\n\nACHTUNG! Ihr könnt nur eine Schneidereispezialisierung auswählen.", completion = "Wie ich sehe war Euer Besuch beim Altar erfolgreich. Etwas an Euch hat sich verändert. Nur wenigen wird es auffallen, aber es ist ohne Zweifel da.", sourceObjectiveStatus = "unverified-source-field" }
quests[10834] = { id = 10834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grillok 'Finsterauge'", description = "Grillok Finsterauge hat einen Teil von sich den dunklen Mächten verpfändet und dafür große Macht erhalten. Sein verlorenes Auge brennt nun in irgendeiner teuflischen Grube als Schmuckstück eines Dämonen... und die Klappe, die seinen Verrat versteckt, hat ihr ganz eigenes dunkles Geheimnis.\n\nBringt mir Grilloks Augenklappe, {name}, und ich werde Euch fürstlich für Eure Dienste belohnen.", sourceObjective = "Tötet Grillok Finsterauge und bringt Grilloks Augenklappe zu Zezzak im Rückenbrecherposten.", progress = "Die Bösartigkeit der Orcs des Blutenden Auges kennt keine Grenzen und wird nur noch von der ihrer Vettern der Zerschmetterten Hand übertroffen.", completion = "Ah ja. Ich frage mich, ob Grillok in seinen dunklen, dunklen Träumen immer noch mit seinem verlorenen Auge verbunden ist, wie jemand, der eine Hand oder ein Bein in der Schlacht verloren hat...\n\nAuch ich werde davon träumen. Und wenn das Schicksal auf unserer Seite steht, werden wir dadurch erfahren, was Grillok und die Orcs des Blutenden Auges dazu gebracht hat, sich den Dämonen zu unterwerfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10835] = { id = 10835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apotheker Antonivich", description = "{name}, ich habe einen vorläufigen Bericht über meine Befunde bezüglich der Orcs des Blutenden Auges angefertigt. Mein Kollege in Thrallmar, Apotheker Antonivich, will ihn sicher gerne lesen. Auch er befasst sich mit dem Phänomen der Höllenorcs und hofft verhindern zu können, dass eine solche Tragödie auch unseren orcischen Verbündeten zustoßen könnte.\n\nBringt diesen Bericht zu ihm. Ich werde in der Zwischenzeit weiter das Blut, das Ihr mir gebracht habt, untersuchen. Wenn das Glück auf unserer Seite ist, können wir die Ursache für das Leiden der Höllenorcs herausfinden.", sourceObjective = "Bringt Albrecks Befund zu Apotheker Antonivich nach Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Guten Tag, {name}. Wie gefällt Euch Euer Aufenthalt auf der Höllenfeuerhalbinsel? Ich bin mir sicher, dass er sehr ergiebig ist...", completion = "Ah, ein Bericht von Albreck? Sehr gut. Die königliche Apothekervereinigung versucht verzweifelt herauszufinden, wie die Orcs der Höllenfeuerhalbinsel zu Höllenorcs geworden sind. Ihr Verrat ist unverzeihlich... und wir müssen sicherstellen, dass unsere Orcfreunde für alle Zeit vor dieser Verderbnis sicher sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[10836] = { id = 10836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterwanderung der Festung des Drachenmals", description = "Ich brauche Zeit, um einen Plan zu entwickeln, mit dem ich meine Kinder und mein Weibchen retten kann. Ihr werdet mir diese Zeit beschaffen, <Sterblicher/Sterbliche>.\n\nReist zur Festung des Drachenmals am östlichen Ende der Netherschwingenfelder und vernichtet alle Orcs des Drachenmals, die Ihr finden könnt. Das daraus resultierende Chaos und die Verwirrung sollte ihre Pläne maßgeblich beeinflussen.\n\nDoch seid auf der Hut. Einige meiner Art sind bereits von den Orcs des Drachenmals verderbt worden. Für sie besteht die einzige Erlösung im Tod. Ihr habt meine Erlaubnis, auch ihr Leben zu beenden.", sourceObjective = "Neltharaku, der hoch über den Netherschwingenfeldern im Schattenmondtal seine Kreise zieht, möchte, dass Ihr 15 Orcs des Drachenmals tötet.\n\nSämtliche Orcs des Drachenmals in der Festung des Drachenmals kommen dafür in Frage.", progress = "Ist es vollbracht? Ich hoffe nur, dass es noch nicht zu spät ist...", completion = "Gut gemacht, {name}. Ich habe einen Weg gefunden, wie wir die versklavten Drachen in der Festung des Drachenmals befreien können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10837] = { id = 10837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Netherschwingenscherbe!", description = "Ich glaube, dass ich die Netherrankenkristalle mit meiner eigenen Essenz erfüllen kann. Die Macht in diesen magieerfüllten Kristallen sollte ausreichen, um die versklavten Drachen aus den Klauen ihrer Meister zu befreien.\n\nReist zur Netherschwingenscherbe, einer Insel am zerbrochenen Rand des Schattenmondtals im Südosten. Auf der Netherschwingenscherbe könnt Ihr die Netherrankenkristalle finden. Kehrt zu mir zurück, wenn Ihr genügend Kristalle gefunden habt, um Eure Taschen damit zu füllen.\n\nUnd Vorsicht, {name}. Der Drachenmalklan hat sich nun auf der Insel niedergelassen.", sourceObjective = "Neltharaku, der hoch über den Netherschwingenfeldern im Schattenmondtal seine Kreise zieht, möchte, dass Ihr 12 Netherrankenkristalle auf der Netherschwingenscherbe sammelt.", progress = "Ich brauche Netherrankenkristalle.", completion = "<Neltharaku nimmt Euch die Kristalle ab.>\n\nIch werde nun die Kristalle mit meiner Magie erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10838] = { id = 10838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der dämonische Seher", description = "Der dämonische Seher ist nun bereit. Bringt ihn hinter die Höllenfeuerzitadelle, in das Höllenfeuerbecken, und platziert ihn dort auf dem Boden. Er wird sich dann selbst auf die Höllenfeuerzitadelle einstellen. Sprecht danach mit dem Seher und schreibt auf, was Ihr erfahrt. Bringt Euren Aufschrieb zu mir...\n\nGeht, {name}, aber erst, wenn Ihr bereit seid. Die Höllenfeuerzitadelle wird ohne Zweifel die Anwesenheit des Sehers entdecken und Wärter schicken, um ihn zu vernichten!", sourceObjective = "Benutzt den dämonischen Seher im Höllenfeuerbecken, wartet, bis er sich eingestellt hat und führt dann eine Messung durch.\n\nBringt den dämonischen Seher und die Messungen des dämonischen Sehers zu Apotheker Antonivich in Thrallmar.", progress = "Habt Ihr die Messung? War Euer Auftrag mit dem dämonischen Seher erfolgreich?", completion = "Ihr habt die Messung? Ausgezeichnet. Ich bin mir sicher, dass diese Daten sich für unsere Forschungen als unersetzlich erweisen werden. Ich werde sie gleich an Apothekerin Zelana und Apotheker Albreck weiterleiten.\n\nIhr solltet stolz auf Euch sein, {name}. Eure Stärke und Euer Mut steht außer Frage... genauso wie Eure Leistungen gegenüber der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[10839] = { id = 10839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelstein des Skithverstecks", description = "Das Skithversteck liegt nordwestlich der Karawane und südlich von Shattrath in einem Versteckten Hain im Wald. Man sagt, dass die Kolonie von Skettis dort einen bösartigen Altar der Verehrung errichtet hat. Wenn die Arakkoa der Skith jemals erlöst werden wollen, muss Terokks Dunkelstein zuerst geläutert werden.\n\nNehmt diese Rute der Läuterung und werft sie auf den Dunkelstein. Da sie von A'dal selbst gesegnet wurde, sollte die Reinheit der Rute stark genug sein, um den Dunkelstein zu reinigen. Nun geht. Möge das Licht über Euch wachen.", sourceObjective = "Benutzt die Rute der Läuterung bei Terokks Dunkelstein im Skithversteck und kehrt danach zu Kirrik den Erwachten bei der Flüchtlingskarawane in der Knochenwüste zurück.", progress = "Die Dunkelheit umgibt uns. Was habt Ihr mir aus dem Skithversteck zu berichten?", completion = "Ich habe bis hierher die Explosion hören können. Nicht mit meinen Ohren, sondern mit meinem Herzen.\n\nWenn die Berührung des gesegneten Naaru A'dal nicht ausreicht, um die Arakkoa zu erlösen, dann kann nichts auf der Welt das schaffen. Diejenigen, die ihre Seele nicht dem Licht ausgeliefert haben, sind nichts als Diener des Bösen.\n\nSie müssen vernichtet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10840] = { id = 10840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grab des Lichts", description = "Im Osten, unter dem versengten Sand, befindet sich das Grab des Lichts. Das Grab ist eine verlorene Ruhestätte unserer Toten. Bevor unsere Karawane überfallen wurde, war ich auf dem Weg zu dem Grab, um es von bösen Geistern zu befreien.\n\nIch hatte ja keine Ahnung, dass es bereits von einem anderen Übel heimgesucht wird. Sogar jetzt noch plündern die Astralen die Körper unsere Gefallenen, um an die Schmuckstücke und Andenken zu kommen, die den Toten vor Jahrhunderten mit ins Jenseits gegeben wurden.\n\nAber ich kann nichts dagegen unternehmen, solange unsere Karawane ums Überleben kämpft.", sourceObjective = "Hohepriester Orglum möchte, dass Ihr zum Grab des Lichts reist und 10 astrale Nethermanten und 10 astrale Brandschatzer tötet. Kehrt danach zu ihm zurück. Zu finden ist er bei der Flüchtlingskarawane.", completion = "Hier in der Wildnis der Scherbenwelt sind wir schwach. Nur wenige Helden verteidigen unsere Rechte, aber Ihr habt ihnen gezeigt, dass sie sich fürchten müssen, {class}. Ich glaube nicht, dass die Astralen Euren starken Arm so schnell vergessen werden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10842] = { id = 10842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rachsüchtige Seelen", description = "Das Grab des Lichts wurde vom Schattenrat verderbt und die toten Draenei wurden zu verfluchten Geistern, die von Zorn erfüllt sind und vor Hass auf die Lebenden brennen.\n\nBetretet das Grab", sourceObjective = "Hohepriester Orglum möchte, dass Ihr in das Grab des Lichts reist und 5 rachsüchtige Draenei besiegt.", progress = "Ihr habt uns alle gerettet. Wie können wir Euch nur danken?", completion = "Ihr könnt nicht wissen, was Ihr hier getan habt, {name}. Ihr habt so viele von uns aus einer ewigen Dunkelheit errettet. Ich kann nur wenig für die Lebenden tun und Euch nichts geben, das als Dank für Euch ausreichen würde. Nehmt Euch, was Euch nützlich erscheint.", sourceObjectiveStatus = "unverified-source-field" }
quests[10843] = { id = 10843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seit ich denken kann...", description = "Schon seit ich denken kann haben wir gegen die Oger der Speerspießer gekämpft.\n\nWir haben es geschafft, sie so weit zurück zu drängen, dass sie nun nur noch im Außenposten der Speerspießer vertreten sind. Dieser Außenposten befindet sich dort, wo Ihr herkommt, am südwestlichen Rand des Messergrats.\n\nBeweist mir Euren Wert, indem Ihr ihren Anführer Gnosh Brognat tötet.\n\nWollen wir mal sehen, aus welchem Holz Ihr geschnitzt seid, wenn es darum geht, die Oger zu bekämpfen.", sourceObjective = "Tötet Gnosh Brognat, den Anführer der Oger im Außenposten der Speerspießer.", completion = "<Leoroxx mustert Euch aufmerksam.>\n\nGnosh Brognats Tod ist ein Segen für alle Mok'Nathal. Das ist gut für Euch.\n\nMal schauen, ob Ihr immer noch so heldenhaft seid, wenn wir die Messlatte etwas anheben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10844] = { id = 10844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktionslager: Groll" }
quests[10845] = { id = 10845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet die Brutmutter", description = "Meine Jäger sind gerade von einer Aufklärungsmission im Singenden Bergrücken zurückgekehrt. Wie es aussieht hat sich die Zahl der Netherdrachen, die die Kristalle dort heimsuchen, deutlich vergrößert. Bald werden sie sich weiter ausbreiten!\n\nDa Ihr Euch als <fähiger/fähige:c> {class} herausgestellt habt, wollen wir einmal sehen, ob Eure Fertigkeiten einem ausgewachsenen Drachen gewachsen sind.\n\nIhr findet den Singenden Bergrücken, indem Ihr nach Süden durch die Schuppenflügelbank geht. Tötet ihre Brutmutter, Unheilschwinge.", sourceObjective = "Tötet Unheilschwinge.", completion = "Nein! Ihr habt Unheilschwinge getötet? Vielleicht habe ich mich in Euch getäuscht, {class}.\n\nVielleicht.\n\nDennoch habt Ihr die Anführer der drei größten Bedrohungen für unser Volk erschlagen. Darauf könnt Ihr stolz sein.\n\nIch werde Euch ein Zeichen meiner Wertschätzung geben, aber lasst es Euch nicht zu Kopf steigen. Ihr habt immer noch keine Ahnung davon, was es bedeutet, ein Mok'Nathal zu sein. Vielleicht werden wir immer noch auf Eure Fähigkeiten zurückkommen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10846] = { id = 10846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verständnis für die Mok'Nathal", description = "<Leoroxx schaut Euch mit einem Blick an, der Euch das Blut in den Adern gefrieren lässt.>\n\nIhr kommt zu den Mok'Nathal, aber Ihr versteht uns nicht. Ihr versteht unseren Kampf um Leben oder Tod nicht.\n\nWenn Ihr uns verstehen wollt, müsst Ihr Euch diesem Kampf aussetzen.\n\nIm Süden findet Ihr die Arakkoa der Vekh'nir. Sie halten eine Gruppe von Ogern in den Höhlen, die als Trogmas Besitz bekannt sind, als Sklaven. Dort findet Ihr auch ihren Anführer Vekh.\n\nTötet ihn!", sourceObjective = "Tötet Vekh, Anführer der Arakkoa der Vekh'nir.", completion = "Die Vekh'nir sind noch die harmlosesten unserer Feinde.\n\nIhr habt also einen übergroßen Vogel getötet. Das macht Euch noch lange nicht zu einem wahren Krieger. Das lässt Euch auch nicht unser Wesen verstehen.\n\nAber es ist ein Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[10847] = { id = 10847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen von Skettis", description = "Von den Klippen von Skettis zieht Unheil heraus.\n\nDas Schicksal meines Volkes, der Arakkoa, wird von einem unaussprechlichen Bösen verschleiert. Schon zu oft haben wir schwarze Magie für üble Taten eingesetzt. Durch A'dal erfuhren wir vom Licht und von der Erlösung.\n\nTerokk überwacht seine Kolonien von Skettis aus mithilfe von Sphären, die er mit seiner schwarzen Kunst verzaubert hat. Stehlt diese Augen aus dem Reskkversteck und dem Shienorversteck im nördlichen Terokkar. Ich möchte sehen können, was Terokk sieht. Lasst mich durch die Augen von Skettis schauen.", sourceObjective = "Bringt das Auge des Reskkverstecks und das Auge des Shienorverstecks zu Rilak dem Erlösten im Unteren Viertel von Shattrath.", progress = "Ihr seid zurück, {class}. Welche Neuigkeiten bringt Ihr?", completion = "Euer Mut sollte belohnt werden. Die Wachen von Skettis rücken ihre Besitztümer nur ungern heraus.\n\nAber die Heldentaten der Vergangenheit sind nun nicht von Belang. Wir sollten uns lieber darum kümmern, dass dieser Heldenmut auch in der Zukunft weiter herrscht, denn Terokks Blick richtet sich gen Süden.\n\nDiese Augen sehen alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[10848] = { id = 10848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das untote Böse des Rhazeverstecks", description = "Das Rhazeversteck war eine besonders bösartige Kolonie von Skettis.\n\nTrotz der Auslöschung seiner Bewohner durch die Katastrophe von Auchindoun hielt Terokk seinen Einfluss auf die bösartigen Geister dort aufrecht. Reist nach Westen zum Rhazeversteck und tötet diese mörderischen Schufte. Ihr findet sie westlich des Schattengrabs, an der Grenze zwischen der Knochenwüste und den Wäldern von Terokkar.\n\nDies wird unser erster Schlag gegen Terokk und die Wächter von Skettis werden.", sourceObjective = "Tötet 4 Todeskrallengeister, 4 kreischende Geister und 2 Geistraben und kehrt danach zu Kirrik den Erwachten bei der Flüchtlingskarawane zurück.", completion = "Diese verderbten Geister haben es verdient zu sterben. Der Tod, den sie über alle anderen gebracht hätten, ist dafür Grund genug.\n\nEs besteht keine Hoffnung, dass wir die, die unter Terokks Einfluss stehen, erlösen können. Aber wir werden ihnen im Namen des Lichts ein Ende setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10849] = { id = 10849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Kirrik", description = "Es waren noch andere Arakkoa an dem Verrat an Terokk beteiligt.\n\nKirrik erkannte in Terokk einen Scharlatan und keinen Propheten. Die einzige Prophezeiung, die Terokk vorausgesehen hat, war das Verderben, das auf seinen eigenen Wunsch heraufbeschworen wurde.\n\nEs war Kirrik, der uns mutig aus Skettis herausgeführt hat. Nach unserer Pilgerreise nach Shattrath ging Kirrik in alle anderen Kolonien, um nach Gleichgesinnten zu suchen.\n\nIn diesem Schreiben steht, was die Augen gesehen haben. Kirrik muss davon erfahren! Folgt der Straße nach Süden aus Shattrath hinaus zu der Knochenwüste und haltet nach der Karawane Ausschau.", sourceObjective = "Bringt Rilaks Schreiben zu Kirrik den Erwachten bei der Flüchtlingskarawane in der Knochenwüste.", progress = "Ihr seid weit gereist und bringt mir Nachrichten.", completion = "Rilaks Geschichte ist grausam, Reisender. Wie Ihr am Zustand der Karawane sehen könnt, gibt es dieser Tage viel Leid und Düsterkeit in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10850] = { id = 10850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nethergas in einem Teufelsfeuermotor", progress = "Ihr findet die Öffnung, durch die der Teufelshäscher betankt wird.", completion = "Als Ihr den falschen Treibstoff einfüllt, beginnt der Motor des Teufelshäschers zu rumpeln und zu stottern." }
quests[10851] = { id = 10851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Totems meines Feindes", description = "Es gibt solche Wege, die Ahnen zu ehren, und es gibt andere Wege.\n\nDie Oger der Speerspießer tragen Totems bei sich, aber sie benutzten sie nicht, um ihre Ehrfurcht auszudrücken. Stattdessen wollen sie damit manipulieren und kontrollieren.\n\nWir sollten ihre Totems stehlen, denn sie sind unwürdig! Wir werden eine bessere Verwendung für sie finden.\n\nGeht zum Außenposten der Speerspießer im Westen, südwestlich des Messergrats. Erschlagt die Mystiker und Zermalmer der Speerspießer und nehmt ihnen die Totems ab!", sourceObjective = "Sammelt 5 Totems der Speerspießer.", progress = "Wart Ihr im Außenposten der Speerspießer und habt ihnen die Totems abgenommen?", completion = "Das sieht nach einer guten Sammlung aus. Wir sollten einen Weg finden können, sie respektvoll einzusetzen.\n\nIn der Tat habe ich sogar schon eine Idee!", sourceObjectiveStatus = "unverified-source-field" }
quests[10852] = { id = 10852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisste Freunde", description = "Wir haben uns hier niedergelassen, weil des Nachts ein paar Kerle kamen und Radau gemacht haben. Es war gruselig. Ich weiß nicht, wann wir weitergehen werden.\n\nEinige meiner Freunde fehlen. Ich habe keine Ahnung, wo sie sind. Ich fürchte, diese schauerlichen Vogelmänner haben sie mit nach Nordwesten genommen. Wahrscheinlich haben sie sie in Käfige eingesperrt und all so was. Es wäre toll, wenn Ihr sie finden könntet. Ich mache mir Sorgen um sie.", sourceObjective = "Ethan möchte, dass Ihr 12 seiner vermissten Freunde im Skithversteck findet und sie zu ihm bei der Flüchtlingskarawane zurückbringt.", completion = "Ihr habt all meine Freunde gefunden! Jetzt habe ich wieder jemanden, der mit mir spielt. Vielen Dank, Herr {name}.\n\nDa ich jetzt wieder andere Kinder zum Spielen habe, könnt Ihr ja eins meiner Spielzeuge haben. Dann habt Ihr auch etwas zum Spielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10853] = { id = 10853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisteranrufung", description = "Die Geister der Netherdrachen im Singenden Bergrücken müssen befreit werden.\n\nDie Netherdrachen waren nicht immer Netherdrachen. Einst waren sie schwarze Drachen.\n\nDoch dann schwappte mit der Zerstörung dieser Welt eine Welle von Netherenergie über alles und veränderte die Eier der Drachlinge.\n\nSeitdem ist ihr eigenes Ich verzerrt. Wir müssen ihnen helfen, Frieden zu finden.\n\nDas erreicht Ihr, indem Ihr einen Drachen in der Nähe des Totems der Geisteranrufung tötet und ihm dann seine Seele nehmt.", sourceObjective = "Benutzt das Totem der Geisteranrufung, um 8 Geister eines geringen Netherdrachen zu sammeln.", progress = "Die Drachen des singenden Bergrückens sind vielleicht eine Bedrohung für uns, doch sie sind majestätische Wesen.\n\nOder sie waren es zumindest. Ich hoffe, dass Ihr ihre Geister retten könnt.\n\nUnd falls Ihr noch mehr Totems brauchen solltet, habe ich noch ein paar über.", completion = "Ihr habt heute eine große Tat vollbracht, {class}. Die Geister der Drachen werden nun wieder singen können, denn sie sind frei. Und die Überreste ihrer Geister, die sie hinterlassen, dienen als mächtiges Heilmittel.\n\nHabt Ihr vielleicht Lust auf eine Reise in den Norden? Es gibt da eine Sache im Zusammenhang mit den Astralen, die mich brennend interessiert.\n\nIch fühle großen Schmerz aus dieser Richtung kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10854] = { id = 10854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht Neltharakus", description = "Nehmt diesen verzauberten Netherrankenkristall und begebt Euch zurück zur Festung des Drachenmals. Sucht nach den versklavten Drachen, wenn Ihr angekommen seid, und setzt die Magie des Kristalls frei. Meine eigenen Energien werden dafür sorgen, dass die Drachen ihre Fesseln abwerfen können. Wenn Ihr seht, dass ein Drache freigekommen ist, helft ihm schnell seinen Kerkermeister zu vernichten! Sie sind von der Gefangenschaft sicherlich noch geschwächt.\n\nLasst alle frei, die Ihr finden könnt und kehrt dann zu mir zurück, {name}!", sourceObjective = "Neltharaku, der hoch über den Netherschwingenfeldern im Schattenmondtal seine Kreise zieht, möchte, dass Ihr 5 versklavte Drachen der Netherschwingen befreit.", progress = "Verschwendet keine Zeit, wir haben viel zu tun!", completion = "<Neltharaku lacht.>\n\nDie Orcs müssen einen ganz schönen Schreck bekommen haben, als die Drachen sich plötzlich gegen sie gewendet haben. Gut gemacht, {name}. Vielleicht seid Ihr wirklich der Held unseres Schwarms.", sourceObjectiveStatus = "unverified-source-field" }
quests[10855] = { id = 10855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelshäscher, nein Danke!", description = "Ah ja, der Teufelshäscher! Das ist sicherlich die schrecklichste mechanische Erfindung der Legion. Und nicht weniger als drei dieser Abscheulichkeiten sind direkt auf die Sturmsäule gerichtet.\n\nZu unserem Glück sind sie noch nicht aktiviert. Das gibt uns die Möglichkeit, dieses Problem mit Sabotage anstatt mit roher Gewalt zu lösen.\n\nBeschafft Euch kondensiertes Nethergas von den Gan'arg in der Konstruktionsbasis: Vergessenheit und füllt es in den Tank eines Teufelshäschers. Ich glaube, sein Motor wird sich nicht allzu sehr darüber freuen.", sourceObjective = "Beschafft Euch 5 Einheiten kondensiertes Nethergas von den Robogenieuren der Gan'arg in der Konstruktionsbasis: Vergessenheit und füllt sie in einen deaktivierten Teufelshäscher. Kehrt danach zu Netherpirscher Nauthis zurück.", completion = "Das sind ausgezeichnete Nachrichten, {name}. Jetzt, da wir wissen, wie wir mit ihnen zu verfahren haben, kann ich ein paar Leute anheuern, um die übrigen Häscher zu sabotieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10856] = { id = 10856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die beste Verteidigung", description = "Mutige Industriesabotage wird uns leider nur bis zu einem gewissen Punkt weiterbringen, {name}. Genauso wie die Konstruktionsbasis: Vergessenheit als Produktionsstätte für die Teufelshäscher dient, ist die Konstruktionsbasis: Gehenna sowohl ein Stützpunkt für ihre Armee, als auch der Ort, an dem sich die meisten Teleporter der Legion befinden.\n\nIch möchte, dass Ihr dorthin geht, und ihre Zahl tüchtig verringert. Bis heute müssen sie ein volles Regiment von Zornschaffern angesammelt haben. Das dürfen wir nicht zulassen!", sourceObjective = "Netherpirscher Nauthis möchte, dass Ihr 12 Zornschaffer in der Konstruktionsbasis: Gehenna nördlich der Sturmsäule vernichtet.", completion = "Gute Arbeit, {name}. Macht weiter so, dann werde ich beim Nexusprinzen ein gutes Wort für Euch einlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10857] = { id = 10857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teleportiert das!", description = "So lustig es auch sein mag, Dämonen zu töten, so wenig hilft es uns, wenn die Legion weiterhin ihre Teleporter benutzen kann, um jeden Dämon, den wir töten, zu ersetzen.\n\nUnglücklicherweise habe ich gerade keinen hochwertigen Sprengstoff zur Hand... aber die Mo'arg, die die Teleporter warten, schon!\n\nNehmt diesen Stab... Ich habe seine Kraft so eingestellt, dass er die Gehirnströme der Mo'arg beeinflussen kann. Kehrt zur Konstruktionsbasis: Gehenna zurück und beeinflusst jeden Mo'arg, den Ihr seht. Viel Zeit bleibt Euch nicht, aber sie wird reichen, um ihre Sprengladungen bei den Teleportern in der Nähe zu benutzen.", sourceObjective = "Netherpirscher Nauthis möchte, dass Ihr den Stab der geistigen Beeinflussung bei den Mo'arg in der Konstruktionsbasis: Gehenna einsetzt und ihre Fähigkeit 'Teleporter sprengen' bei den drei Teleportern in der Konstruktionsbasis benutzt.", progress = "Ist es vollbracht? Sind die Teleporter außer Gefecht?", completion = "Dank Euch kann ich wieder etwas durchatmen, {name}. Das meine ich natürlich im übertragenen Sinne!\n\nIch nehme an, Ihr wollt nun eine Art Belohnung, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[10858] = { id = 10858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karynaku", description = "Ich schäme mich, Euch erneut um Hilfe zu bitten, {name}, aber Ihr seid die einzige Hoffnung meines Schwarms. Ohne mein Weibchen stirbt die Brut der Netherschwingen vielleicht ganz aus!\n\nMacht Euch auf den Weg zur Spitze der Festung des Drachenmals und findet Karynaku.\n\nWir werden über Euch fliegen. Sollte sich ein Loch in ihrer Verteidigung auftun, wird die geballte Macht der Netherschwingen Euch zu Hilfe eilen.", sourceObjective = "Sucht nach Karynaku in der Festung des Drachenmals.", completion = "Es sind die Ketten. Sie berauben mich meiner Macht. Der einzige Ausweg ist, den Schlüssel von Zuluhed zu beschaffen und mich loszuketten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10859] = { id = 10859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelt die Kugeln", description = "Die Astralen der Razaani haben merkwürdige Geräte, aus denen kleine, rosafarbene schwebende Lichtkugeln herauskommen. Sie erinnern mich an Seelen.\n\nMan darf sie nicht mit den großen gelben Kugeln verwechseln, die sich aus den Astralen lösen, wenn sie sterben. Diese hier sind ganz anders.\n\nIch möchte, dass Ihr nach Norden zu Razaans Landeplatz geht und ein paar Totems aufstellt, die die rosafarbenen Lichtkugeln anziehen.\n\nBringt sie zu mir zurück, damit ich genau herausfinden kann, aus was sie bestehen.", sourceObjective = "Benutzt das Kugelfängertotem, um 15 Lichtkugeln der Razaani zu sammeln.", progress = "Habt Ihr alle Lichtkugeln der Razaani, die ich brauche, gesammelt?", completion = "Etwas fühlt sich hier falsch an.\n\nBitte, {name}, reicht mir das Totem. Ich muss diese Kugeln untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10860] = { id = 10860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leckerbissen der Mok'Nathal", description = "Seid Ihr hungrig, {race}? Der große Geist hilft denen, die sich selbst helfen. Wenn Ihr Euch ein Essen verdienen wollt, schlage ich vor, dass Ihr zuhört, denn Braagor da drüben wird Euch nichts umsonst geben, zumindest nichts, was so schmackhaft wäre.\n\nDie Raptoren und Schuppenflügel des Messergrats und der Schuppenflügelbank haben alles, was man für zwei der schmackhaftesten Gerichte, die Ihr je zu essen bekommen werdet, braucht. Bringt mir ihre Raptorenrippchen und das Schlangenfleisch, und ich werde Euch beide zubereiten.\n\nIch kann Euch auch beibringen, sie selbst zu kochen, wenn Ihr in Eile seid.", sourceObjective = "Sammelt 3 Raptorenrippchen und 3 Stück Schlangenfleisch.", progress = "Habt Ihr alle Zutaten schon? Darüber zu reden hat mir das Wasser im Munde zusammenlaufen lassen!", completion = "Mmm, ich kann sie schon schmecken! Schnell, reicht mir die Zutaten... Ich werde sie rasch klein würfeln und dann ab damit aufs Feuer!\n\nZu Eurem Glück hält sich das Zeug lange, und ich meine damit sehr lange! So, nehmt dies. Und da Ihr so freundlich wart, meine Speisekammer aufzufüllen, gebe ich Euch die Rezepte gleich noch dazu.", sourceObjectiveStatus = "unverified-source-field" }
quests[10861] = { id = 10861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Präventivschlag gegen das Lithicversteck", description = "In der verachtungswürdigen Kolonie im Südwesten, die als Lithicversteck bekannt ist, versuchen die Diener Terokks ihre geflügelten Brüder schon vor dem Schlüpfen zu verderben. Die schwarzen Zauberer von Lithic belegen die Eier mit einem schattenhaften Fluch. Wenn die Küken schlüpfen, sind sie bereits willenlose Diener Terokks.\n\nReist ins Lithicversteck und zerbrecht die Eier, bevor der Fluch wirken kann. Sogar wenn es dazu schon zu spät ist, könnt Ihr die verderbten Eier vernichten.\n\nDenkt daran, in der Dunkelheit strahlt das Licht noch heller.", sourceObjective = "Zerbrecht die verfluchten Eier im Lithicversteck. Erlöst 3 Jungtiere und tötet 3 bösartige Jungtiere. Kehrt danach zu Kirrik den Erwachten bei der Flüchtlingskarawane zurück.", completion = "Es ist eine grausame Aufgabe, Jungtiere zu quälen, und doch wäre es unverzeihlich, das wachsende Böse zu ignorieren. Ihr habt gute Arbeit geleistet. A'dals Gunst leuchtet auf Euch herab.", sourceObjectiveStatus = "unverified-source-field" }
quests[10862] = { id = 10862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auslieferung an die Horde", description = "Die feigen Arakkoa greifen uns täglich an. Sie lauern unseren Jägern auf und plündern ab und an sogar innerhalb unserer Stadtmauern! Wir töten sie, wenn wir können, aber ihre Magie ist stark und sie schaffen es oft, unseren Truppen zu entkommen.\n\nIch habe erfahren, dass einige Arakkoa der Horde gegenüber freundlich gesonnen sein sollen. Sie leben in Shattrath im Nordwesten. Ihr Anführer nennt sich Rilak der Erlöste. Sucht im Unteren Viertel nach ihm und fordert ihn auf, sich auszuliefern.", sourceObjective = "Rokag möchte, dass Ihr Rilak den Erlösten im Unteren Viertel von Shattrath aufsucht und von ihm fordert, dass er und sein Volk sich der Horde ausliefern.", completion = "Euer Volk ist wütend, aber ich kann nicht viel dagegen tun. Einige von uns wurden von der Macht der Naaru berührt und für alle Zeiten verändert. Doch diejenigen von uns, die in der Wildnis leben, sind noch immer so, wie wir damals waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10863] = { id = 10863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Arakkoa", description = "Hier an der Front müssen wir uns Tag für Tag mit den Arakkoa herumschlagen. Sie greifen uns an, wenn es ihnen gerade passt, plündern unsere Vorräte und erschlagen unsere Späher.\n\nUnd doch wissen wir nur wenig über diese rätselhaften Kreaturen. Ich habe Informationen erhalten, denen zufolge in Shattrath im Nordwesten einige Arakkoa leben sollen, die nicht so feindselig sind und vielleicht die Geheimnisse ihres Volks mit uns zu teilen bereit sind.\n\nRilak der Erlöste ist ihr Anführer. Er lebt im Norden des Unteren Viertels.", sourceObjective = "Lady Dena Kennedy möchte, dass Ihr Rilak den Erlösten im Unteren Viertel von Shattrath aufsucht und herausfindet, welche Geheimnisse der Arakkoa mit Euch teilen wird.", completion = "Es war sehr weise von Euch, mich aufzusuchen. Es gibt vieles, was ich Euch zeigen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10864] = { id = 10864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Last auf der Seele", description = "Ich habe ein Gerät, mit dem man Teufelsmagie analysieren kann, der dämonische Seher. Ich würde Euch den Seher ja benutzen lassen, aber zunächst müsst Ihr ihn... besänftigen. Ihr müsst wissen, dass innerhalb des Sehers ein Wesen von höchster Intelligenz steckt, das einige, sagen wir, exzentrische Bedürfnisse hat.\n\nUm den Seher zu besänftigen, müsst Ihr Orcs töten, insbesondere die Orcs der Zerschmetterten Hand. Der Seher verlangt ihre Seelen.\n\nKehrt zu mir zurück, wenn Ihr die Seelen geerntet habt. Ihr findet die Orcs nördlich, südlich und um die Höllenfeuerzitadelle herum.", sourceObjective = "Tötet 20 Orcs der Zerschmetterten Hand und kehrt danach zu Apotheker Antonivich in Thrallmar zurück.", progress = "Der dämonische Seher ist noch nicht besänftigt, {name}. Kehrt zu mir zurück, nachdem Ihr die Seelen der Orcs der Zerschmetterten Hand geerntet habt.", completion = "Gut gemacht, {name}. Eure Seele ist mit vielen Toden belastet... und der dämonische Seher wird nun seine Pflicht für Euch erfüllen.\n\nWollen wir hoffen, dass Ihr für das Folgende gewappnet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10865] = { id = 10865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informiert Leoroxx!", description = "Schnell, Ihr müsst Leoroxx über die Geschehnisse bei Razaans Landeplatz informieren.\n\nDiese Kugeln wurden aus Seelen geschaffen, einige davon Seelen der Mok'Nathal!", sourceObjective = "Sprecht mit Leoroxx darüber, was die Astralen der Razaani treiben. Ihr findet ihn im Dorf der Mok'Nathal im Schergrat.", completion = "Ist das, was Ihr da sagt, überhaupt möglich? Was sage ich da? Natürlich ist es das, wenn der Geistrufer davon überzeugt ist.\n\nErinnert Ihr Euch noch, als ich sagte, dass wir vielleicht wieder Eure Hilfe brauchen würden? Wie es scheint, kann ich in die Zukunft sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10866] = { id = 10866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuluhed der Geschlagene", description = "Er versteckt sich in meinen Gedanken, <Sterblicher/Sterbliche>. Er wartet darauf, dass ich zerbreche... mich seinem Willen unterwerfe.\n\nUnd das wird sein Untergang sein. Ich werde ihn rufen. Ich werde ihm sagen, dass ich tue, was er verlangt. Wenn er erscheint, müsst Ihr ihn töten und den Schlüssel nehmen!\n\nSeid gewarnt: Zuluhed ist ein uralter Orc mit ungeahnten Kräften. Sicher hat Illidan seine Macht noch weiter verstärkt. Ihr riskiert Euer Leben, wenn Ihr tut, worum ich euch bitte. Seid Ihr sicher, dass Ihr ein solches Opfer bringen wollt?", sourceObjective = "Tötet Zuluhed den Geschlagenen und beschafft Euch Zuluheds Schlüssel. Benutzt Zuluheds Schlüssel, um Zuluheds Fesseln zu öffnen und Karynaku zu befreien.", progress = "<Karynaku brüllt.>", completion = "Ich bin frei! Ihr habt uns gerettet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10867] = { id = 10867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es kann nur eine Antwort geben", description = "Es kann nur eine Antwort auf diese... diese SCHÄNDUNG der Seelen unserer Vorfahren geben!\n\n{name}, wenn Ihr uns helfen wollt, die Seelen unserer verehrten Toten zu ihrem richtigen Platz zurück zu bringen, dann kehrt zu Razaans Landeplatz zurück.\n\nGeht dorthin zurück und tötet die Razaani bis ihr Anführer, Nexusprinz Razaan, sein feiges Gesicht zeigt. Tötet ihn, beschafft Euch die Seelen zurück und übergebt sie Geistrufer Dohgar!", sourceObjective = "Beschafft Euch die Seelensammlung.", progress = "Habt Ihr es getan? Sind die Seelen unserer Vorfahren sicher vom Bösen der Astralen?", completion = "Es ist gut, dass der Abschaum der Astralen und ihr Anführer tot sind. Ich wünsche ihren Brüdern tausend Plagen auf den Hals!\n\nIhr sollt für Eure Taten im Namen aller Mok'Nathal belohnt werden, {name}! Ihr seid wirklich ein Held für uns!\n\nLasst uns nun die Seelen unserer Vorfahren dem reinigenden Feuer übergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10868] = { id = 10868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegspfad der Arakkoa", description = "Die Arakkoa haben uns erneut angegriffen, dieses Mal bei Nacht. Sie haben ihre dunkle Magie eingesetzt, um zu entkommen, bevor wir losstürmen und ihnen Auge in Auge entgegentreten konnten. Sie benutzen ihre Beschwörungskreise, um ihre Krieger von dem sicheren Tod zu retten, aber wenn wir ihr Zuhause angreifen, können sie uns nicht entkommen. Das Reskkversteck und das Shienorversteck liegen im Norden und Nordosten.\n\nSucht diese Nester der Arakkoa und tötet so viele, wie Ihr könnt.", sourceObjective = "Beraterin Faila bittet Euch, 14 Krallaniere der Shienor und 6 Zauberer der Shienor zu töten. Kehrt danach zu ihr in der Steinbrecherfeste zurück.", completion = "Gut gemacht, {class}. Die Arakkoa haben gelernt, die Macht der Horde zu fürchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10869] = { id = 10869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herde ausdünnen", description = "Die Arakkoa haben uns erneut angegriffen, dieses Mal bei Nacht. Sie haben ihre dunkle Magie eingesetzt, um zu entkommen, bevor wir unsere Soldaten losschicken konnten.\n\nDas Reskkversteck und das Shienorversteck liegen im Norden und Nordwesten. Sucht diese Nester der Arakkoa und tötet so viele, wie Ihr könnt. Vielleicht fürchten sie uns nicht, aber wir können ihre Zahl dennoch verringern!", sourceObjective = "Leutnant Kieshammer bittet Euch, 14 Krallaniere der Shienor und 6 Zauberer der Shienor zu töten. Kehrt danach zu ihm in Allerias Feste zurück.", completion = "Gut gemacht, {class}. Die Arakkoa haben gelernt, die Macht der Allianz zu fürchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10870] = { id = 10870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündeter der Netherschwingen", description = "Erlaubt mir, Euch zu Mordenai zurück zu bringen. Ich bin mir sicher, dass er Euch nochmals sehen möchte.", sourceObjective = "Lasst Euch von Karynaku zurück zu Mordenai in den Netherschwingenfeldern bringen.", completion = "Ihr habt Euch als Verbündeter der Netherschwingen erwiesen. Meine Mutter ist frei und meine Brüder und Schwestern gerettet!\n\nVielleicht werde ich Euch eines Tages erneut rufen. Wenn dieser Tag kommt, werdet Ihr mit offenen Armen begrüßt werden, als Bruder des Drachenschwarms der Netherschwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10871] = { id = 10871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündeter der Netherschwingen", description = "Erlaubt mir, euch zu Mordenai zurück zu bringen. Ich bin mir sicher, dass er Euch nochmals sehen möchte.", sourceObjective = "Lasst Euch von Karynaku zurück zu Mordenai in den Netherschwingenfeldern bringen.", completion = "Ihr habt Euch als Verbündeter der Netherschwingen erwiesen. Meine Mutter ist frei und meine Brüder und Schwestern gerettet!\n\nVielleicht werde ich Euch eines Tages erneut rufen. Wenn dieser Tag kommt, werdet Ihr mit offenen Armen begrüßt werden, als Bruder des Drachenschwarms der Netherschwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10872] = { id = 10872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuluhed der Geschlagene", description = "Er versteckt sich in meinen Gedanken, <Sterblicher/Sterbliche>. Er wartet darauf, dass ich zerbreche... mich seinem Willen unterwerfe.\n\nUnd das wird sein Untergang sein. Ich werde ihn rufen. Ich werde ihm sagen, dass ich tue, was er verlangt. Wenn er erscheint, müsst Ihr ihn töten und den Schlüssel nehmen!\n\nSeid gewarnt: Zuluhed ist ein uralter Orc mit ungeahnten Kräften. Sicher hat Illidan seine Macht noch weiter verstärkt. Ihr riskiert Euer Leben, wenn Ihr tut, worum ich euch bitte. Seid Ihr sicher, dass Ihr ein solches Opfer bringen wollt?", sourceObjective = "Tötet Zuluhed den Geschlagenen und beschafft Euch Zuluheds Schlüssel. Benutzt Zuluheds Schlüssel, um Zuluheds Fesseln zu öffnen und Karynaku zu befreien.", completion = "Ich bin frei! Ihr habt uns gerettet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10873] = { id = 10873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei Nacht verschleppt", description = "Unser kleiner Außenposten wird ständig angegriffen. Vor ein paar Nächten haben die Spinnen des Netherweberkamms, der am südöstlichen Ende der Knochenwüste liegt, unser Lager überfallen. Sie haben viele von uns vergiftet, in ihre Netze gewickelt und fort getragen. Einige unserer Krieger haben zu den Waffen gegriffen und sind den Spinnen todesmutig in die finstere Nacht gefolgt.\n\nWir haben weder die Gefangenen noch die Krieger seit diesem Tag wieder gesehen. Wir hoffen, dass sie noch am Leben sind. Vielleicht halten die Spinnen sie gefangen? Wir sind nur so wenige. Könnt Ihr nach unseren Leuten suchen?", sourceObjective = "Späher Navrin möchte, dass Ihr zum Netherweberkamm reist und 6 eingesponnene Verteidiger der Sha'tar befreit. Kehrt danach zu Navrin ins Basislager der Sha'tari zurück.", completion = "Ihr habt so viele gerettet. Ich habe nicht geglaubt, dass wir sie je wieder sehen würden. Wir können Euch nicht genug danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10874] = { id = 10874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signalfeuer des Shalasverstecks", description = "Über der Knochenwüste im Osten wirft Skettis, der lange Arm Terokks, bedrohlich seine Schatten. Am Fuße von Skettis liegt das Shalasversteck, Terokks vortrefflichste Kolonie. Von diesem Stützpunkt aus führen Terokks Diener Krieg gegen das Licht.\n\nDie Unholde der Shalas kommunizieren über ein komplexes System aus magischen Signalfeuern mit ihrem Meister. Reist nach Osten, {race}, und löscht die Feuer. Sobald das Shalasversteck zum Schweigen gebracht wurde, können wir den Fall von Skettis planen.\n\nAber ich greife mir selbst vor.", sourceObjective = "Kirrik der Erwachte bei der Flüchtlingskarawane möchte, dass Ihr die vier Signalfeuer des Shalasverstecks löscht.", completion = "Wir haben gesehen, wie der verfluchte Rauch aufgestiegen ist. Ihr seid außergewöhnlich mutig, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10875] = { id = 10875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an Nazgrel", description = "{name}, während Eures Auftrags mit dem dämonischen Seher habe ich einen Bericht über Eure Taten gegen die Höllenorcs geschickt. Nazgrel, unser berühmter Anführer in Thrallmar, möchte mit Euch sprechen. Ich glaube, er hat einen blutigen Auftrag für Euch...", sourceObjective = "Sprecht mit Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", completion = "Es ist schön, von Euren Schachzügen gegen die Höllenorcs zu erfahren, {name}. Die Apotheker haben viel Zeit und viel Mühe aufgewendet, um hinter den Grund der Verderbnis zu kommen, und auch wenn diese Informationen sicher unersetzlich sind... schreit mein Orcblut danach, diesen Verrätern einen anständigen Schlag zu verpassen!\n\nHört genau zu, wenn ich Euch Eure Aufgabe erkläre...", sourceObjectiveStatus = "unverified-source-field" }
quests[10876] = { id = 10876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Fuße der Zitadelle", description = "Truppenkommandant Gorax trainiert die Hauptmänner am Fuß der Höllenfeuerzitadelle und drillt sie, bis sie so scharf wie Rasierklingen sind. Ihr müsst ihn töten, {name}. Sein Verlust wäre ein großer Schaden für die Höllenorcs.\n\nDas ist jedoch nicht alles, was Ihr tun müsst.\n\nNehmt dieses Banner. Platziert es auf Gorax' Leichnam. Wenn auch nur ein Tropfen echtes Orcblut in seinem Körper steckt, muss sein Kommandant, die Hand von Kargath, Eure Herausforderung annehmen!\n\nSein Kopf, der Kopf der Hand von Kargath, ist das, was ich begehre.", sourceObjective = "Tötet Truppenkommandant Gorax, platziert die Herausforderung der Horde auf seinem Leichnam. Tötet danach die Hand von Kargath und bringt den Kopf der Hand von Kargath zu Nazgrel in Thrallmar.", progress = "Habt Ihr Euch der Hand von Kargath gestellt, {name}?", completion = "Ihr habt eine große Tat geleistet, {name}. Die Höllenorcs sind eine Schande für alle wahren Orcs. Wenn wir eine Angst haben, so ist es die, erneut einer dämonischen Verderbnis zu verfallen. Unser Krieg gegen die Höllenorcs ist also mehr als nur eine Schlacht gegen schlimme Feinde, es ist eine Schlacht in uns selbst.\n\nUnd mit einer Stärke, wie Ihr sie heute bewiesen habt, werden wir diese Schlacht gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10877] = { id = 10877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schreckensrelikt", description = "Vor langer Zeit machte sich eine Karawane auf den Weg nach Auchindoun mit der Mission, ein Schreckensrelikt aus den uralten Gräbern unter der Stadt der Toten zu bergen. Sie sind geflohen, aber das Relikt sollte ihr Untergang sein. Das Relikt ist böse und ruft Böses herbei, wenn es berührt wird. Ihre Karawane wurde irgendwo im Osten vernichtet.\n\nDieses finstere Artefakt ist der Schlüssel zu meinem schrecklichen Plan, Teribus den Verfluchten zu töten, eine Kreatur, die über der Knochenwüste ihre Kreise zieht. Wenn Ihr wünscht, könnt Ihr mir helfen, aber Euer Leben und Eure Seele stehen dabei auf dem Spiel.", sourceObjective = "Oakun möchte, dass Ihr nach Osten zur Herrenlosen Karawane reist und das Schreckensrelikt besorgt. Kehrt zu Oakun zurück, wenn Eure Aufgabe erledigt ist.", progress = "Habt Ihr das Schreckensrelikt? Wir müssen es bekommen.", completion = "Es ist unglaublich, dass Ihr es geschafft habt. Das Schreckensrelikt ist viel mächtiger, als ich befürchtet hatte. Nur ein starker Held hätte die lange Rückreise mit so einem blasphemischen Gegenstand überlebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10878] = { id = 10878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bevor die Dunkelheit sich senkt", description = "Nachdem unsere Karawane einem Angriff von Kultisten der Kabale des Schattenrats zum Opfer gefallen ist, wurden Späher auf der Suche nach Hilfe nach Shattrath geschickt. Die Wachen denken, wir sind vorerst sicher, aber sie unterschätzen diese Verrückten.\n\nIch freue mich jedenfalls nicht darauf, mir meine Kehle von irgendeinem Initianden der Kabale mitten in der Nacht durchschneiden zu lassen. Tut uns allen einen Gefallen und greift sie an, bevor sie es tun.\n\nIhr findet unsere Angreifer südlich von hier, am nördlichen Eingang von Auchindoun.", sourceObjective = "Mekeda bei der Flüchtlingskarawane möchte, dass Ihr 8 Scharmützler der Kabale, 4 Zauberwirker der Kabale und 2 Initianden der Kabale tötet.", completion = "Vorerst kann ich erleichtert durchatmen, {name}. Der Schattenrat wird sich bis auf weiteres zurückhalten.\n\nSie sind Mörder und Feiglinge. Eure Zurschaustellung von Mut wird sie einschüchtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[10879] = { id = 10879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offensive aus Skettis", description = "Skettis hat uns den Krieg erklärt! Habt Ihr genug Kraft für die Verteidigung Shattraths gesammelt?\n\nHaltet die Angreifer auf!", sourceObjective = "Haltet die Angreifer auf und sprecht mit Rilak den Erlösten.", progress = "Wir haben jetzt keine Zeit für einen Plausch, {name}. Wir werden angegriffen! Haltet die Eindringlinge auf!", completion = "Ich ziehe meinen Hut vor Euren Kampfkünsten, {class}. Ihr habt Euch als wahrer Verteidiger des Lichts bewiesen. Möge A'dals Segen in Euren dunkelsten Stunden auf Euch ruhen.\n\nDoch seht zum fernen Horizont. Dunkle Wolken ziehen unheilvoll über Skettis herauf. Sicher plant Terokk schon seinen nächsten Schachzug. Für heute ist Shattrath gerettet. Doch wer weiß schon, welch Verderben der nächste Tag über uns alle bringen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10880] = { id = 10880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle der Kabale", description = "Die Botschaft trägt ein dunkles Siegel. Auch wenn Euch die Sprache bekannt vorkommt, scheint der Text verschlüsselt zu sein.\n\nVielleicht weiß jemand bei der Flüchtlingskarawane etwas darüber.", sourceObjective = "Bringt die Befehle der Kabale zu Mekeda bei der Flüchtlingskarawane in der Knochenwüste.", progress = "Wollt Ihr mir etwas zeigen, {name}?", completion = "Ah, ja... dieser Text wurde in einer einfachen Form der Geheimschrift der Schatten geschrieben. Mein Wissen darüber ist nicht perfekt, aber es sollte ausreichen, um sie zu übersetzen.\n\nMan kann viel von den zwielichtigen Gestalten lernen, wenn man unter den Ausgestoßenen und Flüchtlingen im unteren Viertel lebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10881] = { id = 10881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schattengrab", description = "Viele glauben, dass der Schattenrat die Explosion, die Auchindoun in tausend Stücke gerissen hat, verursacht hat. Gerüchten zufolge sollen sie im Inneren ein großes Übel erweckt haben.\n\nWenn das stimmt, muss dieses Böse sich gegen sie gewandt haben. Laut diesen Befehlen flieht ein Teil des Schattenrats aus Auchindoun. Sie benutzen das Schattengrab, um mächtige Artefakte aus Auchindoun zu lagern.\n\nDrei dieser Artefakte sind heilig, denn sie gehörten den mächtigen Patriarchen Arunen, K'alen und Atalor. Ich muss Euch bitten, sie wieder zu holen.", sourceObjective = "Geht in das Schattengrab westlich der Flüchtlingskarawane und beschafft Euch Arunens Tuch, K'alens Hammer und Atalors Schriftrolle. Kehrt danach zu Mekeda bei der Flüchtlingskarawane zurück.", progress = "Habt Ihr die Relikte, {name}? Wir können nicht zulassen, dass der Schattenrat sie für seine dunklen Zwecke einsetzt.", completion = "Das Licht hat mich vielleicht vergessen, aber ich habe das Licht nicht vergessen. Diese Relikte waren meinem Volk einst sehr heilig.\n\nDem Schattenrat zu erlauben, sie für Böses einzusetzen ist... undenkbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[10882] = { id = 10882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herold der Verdammnis", description = "<Ein Missklang ertönt in A'dals 'Stimme'.>\n\nPrinz Kael'thas hat seine Wärter schlampig ausgewählt, und nun brechen die Wesenheiten, die in der Arkatraz eingesperrt waren, aus.\n\nBesonders eine davon, ein Diener der Alten Götter, der als Herold Horizontiss bekannt ist, versucht, die Vision seines Meisters von der Eroberung aller Welten in diesem Universum in die Tat umzusetzen.\n\n{name}, Ihr dürft nicht zulassen, dass er entkommt. Kehrt zur Festung der Stürme zurück und begebt Euch in die Arkatraz. Tötet Herold Horizontiss, bevor es zu spät ist!", sourceObjective = "Ihr wurdet beauftragt, zur Arkatraz in der Festung der Stürme zu reisen und Herold Horizontiss zu töten. Kehrt danach zu A'dal auf der Terrasse des Lichts in Shattrath zurück.", completion = "<Das kristallene Klingen von A'dals Stimme fließt in einer deutlich ruhigeren Melodie als die letzten beiden Male, in denen Ihr miteinander gesprochen habt.>\n\nWieder einmal habt Ihr Euren Eifer bewiesen. Wenn Herold Horizontiss ausgebrochen wäre, wären Tausende dem Konflikt zum Opfer gefallen, genauso, wie es bei einem anderen Diener der alten Götter, Skeram, auf Eurer Welt Azeroth geschehen ist.\n\n{name}, was ich Euch als Belohnung anbiete, scheint im Vergleich erbärmlich zu sein, aber seid Euch bewusst, dass die ewige Dankbarkeit der Sha'tar damit verbunden ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[10883] = { id = 10883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel der Stürme", description = "Ihr habt Euch in großen Taten bewiesen, {name}. Eure Entdeckung der Litanei der Verdammnis und Kael'thas' Rolle dabei sind für unsere Sache von äußerster Wichtigkeit. Sollte Kael'thas die Litanei benutzen, würde der kleine Rest, der noch von dieser Welt übrig ist, in sich zusammenfallen.\n\nA'dal ist davon überzeugt, dass Kael aufgehalten werden muss und ist nun auf der Suche nach Abenteurern, die sich seinen Prüfungen unterziehen möchten. Die Naaru werden denjenigen, die ihre Stärke beweisen, ihre Gunst gewähren.\n\n<Khadgar nickt.>\n\nA'dal erwartet Euch...", sourceObjective = "Sprecht mit A'dal in Shattrath.", completion = "Die Festung der Stürme ist eine Erfindung der Naaru, Sterblicher. Zutritt zu der Festung zu gewähren lag schon immer alleine im Ermessen der Naaru. Eine Rückkehr zur Festung der Stürme erschien uns jedoch unnötig. Vielleicht mag das für ein sterbliches Volk wie Stolz aussehen, doch wir Naaru halten nur wenig von solchen Dingen.\n\nWir gehen nun, weil wir es müssen. Kael'thas darf die Litanei der Verdammnis niemals vorlesen.\n\nAuch wenn der Weg offen steht, so würde sich nur ein Narr unerprobt hineinwagen. Unterschätzt nicht den Zweck der Prüfungen, Sterblicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[10884] = { id = 10884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: Erbarmen", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nIn den Zerschmetterten Hallen der Höllenfeuerzitadelle werden drei Leute Eures Volkes von dem erbarmungslosen Kargath Messerfaust gefangen gehalten. Er hat vor, sie als Zeichen seiner Männlichkeit und Stärke hinzurichten. Ihr müsst diese Gefangenen retten, bevor eine solche Grausamkeit geschehen kann. Bringt mir die unbenutzte Axt des Henkers als Beweis Eurer Tat. Es darf kein einziger Tropfen Blut an der Klinge sein!", sourceObjective = "A'dal in Shattrath möchte, dass Ihr die unbenutzte Axt des Henkers aus den Zerschmetterten Hallen der Höllenfeuerzitadelle besorgt.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "<A'dal grüßt Euch.>", completion = "Gut gemacht, {name}. Ihr habt die Prüfung des Erbarmens abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10885] = { id = 10885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: Stärke", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nDie Prüfung der Stärke besteht aus zwei Teilen. Ihr müsst den Anführer der Dampfkammern des Echsenkessels, Kriegsherr Kalithresh, töten und mir seinen Dreizack bringen. Außerdem müsst Ihr das außerdimensionale Wesen Murmur im Schattenlabyrinth in Auchindoun erlegen und mir seine Essenz bringen.\n\nWenn Ihr dies geschafft habt, habt Ihr die Prüfung der Stärke bestanden.", sourceObjective = "A'dal in Shattrath möchte, dass Ihr Kalithreshs Dreizack und Murmurs Essenz besorgt.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "<A'dal grüßt Euch.>", completion = "Gut gemacht, {name}. Ihr habt die Prüfung der Stärke abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10886] = { id = 10886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: Zuverlässigkeit", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nAuf unseren Reisen haben wir viele gefährliche Wesen getroffen. Einige dieser Wesen wurden eingefangen und werden nun an Bord der Arkatraz in der Festung der Stürme gefangen gehalten.\n\nEiner der Gefangenen ist jedoch Opfer eines unglücklichen Zufalls. Er war zur falschen Zeit als blinder Passagier auf dem falschen Schiff der Naaru unterwegs.\n\nReist zur Arkatraz und rettet den Gnom Millhaus Manasturm. Stellt sicher, dass er überlebt.", sourceObjective = "A'dal in Shattrath möchte, dass Ihr Millhaus Manasturm aus der Arkatraz in der Festung der Stürme rettet.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", completion = "Gut gemacht, {name}. Ihr habt die Prüfung der Zuverlässigkeit abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10887] = { id = 10887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus dem Grab", description = "Ich weiß Eure Hilfe zu schätzen, {name}. Ich war mir sicher, dass ich sterben würde.\n\nLasst uns schnell von hier verschwinden. Bald werden uns noch mehr Kultisten auf den Fersen sein.", sourceObjective = "Helft Akuno zur Flüchtlingskarawane zu gelangen. Sprecht danach mit Mekeda.", completion = "Ihr habt Akuno, meinen geschätzten Freund, errettet. Dafür stehe ich in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10888] = { id = 10888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: Magtheridon", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nEs bleibt nur noch eine übrig, <Sterblicher/Sterbliche>. Sammelt eine Armee und reist zu Magtheridons Kammer tief in der Höllenfeuerzitadelle. Kämpft Euch bis zur Mitte der Kammer durch und vernichtet diesen miesen Verderber!", sourceObjective = "A'dal in Shattrath möchte, dass Ihr Magtheridon vernichtet.", progress = "<A'dal grüßt Euch.>", completion = "Ihr habt Euch als Wesen mit großer Macht bewiesen. Die Naaru sind sich einig...", sourceObjectiveStatus = "unverified-source-field" }
quests[10889] = { id = 10889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Shattrath", description = "Auch wenn Eure Taten sehr mutig waren, wird Terokk sicher nicht lange auf seine Rache warten lassen.\n\nGeht schnell nach Shattrath! Verständigt Rilak!", sourceObjective = "Reist nach Shattrath und Sprecht mit Rilak den Erlösten im Unteren Viertel.", completion = "Die Wachen von Skettis werden langsam unruhig. Shattrath steckt in Schwierigkeiten. Wir werden Terokks Rache sicher eiskalt zu schmecken bekommen.\n\nStellt schnell eine Verteidigung auf die Beine! Sprecht mit Verteidiger Grashna und lasst ihn wissen, dass Ihr bereit seid, die Waffen gegen unsere Angreifer zu erheben!", sourceObjectiveStatus = "unverified-source-field" }
quests[10891] = { id = 10891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Plattenrüstung", description = "In Gadgetzan gibt es einen Zwerg namens Derotain Matschnipper der Euch beibringen kann, wie man eine imperiale Brustplatte herstellt. Ihr müsst nur nach Tanaris reisen und ihn suchen. Interesse?", sourceObjective = "Sprecht Derotain Matschnipper in Gadgetzan in Tanaris.", completion = "Natürlich bringe ich Euch bei, wie man eine imperiale Plattenrüstung herstellt! Es wird Euch allerdings ein wenig Gold kosten... in Form von Thoriumbarren!", sourceObjectiveStatus = "unverified-source-field" }
quests[10892] = { id = 10892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperiale Plattenrüstung", description = "In Gadgetzan gibt es einen Zwerg namens Derotain Matschnipper der Euch beibringen kann, wie man eine imperiale Brustplatte herstellt. Ihr müsst nur nach Tanaris reisen und ihn suchen. Interesse?", sourceObjective = "Sprecht Derotain Matschnipper in Gadgetzan in Tanaris.", completion = "Natürlich bringe ich Euch bei, wie man eine imperiale Plattenrüstung herstellt! Es wird Euch allerdings ein wenig Gold kosten... in Form von Thoriumbarren!", sourceObjectiveStatus = "unverified-source-field" }
quests[10893] = { id = 10893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langschweif ist der springende Punkt", description = "Da die Wyrmkultisten der Pechschwingen sich im Tunnel sammeln, sehen wir uns gezwungen, der Lage Herr zu werden. Ehrlich gesagt sind sie deutlich in der Überzahl.\n\nAuch wenn wir bisher diejenigen, die uns zu nahe gekommen sind, zurückhalten konnten, wären wir einem ernsthaften Angriff von ihnen nicht gewachsen.\n\nDie Lage erfordert, dass jemand sich bis an das andere Ende des Tunnels durchkämpft und ihre Anführerin, Draaca Langschweif, unschädlich macht. Habt Ihr Lust auf ein wenig Spaß?", sourceObjective = "Tötet Draaca Langschweif, die Anführerin der Wyrmkultisten im Tunnel des Wyrmschädels.", progress = "Ist sie tot?\n\n{name}, wenn wir auch nur die leiseste Chance gegen sie haben wollen, müsst Ihr Verwirrung unter ihren Rängen säen, indem Ihr Draaca Langschweif tötet!", completion = "Nun, da Draaca unschädlich gemacht wurde, sollten wir in der Lage sein, unseren Vorteil aus der Situation zu ziehen. Sie werden sich jetzt untereinander darum streiten, wer die Leitung übernehmen soll, und das wird uns viel Druck nehmen.\n\nEs sei denn der Aufseher aus dieser Einladung, die Ihr mir gegeben habt, nimmt ihren Platz ein.\n\nWir sollten sicherstellen, dass das niemals passieren wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[10894] = { id = 10894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behüter des Wyrmschädels", description = "Hm, ich weiß nicht so recht, was wir tun sollen. Ich bin nicht gerade ein Militärstratege.\n\nBehüter Mondschatten weiß sicher, was zu tun ist. Er kümmert sich um unsere Verteidigung beim Tunnel des Wyrmschädels im Westen, am Ende der Brücke des Wyrmschädels. Wir unterhalten dort eine Streitmacht, falls die Kultisten zu übermütig werden.\n\nBitte, bringt ihm so schnell wie möglich diese Nachricht.", sourceObjective = "Bringt die Einladung zum Treffen zu Behüter Mondschatten beim Eingang des Tunnels des Wyrmschädels im Schergrat.", progress = "Wie kann ich Euch helfen? Bringt Ihr Nachrichten aus dem ewigen Hain?", completion = "Es ist genau so, wie ich es befürchtet habe, und das ist nicht gut!\n\nIch habe schon eine Idee, wie ich Euch helfen kann, aber vielleicht könnt zunächst Ihr uns helfen?\n\nEine Hand wäscht die andere.", sourceObjectiveStatus = "unverified-source-field" }
quests[10895] = { id = 10895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeth'Gor muss brennen!", description = "Es ist an der Zeit, Zeth'Gor aus der Luft anzugreifen! Unsere Greifenreiter sind bereit für einen kleinen Ausflug, {name}. Aber wir brauchen jemanden, der vom Boden aus ihre Angriffe lenkt. Seid Ihr bereit für einen kleinen Geheimauftrag?\n\nBringt diese Rauchsignale nach Zeth'Gor, dem Stützpunkt des Blutenden Auges im Westen. Dort befinden sich vier Wachtürme: einer in der Nähe der nördlichen Mauer, einer in der Nähe der südlichen Mauer, einer in der Nähe der Schmiede und einen in den Hügeln. Platziert ein Rauchsignal unter jedem Turm und wir werden sie bombardieren!", sourceObjective = "Benutzt das Rauchsignal unter jedem Wachturm in Zeth'Gor und kehrt danach zu Schwadronskommandant Dabir'ee beim Expeditionsposten zurück.", progress = "Die Zeit drängt, {name}. Wir müssen diese Wachtürme anzünden!", completion = "Ich konnte von hier aus den Rauch und die Flammen sehen! Gute Arbeit, {name}! Ihr verdient mehr als nur ein paar Lobesworte von unseren Greifenreitern. Was Ihr da getan habt, erfordert eine gehörige Portion Mut.", sourceObjectiveStatus = "unverified-source-field" }
quests[10896] = { id = 10896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verseuchten Beschützer", description = "Die Macht, die von Auchindoun freigesetzt wurde, hat verheerende Auswirkungen auf die Bäume dieses Landes. Die verderbte Magie, die dort entfesselt wurde, hat das Land in diese Wüste verwandelt, die Ihr nun hier überall sehen könnt. Die Bäume, die überlebt haben, sind nun von schädlichen Baummilben befallen, die unter ihre Rinde kriechen und ihr Holz anfressen.\n\nFaulende Waldwüter und befallene Wurzelwandler sind ein idealer Nährboden für die Milben. Man kann sie am östlichen Waldrand finden. Vernichtet diese Kreaturen und tötet dann die Milben, die aus ihrer Hülle fliehen.", sourceObjective = "Lakotae möchte, dass Ihr 25 Baummilben tötet und danach zu ihm bei der Flüchtlingskarawane zurückkehrt. Ihr findet die Milben in den Körpern der faulenden Waldwüter und befallenen Wurzelwandler.", completion = "Ihr habt viel zur Rettung der Wälder von Terokkar beigetragen, {name}. Jetzt, da die schlimmsten Milbenkolonien vernichtet sind, können wir vielleicht dieses öde Land zurückerobern.", sourceObjectiveStatus = "unverified-source-field" }
quests[10897] = { id = 10897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Tränke", description = "Wie Ihr sicher wisst, verfügen Pflanzen über Eigenschaften, mit deren Hilfe Alchemisten über Tränke andere stärken und verjüngen können.\n\nMein Wissen über die Pflanzen in der Scherbenwelt ermöglicht mir, Alchemisten beizubringen, wie sie das Beste aus ihnen herausholen können. Wenn Ihr Euer Wissen über Tränke vertiefen möchtet, müsst Ihr nur eine kleine Aufgabe für mich erledigen.\n\nHochbotaniker Freywinn in der Festung der Stürme soll angeblich einen ausführlichen Botanikführer geschrieben haben. Bringt ihn zusammen mit ein paar Proben Eurer Arbeit zu mir und ich werde Euch das Wissen lehren, das Ihr wünscht.", sourceObjective = "Lauranna Thar'well möchte, dass Ihr die Botanika der Festung der Stürme betretet und den Naturführer der Botanika von Hochbotaniker Freywinn besorgt. Zusätzlich möchte sie, dass Ihr ihr 5 erstklassige Heiltränke, 5 erstklassige Manatränke und 5 erhebliche Tränke des traumlosen Schlafs bringt.\n\nACHTUNG! Ihr könnt nur eine Alchimiespezialisierung wählen.", progress = "Seid Ihr Euch sicher, {name}? Wenn Ihr Euch in der Kunst der Tränke spezialisiert, werdet Ihr keine weiteren Spezialisierungen erlernen können.", completion = "Ausgezeichnet! Wie es aussieht, seid Ihr begierig darauf zu lernen, also lasst uns beginnen. Ich werde Euch beibringen, wie Ihr das Beste aus den Pflanzen für Eure alchimistischen Tränke herausholt.\n\nIhr werdet sehen, dass ganz schön viel in den Kräutern steckt, wenn man weiß, was man zu tun hat. Manchmal kann man sogar zwei Tränke mit den Materialien für einen herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10898] = { id = 10898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolkenschwinge", description = "Wolkenschwinge flattert um Euch herum.\n\nEurer Einschätzung nach möchte er, dass Ihr ihm folgt.", sourceObjective = "Begleitet Wolkenschwinge und meldet Euch dann bei Rilak dem Erlösten in Shattrath.", completion = "Also stand der arme Wolkenschwinge unter dem schrecklichen Fluch von Luanga dem Kerkermeister!\n\nWolkenschwinge hatte sich auf den Weg ins Shalasversteck gemacht, um zu versuchen, die anderen auf den Weg des Lichts zu bringen. Sie haben seine Versuche nicht gerade positiv aufgenommen, vor allem nicht, da sie direkt am Fuße von Skettis liegen.\n\nLuanga war einer von Terokks gefürchtetsten Dienern. Es war gut von Euch Wolkenschwinge zu befreien! Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10899] = { id = 10899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Transmutation", description = "Jeder Alchemist kann Euch erklären, dass Materie formbar ist und jede Substanz in eine andere verwandelt werden kann. Jedoch wird dabei nichts wirklich erschaffen oder zerstört.\n\nEin wahrer Meister der Transmutation kann lernen, diese Grenzen zu überwinden. Und ich kann Euch zeigen, wie man dies erreichen kann!\n\nAls angehender Transmutierer seid Ihr sicher mit der Urmacht vertraut, der Verbindung der Materialien aller Urkräfte. Beweist mir Euer Können in der Kunst der Transmutation. Dann werde ich mein Wissen mit Euch teilen.", sourceObjective = "Zarevhi in der Sturmsäule im Nethersturm möchte, dass Ihr ihm 4 Einheiten Urmacht bringt.\n\nACHTUNG! Ihr könnt nur eine Alchimiespezialisierung wählen.", progress = "Seid Ihr sicher, dass Ihr ein Meistertransmutierer werden wollt? Wenn Ihr Euch auf diesem Gebiet spezialisiert, werdet Ihr Euch nicht auf Tränke oder Elixiere spezialisieren können.", completion = "Ausgezeichnete Arbeit, {name}! Diese Transmutationen sind in jeder Hinsicht perfekt!\n\nIch werde Euch nun beibringen, wie man mit Hilfe der alchimistischen Transmutation Materie aus dem Nichts erschaffen kann! Nutzt Euer Wissen weise, Meistertransmutierer.\n\nWenn Ihr mich nun entschuldigen möchtet, ich muss einen Kunden aufsuchen, der an Urmacht interessiert ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[10900] = { id = 10900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mal von Vashj", sourceObjective = "Brennt es nieder, {race}! Brennt alles nieder! Sie haben nichts verdient. Habt Ihr mich verstanden? NICHTS! Sie müssen für ihre Taten bezahlen. Auch für ihre zukünftigen.\n\nIch würde Vashj selbst töten, wenn ich von diesen verdammten Fesseln frei wäre.\n\nOder wollt Ihr vielleicht Neptulons Arbeit erledigen? Ihr Tod ist uns beiden dienlich, Weichhaut. Werdet Ihr mir dabei helfen, den heiligen Knüppel herzustellen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10901] = { id = 10901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Knüppel von Kar'desh", description = "Bringt mir die Elementarsiegel, die ich für den Knüppel brauche!\n\nDas Erdensiegel befindet sich im Besitz von Gruul dem Drachenschlächter. Ihr findet ihn in seinem Unterschlupf im Schergrat.\n\nDas zweite Siegel ist das flammende Herz einer Kreatur, die als Schrecken der Nacht bekannt ist. Diese mystische Kreatur soll sich angeblich in den geheiligten Hallen des Propheten Medivh aufhalten.\n\nBeeilt Euch!", sourceObjective = "Nar'biss der Ketzer in den heroischen Sklavenunterkünften des Echsenkessels möchte, dass Ihr ihm das Erdensiegel und das Flammensiegel bringt.", progress = "Mit dem Knüppel werde ich meine Fesseln lösen können und zum Schlangenschrein zurückkehren, um meine Rache an Vashj und ihren Dienern zu üben!", completion = "Endlich!\n\nMit gelösten Fesseln und dem Knüppel in meinem Besitz werde ich diese Meereshexe wieder zurück in die eisigen Tiefen senden...", sourceObjectiveStatus = "unverified-source-field" }
quests[10902] = { id = 10902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Elixiere", description = "Ich habe mein Leben der Perfektion meiner Elixiere gewidmet. Trotz meines Erfolgs habe ich es nie geschafft, ein Elixier des ewigen Lebens herzustellen.\n\nIch glaube zu wissen, welche Reagenz mir fehlt. Ich habe von einem Ort in Azeroth gehört, der die Höhlen der Zeit genannt wird. Die Eindringlinge dort, Fürsten der Zeitenrisse genannt und die Bewahrerinnen der Zeitrisse können auf den Zeitlinien hin- und herspringen.\n\nDurch diesen Wechsel in der Zeit entstehen Risse, die sich in alle Ewigkeit ziehen und zu unendlicher Essenz kristallisieren. Bringt mir diese Essenzen zusammen mit Proben Eures handwerklichen Könnens und ich werde Euch alles beibringen, was ich weiß.", sourceObjective = "Begebt Euch in den Schwarzen Morast in den Höhlen der Zeit und besorgt 10 Essenzen der Unendlichkeit von den Fürsten der Zeitenrisse und den Bewahrerinnen der Zeitenrisse. Bringt die Essenzen zusammen mit 5 Elixieren der erheblichen Verteidigung, 5 Elixieren des Meisters und 5 Elixieren der erheblichen Beweglichkeit zu Lorokeem im Unteren Viertel von Shattrath.\n\nACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchemie wählen!", progress = "Die Essenzen! Habt Ihr sie?", completion = "Ihr versteht Euch auf Elixiere, wenn man diesen hier glauben mag. Ihr werdet ein guter Schüler sein.\n\nDiese Essenzen werden ausreichen, um mein Rezept zu entwickeln. Für diese Entdeckung werde ich Berühmtheit unter allen Alchimisten erlangen!\n\nWenn Ihr nun bereit seid zu lernen, bin ich bereit zu lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10903] = { id = 10903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Ehrenfeste", description = "{name}, während Ihr mit Eurem Auftrag in Zeth'Gor beschäftigt wart, habe ich Nachricht von meinem befehlshabenden Offizier, Oberst Jules erhalten. Er wurde während des Kampfes beim Außenposten von Gor'gaz von einer dämonischen Verderbnis befallen. Sein Zustand wird immer schlechter.\n\nIhr habt so viele große Erfolge gegen die Höllenorcs erzielt. Eure Kraft in der Schlacht steht außer Frage... ist Euer Geist auch so stark?\n\nBitte, kehrt zur Ehrenfeste zurück und sprecht mit Klatu. Er befindet sich in einem Raum über dem Gasthaus der Ehrenfeste.", sourceObjective = "Sprecht mit Gehilfe Klatu im Gasthaus der Ehrenfeste.", completion = "Ja, es ist wahr. Oberst Jules' Zustand hat sich in den letzten Tagen stark verschlechtert. Anachoret Barada betet schon die ganze Zeit für ihn... Wir hoffen, dass er geheilt werden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10904] = { id = 10904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsmunition", description = "Wir müssen der Brennenden Legion den Zugang zu Schwelle des Todes versperren, aber zunächst müsst Ihr die beiden Warptore zerstören!\n\nDas Problem ist, dass wir diesen Dingern nicht einmal einen Kratzer zufügen können, daher müsst Ihr ihre eigenen Waffen gegen sie verwenden.\n\nDie Mächte des Todes, die Augen des Todes, die Oberschmiede der Todesschmiede und die Techniker der Todesschmiede tragen die Munition für die Teufelskanonen bei sich.\n\nNormalerweise kann diese Munition ihnen nichts anhaben, aber wenn Ihr die Kanonenkugeln zu mir bringt, werde ich sie mit dem unbändigen Zorn der Natur erfüllen!", sourceObjective = "Beschafft Euch 5 Teufelskanonenkugeln.", progress = "Habt Ihr die Kanonenkugeln schon?", completion = "Diese Dinger stinken ja schlimmer, als ich dachte!\n\nSchnell, gebt sie mir, damit ich die mit der Macht der Natur erfüllen kann. Dann werden sie zu tödlichen Waffen gegen die teuflischen Meister und ihre unnatürlichen Schöpfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10905] = { id = 10905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Tränke", description = "Mein Wissen über die Alchemie ist sehr groß. Jedoch ist es eher allgemein gehalten. Wenn Ihr Euch spezialisieren möchtet, müsst Ihr Euch an jemanden wenden, der sich auf ein engeres Studiengebiet konzentriert.\n\nWenn Ihr Euch auf die Herstellung von Tränken spezialisieren möchtet, empfehle ich Euch, Lauranna Thar'well von der Expedition des Cenarius aufzusuchen.\n\nIhr Wissen über die Pflanzen wird Euch dabei helfen, das Beste aus Euren Rohmaterialien herauszuholen. Sucht sie in den Zangarmarschen auf und sagt ihr, dass ich Euch geschickt habe.", sourceObjective = "Sprecht mit Lauranna Thar'well in der Zuflucht des Cenarius in den Zangarmarschen.\n\nACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchemie erlernen.", completion = "Ihr wollt, dass ich Euch bei Euren Studien der Tränke helfe? Nun gut, {name}. Wollen wir mal schauen, was wir da machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10906] = { id = 10906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Elixiere", description = "Mein Wissen über die Alchemie ist sehr groß. Jedoch ist es eher allgemein gehalten. Wenn Ihr Euch spezialisieren möchtet, müsst Ihr Euch an jemanden wenden, der sich auf ein engeres Studiengebiet konzentriert.\n\nWenn Ihr Euch auf die Herstellung von Elixieren spezialisieren möchtet, empfehle ich Euch, den Arakkoa namens Lorokeem um Hilfe zu bitten.\n\nSein Wissen über Elixiere sucht seinesgleichen und doch verschwendet er sein Können darauf, ein Elixier des ewigen Lebens zu brauen. Sucht nach ihm und schaut, was er Euch beibringen kann.", sourceObjective = "Sprecht mit Lorokeem im Unteren Viertel von Shattrath.\n\nACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchemie erlernen.", completion = "Ihr wollt von mir lernen? Hmmm, ja. Vielleicht seid Ihr ja ein geeigneter Schüler.", sourceObjectiveStatus = "unverified-source-field" }
quests[10907] = { id = 10907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Transmutation", description = "Mein Wissen über die Alchemie ist sehr groß. Jedoch ist es eher allgemein gehalten. Wenn Ihr Euch spezialisieren möchtet, müsst Ihr Euch an jemanden wenden, der sich auf ein engeres Studiengebiet konzentriert.\n\nWenn Ihr Euch in der Kunst der Transmutation spezialisieren möchtet, empfehle ich Euch, den Astralen namens Zarevhi um Hilfe zu bitten. Er lebt in der Sturmsäule im Nethersturm.\n\nSeine Beherrschung der Transmutation ist... nun, exotisch! Seht nach, was Ihr von ihm lernen könnt. Aber seid vorsichtig: Astrale sind hartnäckige Verhandlungspartner.", sourceObjective = "Sprecht mit Zarevhi in der Sturmsäule im Nethersturm.\n\nACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchemie erlernen.", completion = "Ihr wollt, dass ich Euch bei Euren Studien der Transmutation helfe? Nun gut, {name}. Wollen wir mal schauen, was wir da machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10908] = { id = 10908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Rilak dem Erlösten", description = "Ihr seht überrascht aus, dass ich mit Euch rede. Ich mache Euch keinen Vorwurf. Mein Volk, die Arakkoa, verdienen Euren Argwohn.\n\nSprecht mit Rilak dem Erlösten in Shattrath, wenn Ihr mehr erfahren wollt. Er hält sich im nördlichen Teil des Unteren Viertels bei den anderen Ausgestoßenen der Skettis auf.\n\nUnd {name}, wir werden voneinander hören.", sourceObjective = "Kirrik der Erwachte möchte, dass Ihr mit Rilak dem Erlösten im Unteren Viertel von Shattrath sprecht.", completion = "So treffen wir uns also, {name}. Bitte vergebt mir meine fehlenden Manieren, aber die Zeit drängt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10909] = { id = 10909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllengeister", description = "Oberst Jules wurde in einer Schlacht in der Nähe des Außenpostens von Gor'gaz, einer der Lieblingsorte der Höllenorcs der Zerschmetterten Hand, verflucht. Mein Meister Barada versucht verzweifelt, den armen Menschen zu heilen, aber er braucht Hilfe. Der verwirrte Geist des Oberst sucht nach Frieden, und ich fürchte, dass ein Teil des Weges dazu der Weg der Rache ist.\n\nBringt dieses Relikt des Anachoreten zum Außenposten von Gor'gaz. Stellt es in der Nähe der Orcs der Zerschmetterten Hand auf und besiegt sie. Das wird ihre Höllengeister freisetzen. Ihr müsst die Höllengeister töten, damit Jules Geist sich erholen kann.", sourceObjective = "Klatu in der Ehrenfeste möchte, dass Ihr das Relikt des Anachoreten beim Außenposten von Gor'gaz benutzt, die Orcs der Zerschmetterten Hand in der Nähe des Relikts tötet und dann 10 freigesetzte Höllengeister vernichtet, um Oberst Jules zu rächen.", progress = "Die Höllengeister der Orcs der Zerschmetterten Hand sind für Jules' arme Seele eine Schmach. Sagt mir, {name}... habt Ihr ihn gerächt?", completion = "Die Orcs der Zerschmetterten Hand sind verderbt und nicht mehr zu retten. Und dennoch erfüllt es mein Herz mit Traurigkeit, dass die Rettung von Oberst Jules ein solches Blutvergießen erfordert.", sourceObjectiveStatus = "unverified-source-field" }
quests[10910] = { id = 10910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwelle des Todes", description = "Wir haben von einer sogar noch größeren Bedrohung durch die Legion erfahren. Im Süden befindet sich ein Portal, dass als Schwelle des Todes bekannt ist. Es ist die Tür zu einer entsetzlichen Welt, in der die Legion ihre verschiedenen Hunderassen züchtet.\n\nUm dorthin zu gelangen, müsst Ihr den Ewigen Hain Richtung Osten verlassen und den Pfad hinauf gehen. Folgt dem Weg nach Süden durch die Messerschlucht, an Razaans Landeplatz vorbei durch den Messergrat und über die Schuppenflügelbank. Nehmt dann den Pfad hinab nach Vekhaar und betretet die Schwelle des Todes durch den Tunnel südlich des Dorfs der Mok'Nathal.\n\nBenutzt dieses Druidensignal, sobald Ihr angekommen seid.", sourceObjective = "Benutzt das Druidensignal bei der Schwelle des Todes, um einen Druiden des Ewigen Hains zu rufen und mit ihm zu sprechen.\n\nBereitgestellter Gegenstand:", completion = "Ich bin sehr erleichtert, dass Wildfürst Antelarion Euch zu uns geschickt hat. Das Problem ist noch viel schlimmer, als wir befürchtet haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[10911] = { id = 10911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer frei!", description = "Jetzt, da unsere Munition der Brennenden Legion Schaden zufügen kann, ist es an der Zeit, dass Ihr sie benutzt.\n\nEs gibt zwei Warptore, die für die Teleportation und die Verbesserung der Schrecken der Leere benutzt werden. Eines befindet sich im Süden, das andere im Norden. Beide liegen in der Reichweite einer Teufelskanone.\n\nKämpft Euch bis zu den Teufelskanonen durch und benutzt die naturalisierte Munition, um die Kontrolle über die Kanonen zu erlangen und die Warptore zu zerstören.\n\nHütet Euch jedoch von den Verteidigern, die ausschwärmen werden, um die Kanone anzugreifen!", sourceObjective = "Verwendet die naturalisierte Munition, um die Kontrolle über die Teufelskanonen der Schwelle des Todes zu erlangen. Benutzt die Kanonen, um das südliche Warpportal und das nördliche Warpportal zu zerstören.", progress = "Habt Ihr beide Warpportale schon zerstört?", completion = "Euer Heldenmut ist beeindruckend!\n\nSehr gut. Nun, da die Warpportale außer Gefecht sind, bleibt nur noch eines zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[10912] = { id = 10912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hundehetzer", description = "Baelmon der Hundehetzer muss sterben! Er ist es, der das Ritual vollzieht, mit dem das Portal aufrechterhalten wird!\n\nDas Portal der Schwelle des Todes befindet sich am nördlichen Ende der Schlucht. Wenn Ihr es gefunden habt, findet Ihr auch Baelmon.\n\nIhr werdet dabei Hilfe brauchen, also nehmt diesen Stab mit. Benutzt ihn, wenn Ihr gegen den Hundehetzer kämpft, und ein paar meiner Freunde werden Euch zu Hilfe eilen.\n\nKehrt zu Wildfürst Antelarion zurück, wenn Ihr Baelmon besiegt habt.\n\nUnd {name}, vielen Dank für alles, was Ihr unseretwegen auf Euch genommen habt.", sourceObjective = "Tötet den Hundehetzer.", progress = "Ist es vorbei? Ist die Gefahr an der Schwelle des Todes abgewendet?", completion = "Ihr seid wirklich ein ganz erstaunlicher {race}! Wenn ich schon zuvor dachte, dass wir in Eurer Schuld stehen, so gibt es nun einfach keinen Weg mehr, Euch je für Eure Taten zu danken.\n\nAber wir wollen es dennoch versuchen. Vielen Dank, Held des ewigen Hains!", sourceObjectiveStatus = "unverified-source-field" }
quests[10913] = { id = 10913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unangemessenes Begräbnis", description = "Gibt es nichts, was man gegen diese Flut der Verderbnis tun kann? Meine Soldaten kämpfen schon seit Tagen gegen die Auchenai und ein Ende ist nicht in Sicht. Jeder Gefallene, ob Sha'tar oder Auchenai, wird sofort vom Schlachtfeld gezerrt. Ihre Seelen werden geraubt und an unbekannte Orte gebracht.\n\nDas werde ich nicht zulassen! Ein angemessenes Begräbnis ist leider nicht möglich, aber diese Bestien werden ihre Seelen nicht bekommen! Nehmt diese Fackel und begebt Euch zum Schlachtfeld östlich von hier. Verbrennt jeden Leichnam, den Ihr finden könnt! Wir werden ihre Rituale nicht verstärken!", sourceObjective = "Kommandant Ra'vaj beim Basislager der Sha'tari in der Knochenwüste der Wälder von Terokkar möchte, dass Ihr 8 getötete Kämpfer der Auchenai und 8 getötete Verteidiger der Sha'tar verbrennt.", progress = "Ich weiß, es ist eine grausame Aufgabe...", completion = "<Kommandant Ra'vaj schüttelt traurig den Kopf.>\n\nEs ist nicht genug... Es ist einfach nicht genug.", sourceObjectiveStatus = "unverified-source-field" }
quests[10914] = { id = 10914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen einen Helden!", description = "Es reicht. Wir brauchen einen Helden. Unsere Streitkräfte können der immer wachsenden Zahl der Auchenai nicht mehr Herr werden.\n\n<Kommandant Ra'vaj schaut Euch an.>\n\nWollt Ihr <unser Held/unsere Heldin> sein? Kehrt zum Schlachtfeld zurück und greift ihre Soldaten an. Beschäftigt sie, damit meine Späher hinter die Linien gelangen und herausfinden können, was sie dort vorbereiten.", sourceObjective = "Kommandant Ra'vaj beim Basislager der Sha'tari in der Knochenwüste der Wälder von Terokkar möchte, dass Ihr 12 Initianden der Auchenai und 5 Verdammnisverkünder der Auchenai tötet.", progress = "Keine Gefangenen!", completion = "Ihr habt es geschafft, {name}! Dank Euch konnten wir eine neue Entdeckung machen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10915] = { id = 10915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefallene Exarch", description = "Sie verfüttern die Seelen, die sie gestohlen haben, an einen Sarg, den sie aus der Auchenaikrypta entwendet haben. Meine Späher glauben, dass sich der erste Exarch der Krypta in diesem Sarg befindet. Die Auchenai versuchen, ihn wieder zum Leben zu erwecken!\n\nIhr müsst Euch zur westlichen Seite von Auchindoun durchschlagen und den Inhalt des Sargs stören, bevor sie ihm genügend Seelen füttern konnten. Falls Ihr Euch verirren solltet, folgt einfach den wandelnden Seelen.\n\nWas auch immer sich in dem Sarg befinden mag - vernichtet es!", sourceObjective = "Kommandant Ra'vaj beim Basislager der Sha'tari in der Knochenwüste der Wälder von Terokkar möchte, dass Ihr den Inhalt des Sargs der Auchenai vernichtet.", progress = "Ihr müsst dieses uralte Böse vernichten, bevor es seine Macht wiedererlangt.", completion = "Der Sieg ist unser! Diese Niederlage wird die Auchenai um mehrere Wochen zurückwerfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10916] = { id = 10916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Gebetsperlen graben", description = "Anachoret Barada hat vor, die Verderbnis aus Oberst Jules zu exorzieren und braucht dafür einen Gehilfen. So ein Gehilfe muss allerdings gut vorbereitet sein...\n\nIch schäme mich sehr, es zuzugeben, aber ich habe meine Gebetsperlen im Hof der Ehrenfeste verloren. Ich glaube, dass Fei-Fei der Hund sie gestohlen und verbuddelt hat, aber ich weiß nicht wo. Sprecht mit seiner Meisterin, Stabsfeldwebel Tracy Stolzbrunn. Vielleicht weiß sie, wo Fei-Fei seine gestohlenen Schätze aufbewahrt.", sourceObjective = "Sucht die Gebetsperlen der Draenei und bringt sie zu Gehilfe Klatu in der Ehrenfeste.", progress = "Habt ihr die Gebetsperlen schon gefunden, {name}? Ihre Macht ist für viele heilige Rituale unerlässlich... darunter auch für einen Exorzismus...", completion = "Ihr habt die Gebetsperlen gefunden! Gut gemacht, {name}. Ihr seid in der Tat ein Wunder. Im einen Moment erschlagt Ihr die Schrecken der Höllenfeuerhalbinsel, im anderen findet Ihr verlorene Schätze. Euer Volk ist wirklich sehr vielseitig!\n\nEs ist gut, dass Ihr diese Perlen gefunden habt... Sie sind für das folgende Exorzismusritual von äußerster Wichtigkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10917] = { id = 10917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflicht eines Ausgestoßenen", description = "Als Ausgestoßener gelte ich bei den Arakkoa, die der Stadt Skettis treu ergeben sind, als vogelfrei. Ich kann diese Mauern aus Angst um mein Leben nicht verlassen. Aber das heißt noch lange nicht, dass ich mich nicht rächen kann.\n\nIch habe einen kleinen Schatz, den ich hergeben würde, wenn Ihr mir dabei helft, meine Möchtegernmörder zu erledigen. Bringt mir die Federn der Bewohner der verschiedenen Arakkoaverstecke von Terokkar als Beweis für ihr Ableben.", sourceObjective = "Bringt 30 Arakkoafedern zu Vekax im Unteren Viertel von Shattrath.", progress = "Seid Ihr mit den Federn zurück, {name}?", completion = "<Vekax krächzt vor Freude, als Ihr ihm den Beweis für den Tod seiner Feinde übergebt.>\n\nJa, das wird Skettis zeigen, dass wir Ausgestoßenen ihre Bestrafung nicht lammfromm hinnehmen. Hier ist die Belohnung, die ich Euch versprochen habe. Ich kann Euch noch mehr geben, wenn Ihr mir weitere Federn bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10918] = { id = 10918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Federn", progress = "Die Schoßhunde von Skettis behalten uns Ausgestoßene immer noch genau im Auge. Sobald einer von uns es wagt, einen Fuß aus Shattrath zu setzen, sind wir so gut wie tot.\n\nBringt mir mehr Federn als Beweis für Euren Sieg über sie.", completion = "<Vekax krächzt vor Freude, als Ihr ihm den Beweis für den Tod seiner Feinde übergebt.>\n\nJa, das wird Skettis zeigen, dass wir Ausgestoßenen ihre Bestrafung nicht lammfromm hinnehmen. Hier ist die Belohnung, die ich Euch versprochen habe. Ich kann Euch noch mehr geben, wenn Ihr mir weitere Federn bringt.\n\n<Diese Quest kann wiederholt werden, bis Ihr den Ruf 'Wohlwollend' erlangt habt.>" }
quests[10919] = { id = 10919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fei-Feis Belohnung", progress = "Fei-Fei schaut Euch erwartungsvoll an...", completion = "<Fei-Fei bellt glücklich und schnappt sich das Hundeleckerli. Er schaut nach links und rechts um zu entscheiden, wo er seinen neuen Schatz vergraben soll...>" }
quests[10920] = { id = 10920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Gefallenen", description = "Als die Schreckenswitwen unseren Außenposten angegriffen haben, hörten wir die Stimme der Naaru, die uns in die Schlacht schickte. Wir verfolgten die Kreaturen bis in die tiefe Nacht hinein. Ein paar unserer Leute wurden in der Dunkelheit tot aufgefunden, andere hörten wir im verzweifelten Kampf gegen die Spinnen.\n\nDer Morgen zeigte uns, dass wir tapfer gekämpft und dennoch verloren hatten. Das Gift der Schreckensweber wird meine Kameraden bald dahinraffen, und auch ich werde nicht mehr lange durchhalten können. Doch bevor ich sterbe möchte ich die Gewissheit haben, dass die Schreckenswitwen geschlagen wurden.", sourceObjective = "Verteidiger Haylen möchte, dass Ihr 20 Schreckenswitwen tötet und danach zu ihm westlich des Netherweberkamms zurückkehrt.", progress = "Ich kann das Gift in meinen Adern spüren. Die Naaru rufen mich, ich sehe das Licht. Sind die Schreckenswitwen schon besiegt?", completion = "Ich habe die Geräusche Eures Kampfes bis hierher hören können, {class}. Der Klang Eures Sieges hat mein Herz mit Hoffnung erfüllt. Wenn Ihr gegen eine solch gewaltige Überzahl bestehen könnt, kann auch ich vielleicht noch die Kraft finden, um meine Kameraden von diesem schrecklichen Ort fort zu führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10921] = { id = 10921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokkarantula", description = "Ihr habt sehr viele Schreckenswitwen erschlagen, aber sie werden sich weiter vermehren und uns bald wieder angreifen. Tief im Netherweberkamm befindet sich das Nest von Terokkarantula, der Brutmutter dieser grausamen Kreaturen. Wenn wir in Sicherheit leben wollen, muss sie sterben.", sourceObjective = "Verteidiger Haylen möchte, dass Ihr Terokkarantula tötet und danach zu ihm westlich des Netherweberkamms zurückkehrt.", progress = "Ist Terokkarantula schon tot?", completion = "Die Schreckensspinnen wurden geschlagen. Ihr habt so viele von ihnen getötet und nun auch noch ihre verderbte Mutter erlegt. Meine Vergiftungen sind zu schwer, als dass ich mich zurück in die Freiheit kämpfen könnte.\n\nBitte, nehmt etwas von meiner Ausrüstung. Ich werde mein Bündel erleichtern und Euch die nötigen Werkzeuge geben, um heil zum Außenposten der Sha'tar zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10922] = { id = 10922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Knochen wühlen", description = "Heda! Ihr seht aus, als könntet Ihr gut auf Euch selbst aufpassen, {race}. Meine Truppe und ich hier sind auf der Suche nach einem Leibwächter, der auf uns aufpasst, während wir zu einer Ausgrabungsstätte im Norden gehen. Die Bezahlung ist ziemlich gut und Ihr müsst nur schauen, dass keine fiese Kreatur mich oder meine Angestellten tötet.\n\nWenn Ihr es heil zurückschafft ohne irgendwelche Todesopfer, wird Zwergowitz da drüben Euch bezahlen.", sourceObjective = "Begleitet Letoll und seine Truppe und beschützt sie, während sie ihre Ausgrabung durchführen. Kehrt danach zu Zwergowitz beim Basislager der Sha'tari zurück.", completion = "Ein Knochenwurm! Fantastisch! Das könnte tatsächlich das erste Mal seit Beginn der Geschichtsschreibung sein, dass Letoll tatsächlich eine Entdeckung gemacht hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[10923] = { id = 10923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Böse rückt näher", description = "Jetzt müsst Ihr das Schreckensrelikt in einem bösartigen nekromantischen Ritual benutzen, um Teribus den Verfluchten herauszufordern. Im Nordosten, hinter Auchindoun, liegt der Gequälte Hügel. An diesem Ort versammeln sich die Nekromanten.\n\nDie Todessprecher und Verdammnisverkünder der Auchenai tragen Verdammnisschädel bei sich, die mit mächtigen nekromantischen Verzauberungen belegt sind. Wenn Ihr genügend Schädel sammelt, könnt Ihr ihre Macht mit der des Schreckensrelikts vereinen und Teribus so befehlen, sich Euch zu stellen.", sourceObjective = "Oakun möchte, dass Ihr das Schreckensrelikt zum Gequälten Hügel bringt. Tötet dort die Todessprecher und Verdammnisverkünder der Auchenai, um 20 Verdammnisschädel zu sammeln. Sucht danach den Beschwörungskreis des Gequälten Hügels auf und benutzt das Schreckensrelikt, um Teribus den Verfluchten zu beschwören und zu vernichten. Kehrt zu Oakun zurück, wenn Ihr Eure Aufgabe erfüllt habt.", progress = "Habt Ihr Teribus den Verfluchten aus den Himmeln Terokkars vertrieben?", completion = "Terokkar wurde von einem schlimmen Übel befreit. Die Sha'tar stehen in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[10924] = { id = 10924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwichtelt und zugenäht!", description = "Das Blut der Sphärenhetzer in dieser Gegend ist eine sehr mächtige Reagenz und mein größter Verkaufsschlager.\n\nNormalerweise ziehe ich mit meinen Wichtel Zeppit los, um es zu sammeln. Es ist einfach viel zu ätzend, als dass Ihr es sammeln könntet, aber Zeppit kann es nichts anhaben.\n\nHier im Laden ist immer mehr los. Hättet Ihr daher etwas dagegen, wenn ich Euch Zeppit mitschicke, um etwas Blut zu sammeln? Zeppits Aufmerksamkeit neigt jedoch dazu abzuschweifen. Ihr müsst daher nahe an dem Hetzer stehen, wenn er gestorben ist, um sicherzugehen, dass Zeppit seine Arbeit erledigt.", sourceObjective = "Bringt 8 Phiolen Sphärenhetzerblut zu Sab'aoth in Kosmozang.", progress = "War Zeppit freundlich genug, das Blut für Euch zusammeln?", completion = "Das sollte genügend Vorrat für meine Zwecke sein.\n\nIch hoffe, der Wichtel hat Euch nicht allzu viel Ärger gemacht. Er hat manchmal Haare auf den Zähnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10926] = { id = 10926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Basislager der Sha'tari", description = "Wir werden es nicht ohne Hilfe zurück schaffen. Das Gift der Schreckensweber ist zu stark. Ihr müsst für uns zum Basislager der Sha'tari gehen. Späher Navrin wird eine Rettungstruppe nach uns schicken.", sourceObjective = "Verteidiger Haylen möchte, dass Ihr zum Basislager der Sha'tari in die Knochenwüste zurückkehrt und mit Späher Navrin sprecht.", completion = "Es ist gut zu wissen, dass einige unserer Krieger tapfer gegen die Schreckenswitwen gekämpft und überlebt haben. Wir werden sofort eine Rettungstruppe nach ihnen schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10927] = { id = 10927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krabbler erschlagen", description = "Kommandant Himmelsschatten möchte, dass wir diesen Tunnel freiräumen, damit wir den Handel mit der Zuflucht beschleunigen können. Ich darf meinen Posten hier nicht verlassen, daher übertrage ich Euch diese Aufgabe. Räumt den Tunnel frei und meldet Euch dann sofort bei Kommandant Himmelsschatten!", sourceObjective = "Tötet 6 Höhlenkrabbler.", completion = "Gute Arbeit, {class}. Dieser Tunnel ist unsere direkte Verbindung zum Sumpf.", sourceObjectiveStatus = "unverified-source-field" }
quests[10928] = { id = 10928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krabbler erschlagen", description = "Tor'chunk Zweiklaue möchte, dass wir diesen Tunnel freiräumen, damit wir den Handel mit dem Sumpfrattenposten beschleunigen können. Ich darf meinen Posten hier nicht verlassen, daher übertrage ich Euch diese Aufgabe. Räumt den Tunnel frei und meldet Euch dann sofort bei Tor'chunk Zweiklaue!", sourceObjective = "Tötet 6 Höhlenkrabbler.", completion = "Gute Arbeit, {class}. Dieser Tunnel ist unsere direkte Verbindung zum Sumpf.", sourceObjectiveStatus = "unverified-source-field" }
quests[10929] = { id = 10929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stampfen", description = "Würdet Ihr gerne noch mehr Aufgaben für die Forscherliga erledigen? Wir alle hier finden diese Knochenwürmer ziemlich faszinierend.\n\nIch habe hier eine Trommel, die Ihr draußen in der Knochenwüste benutzen könnt. Schlagt sie einfach und schaut, was dabei herauskommt. Wenn es ein Wurm ist, dann tötet ihn und bringt uns den Kadaver, damit wir ihn untersuchen können. Wir werden eine ganze Menge an Kadavern brauchen, wenn wir ein repräsentatives Testergebnis erzielen wollen.", sourceObjective = "Zwergowitz beim Basislager der Sha'tari in der Knochenwüste möchte, dass Ihr ihm 8 Kadaver eines ausgewachsenen Knochenwühlers bringt.", progress = "Wir glauben, dass das, was wir bei den Ausgrabungen gefunden haben, tatsächlich nur ein Wurmkind war!", completion = "Sandgnome? Ja, klar... Die Wüste kann schon schlimme Dinge mit den Leuten anstellen.\n\nIch glaube, wir werden mit diesen Würmern hier einen wahren Durchbruch erzielen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10930] = { id = 10930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Knochenwurm", description = "Ich hatte Recht! Die Kadaver, die Ihr mir gebracht habt, stammen von heranwachsenden Würmern! Wisst Ihr, was das bedeutet? Das bedeutet, dass es irgendwo da draußen noch einen großen geben muss! Wenn wir ihm das richtige Futter anbieten, können wir ihn sicher hervorlocken. Mal überlegen... etwas Großes! Ja!\n\nIch erinnere mich daran, hier auf der anderen Seite der Knochenwüste ein paar Grollhufe gesehen zu haben. Geht dorthin und tötet einen von ihnen. Benutzt die Trommel, sobald Ihr ihn erlegt habt. Hoffentlich kommt der große Wurm dann heraus, um zu fressen. Bringt mir seine Organe, wenn Ihr es schafft ihn zu töten!", sourceObjective = "Zwergowitz beim Basislager der Sha'tari in der Knochenwüste möchte, dass Ihr ihm riesige Knochenwurmorgane bringt.\n\nBringt auch den Stampfer zu ihm zurück.", progress = "Nehmt ein oder zwei Freunde mit!", completion = "Erstaunlich! Schaut Euch das an! Dieses Wasauchimmer hat eine Art Staub in seiner Wiemanesauchnennenmag. Aber ich will Euch nicht mit meinen wissenschaftlichen Fachbegriffen langweilen. Ich habe den kleineren Würmern ein paar Zähne gezogen und daraus diese unglaublich scharfen Messer gemacht. Wollt Ihr eins?", sourceObjectiveStatus = "unverified-source-field" }
quests[10931] = { id = 10931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Exodar", description = "Euer Meister Caedmos der Exodar wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.", sourceObjective = "Sprecht mit Caedmos in der Exodar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10932] = { id = 10932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Exodar", description = "Euer Meister Caedmos der Exodar wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.", sourceObjective = "Sprecht mit Caedmos in der Exodar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10933] = { id = 10933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Silbermond", description = "Euer Meister Aldrae in Silbermond wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.", sourceObjective = "Sprecht mit Aldrae in Silbermond.", sourceObjectiveStatus = "unverified-source-field" }
quests[10934] = { id = 10934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Silbermond", description = "Euer Meister Aldrae in Silbermond wünscht Euch zu sehen. Ich weiß nur, dass es Eure Ausbildung betrifft, mehr nicht.", sourceObjective = "Sprecht mit Aldrae in Silbermond.", sourceObjectiveStatus = "unverified-source-field" }
quests[10935] = { id = 10935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Exorzismus des Oberst Jules", description = "{name}, es ist an der Zeit, Oberst Jules zu retten. Sein Zustand hat sich verschlechtert, und Barada fürchtet, dass wir ihm nicht mehr helfen können, wenn wir ihn nicht bald von seiner Verderbnis heilen.\n\nNehmt die Gebetsperlen, die Ihr gefunden habt, und sprecht mit Anachoret Barada, um das Ritual zu beginnen. Lasst Euch dabei auf keinen Fall unterbrechen... und wenn alles gut geht, wird Oberst Jules gerettet sein. Sprecht mit Jules, wenn Ihr es geschafft habt, und kehrt danach zu mir zurück.", sourceObjective = "Sprecht mit Anachoret Barada. Benutzt die Gebetsperlen, um bei dem Ritual zu helfen und sprecht mit Oberst Jules, wenn er gerettet wurde. Kehrt danach zu Gehilfe Klatu zurück.", progress = "Geht zu Anachoret Barada, {name}. Er muss mit seinem Ritual Erfolg haben, wenn der Oberst gerettet werden soll.", completion = "Ihr habt es geschafft, {name}. Ihr habt Oberst Jules' Seele gerettet und die Dunkelheit in ihm vertrieben. Das ist eine großartige und selbstlose Tat! Die Tat eines Helden!", sourceObjectiveStatus = "unverified-source-field" }
quests[10936] = { id = 10936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollbann sucht Euch", description = "Während Ihr beschäftigt wart, kam ein Bote und hat in der Halle auf Euch gewartet. Ich nehme an, er hatte keine Lust mehr zu warten oder er hat beim Anblick von Jules, der hier durch den Raum schwebt, das Weite gesucht.\n\nWie auch immer, Truppenkommandant Danath sucht Euch. Ich schlage vor, dass Ihr ihn so schnell wie möglich in der Kaserne aufsucht!", sourceObjective = "Gehilfe Klatu hat Euch informiert, dass Truppenkommandant Danath Trollbann nach Euch sucht. Sprecht mit ihm in der Kaserne der Ehrenfeste auf der Höllenfeuerhalbinsel.", completion = "Das wird auch langsam Zeit! Ich habe davon erfahren, was Ihr und dieser Draeneipriester angestellt habt! Ihr habt meinen Boten völlig schockiert!\n\nJetzt, da Ihr damit fertig seid, habe ich einen kleinen Auftrag in der Höllenfeuerzitadelle für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10937] = { id = 10937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Züchtigung des Drillmeisters", description = "Ich erhalte Berichte, denen zufolge die Höllenorcs der Zerschmetterten Hand vor der Höllenfeuerzitadelle dabei sind, einen groß angelegten Angriff zu organisieren. Offensichtlich sind sie alles andere als glücklich über Eure Siege über all die anderen Klans.\n\nBegebt Euch zur Basis der Zitadelle am Ende des Pfads des Ruhmes. Dort werdet Ihr sehen, dass die Höllenorcs mitten in den Vorbereitungen stecken und sie eiskalt überraschen.\n\nVernichtet den Verantwortlichen der Truppe. Tötet Drillmeister Zurok!", sourceObjective = "Truppenkommandant Danath Trollbann befiehlt Euch, Drillmeister Zurok so schnell wie möglich zur Strecke zu bringen. Kehrt zu dem Truppenkommandanten in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück, wenn der Drillmeister tot ist.", completion = "Ich wollte es nicht glauben, bis ich es nicht von Euch persönlich gehört habe. Unsere Späher berichten uns jetzt schon, dass die Zerschmetterte Hand ohne ihren geschätzten Drillmeister, der ihnen sagt, was zu tun ist, völlig überfordert ist.\n\nIhr habt einen langen Weg zurückgelegt, {name}. Ich vertraue darauf, dass Ihr diese Rüstung zusammen mit meinem Dank annehmt. Tragt sie mit Stolz, denn Ihr habt sie verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[10938] = { id = 10938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segenskartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Segenskartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Segenskartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe habt Ihr es geschafft ein Set der Segenskarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Segenskartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10939] = { id = 10939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Sturmkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Sturmkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe habt Ihr es geschafft ein Set der Sturmkarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Sturmkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10940] = { id = 10940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furienkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Furienkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Furienkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe habt Ihr es geschafft ein Set der Furienkarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Furienkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10941] = { id = 10941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliriumkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Deliriumkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Deliriumkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe habt Ihr es geschafft ein Set der Deliriumkarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Deliriumkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10942] = { id = 10942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kinderwoche", description = "Ein ganz besonderes kleines Mädchen wird sich sehr darüber freuen, Euch zum Freund zu haben, und sei es nur für eine kurze Zeit.\n\nNehmt diese Pfeife. Ihr könnt damit das Kind rufen, dessen Patenschaft Ihr übernommen habt. Diese Patenschaft wird nicht lange dauern, nur solange die Kinderwoche andauert.\n\nBitte, {name}, ruft Eurer Waisenkind herbei. Ich weiß, dass sie schon darauf brennt Euch kennenzulernen und die Chance zu haben, einen Blick auf die Welt außerhalb der Stadt zu werfen!", sourceObjective = "Benutzt die Pfeife des Blutelfenwaisenkinds um Euren Schützling zu rufen, um den Ihr Euch während der Kinderwoche kümmern werdet.\n\nBereitgestellter Gegenstand:", completion = "Hm, Ihr seid also mein Pate? Ich bin Salandria! Ich bin schon, seit ich ein Baby war, hier. Meine Eltern sind im Krieg gestorben, daher lebe ich im Waisenhaus.\n\nEs ist nicht so übel, aber ich wollte schon immer gern die Welt sehen. Ich habe bisher nicht einmal einen Fuß aus der Stadt hinaus gesetzt. Ich habe schon eine Liste gemacht mit all den coolen Orten, die ich sehen will, und all den tollen Sachen, die ich machen möchte.\n\nIch bin bereit, wenn Ihr bereit seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[10943] = { id = 10943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kinderwoche", description = "Ein ganz besonderes kleines Mädchen wird sich sehr darüber freuen, Euch zum Freund zu haben, und sei es nur für eine kurze Zeit.\n\nNehmt diese Pfeife. Ihr könnt damit das Kind rufen, dessen Patenschaft Ihr übernommen habt. Diese Patenschaft wird nicht lange dauern, nur solange die Kinderwoche andauert.\n\nBitte, {name}, ruft Eurer Waisenkind herbei. Ich weiß, dass sie schon darauf brennt Euch kennenzulernen und die Chance zu haben, einen Blick auf die Welt außerhalb der Stadt zu werfen!", sourceObjective = "Benutzt die Pfeife des Draeneiwaisenkinds um Euren Schützling zu rufen, um den Ihr Euch während der Kinderwoche kümmern werdet.\n\nBereitgestellter Gegenstand:", completion = "Ihr müsst der Abenteurer sein, der in der Kinderwoche mein Pate ist! Ich bin Dornaa, freut mich sehr, Euch kennenzulernen.\n\n<Für einen Moment sieht sie sehr traurig aus.>\n\nMutter und Vater wurden im Krieg getötet. Ich bin schon mein ganzes Leben lang im Waisenhaus. Es ist wirklich schön dort, aber ich wollte schon immer gerne die Welt sehen.\n\nIch habe schon eine Liste mit all den Orten gemacht, die ich gerne sehen würde, wenn es Euch nichts ausmacht. Wir werden so viel Spaß zusammen haben!\n\nIch bin bereit, wenn Ihr bereit seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[10944] = { id = 10944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gefährdete Geheimnis", description = "Nochmals vielen Dank, {name}. Ich kenne Euren Namen. Akama hat Euch seine Pläne anvertraut, daher werde ich Euch ebenso vertrauen.\n\nDie Naga haben herausgefunden, dass ich gegen Illidan arbeite und mich grausamer Folter unterzogen. Sie haben jedoch nichts aus mir herausbekommen. Akama selbst hat mir beigebracht, wie man Schmerz mithilfe von Meditation überwindet.\n\nIllidan hat den Naga aufgetragen, mich zu ihm persönlich zu bringen. Er hätte mich sofort durchschaut und die tiefsten Geheimnisse meiner Seele gesehen.\n\nWir müssen Akama warnen! Unsere Pläne sind in Gefahr!", sourceObjective = "Reist zum Kerker des Wächters im Schattenmondtal und sprecht mit Akama.", completion = "Ich danke Euch, {name}. Olum ist einer meiner engsten Freunde und meiner treuesten Anhänger. Sein Beitrag zu unserem Werk ist für unsere Pläne unverzichtbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10945] = { id = 10945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hch'uu und das Pilzvolk", description = "Ich habe eine Freundin namens Hch'uu. Sie hat mir erzählt, dass sie im Waisenhaus gelandet ist, weil sie vor einem bösen Fungusgiganten fliehen musste und sich verlaufen hat.\n\nWir hatten sehr viel Spaß zusammen, bis ihr Volk sie letztes Jahr gefunden und mitgenommen hat. Ich glaube, sie haben sie an einen Ort namens Sporeggar gebracht.\n\nIch würde sie und das Pilzdorf gerne sehen. Die Waisenmatrone hat mir gesagt, dass es auf der westlichen Seite der Zangarmarschen liegt, zwischen dem Sporenwindsee und dem Sumpflichtsee.\n\nGehen wir dorthin? Gehen wir dorthin? Bitte?!", sourceObjective = "Bringt Euer Waisenkind Salandria nach Sporeggar in den Zangarmarschen. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt. Sprecht danach mit Hch'uu.", completion = "Vielen Dank, dass Ihr mir die Möglichkeit gegeben habt, Salandria wiederzusehen. Ich habe sie im letzten Jahr so sehr vermisst, aber wir sind immer noch gute Freunde.\n\nWir sind uns einig, dass wir, wenn wir groß sind, genauso mutige Abenteurer werden wollen, wie Ihr es seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[10946] = { id = 10946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die List der Aschenzungen", description = "Olums Opfer war gewaltig. Ich hätte ihn niemals gebeten, sein Leben für mich zu geben. Aber so ist es geschehen.\n\nWenn wir Illidan in falscher Sicherheit wiegen wollen, müssen wir seine Befehle ausführen, zumindest fürs Erste.\n\nIch befehlige eine große Armee von Aschenzungen, aber außer den Todeshörigen kann ich keinem davon trauen.\n\nIhr sollt die Tat, die Illidan wünscht, ausführen. Nehmt diese Gugel. Sie ist magisch. Jeder, der Euch Kaels Phönix Al'ar erschlagen sieht, wird Euch für einen meiner Männer halten.", sourceObjective = "Reist in die Festung der Stürme und tötet Al'ar, während Ihr die Gugel der Aschenzungen tragt. Kehrt nach Abschluß der Aufgabe zu Akama ins Schattenmondtal zurück.", progress = "Ist es vollbracht, {name}? Illidan ist kein besonders geduldiger Herr!", completion = "Das habt Ihr gut gemacht, {name}. Dies bringt uns einen Schritt näher, Illidans Blick abzuwenden. Von uns und von...\n\n\n\nEs liegt noch mehr Arbeit vor uns, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10947] = { id = 10947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Artefakt aus der Vergangenheit", description = "Dank Euch richtet sich Illidans Aufmerksamkeit nun auf Kael'thas. Es ist an der Zeit zu handeln!\n\nIn einer Vision sah ich ein mächtiges Artefakt, welches in unserem Entscheidungskampf von größter Bedeutung sein wird, das Phylakterium eines mächtigen Lichs, bekannt als Winterfrost. Leider ging es nach seiner Niederlage in der Schlacht um den Berg Hyjal für immer verloren.\n\nEs gibt jedoch einen Weg, um wieder an das Artefakt zu gelangen. Die Legenden sprechen von einem Ort in Azeroth, welcher von bronzenen Drachen bewacht wird... ein Ort an dem Vergangenheit und Gegenwart nebeneinander existieren. Dort werdet Ihr finden, was wir suchen!", sourceObjective = "Reist zu den Höhlen der Zeit in Tanaris und verschafft Euch Zugang zur Schlacht um den Berg Hyjal. Habt Ihr dies geschafft, so bezwingt Furor Winterfrost und bringt das zeitverzerrte Phylakterium zu Akama im Schattenmondtal.", progress = "Ist das Phylakterium bereits in Eurem Besitz, {name}?", completion = "Meine Vision... nun wird mir alles klar. Die Macht, die dieses Artefakt über eine Seele ausüben kann... sie einzuschließen... sie in sich selbst aufzunehmen... Ich werde diese Kraft dazu nutzen, um zurückzuholen, was rechtmäßig mir gehört! Der Augenblick ist gekommen, um den Kampf gegen Illidan aufzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10948] = { id = 10948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seelengeisel", description = "Ihr fragt Euch vielleicht, warum ich so weit gehe, um mein Vorhaben zu verschleiern. Warum arbeite ich nicht einfach offiziell mit den Naaru zusammen?\n\nMeine ureigene Essenz, meine Seele, wird im Schwarzen Tempel als Geisel gehalten. Mit einem Wimpernschlag könnte Illidan mich ausradieren... bis jetzt! Dieses Phylakterium wird es mir ermöglichen, meine Seele wieder in meine Kontrolle zu bringen.\n\nEs ist soweit, {name}. Ich werde Maiev und meine Todeshörigen bis an Illidans Türschwelle führen.\n\nSprecht mit A'dal und berichtet ihm von unserem Plan. Wenn wir gemeinsam zuschlagen, werden wir Illidans Verteidigung durchbrechen können.", sourceObjective = "Reist nach Shattrath und erzählt A'dal von Akamas Bitte.", completion = "<A'dals Licht umfängt Euch, als er Euch begrüßt. Ihr habt das Gefühl, dass er schon weiß, worum Ihr ihn bitten wollt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10949] = { id = 10949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zutritt zum Schwarzen Tempel", description = "<A'dal zeigt Euch ein Bild eines Naaru außerhalb des Schwarzen Tempels, der Seite an Seite mit Verteidigern der Draenei und Magistern der Blutelfen kämpft. Ihr wisst sofort, dass dies die Ablenkung ist, auf die Akama wartet.>", sourceObjective = "Reist zum Eingang des Schwarzen Tempels im Schattenmondtal und sprecht mit Xi'ri.", completion = "<Xi'ri scheint Eure Anwesenheit zu bemerken. Offensichtlich konzentriert er sich auf die Schlacht in der Umgebung.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10950] = { id = 10950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun und der Ring der Beobachtung", description = "Einer der Priester, der uns regelmäßig besucht, hat mir eine Geschichte über einen Ort in der Nähe erzählt. Er wird Auchindoun genannt und soll für die Draenei sehr wichtig sein.\n\nEr sagte, dass die Körper der verstorbenen Draenei an diesen Ort gebracht wurden. Aber vor einer Weile hat etwas Böses ihn in die Luft gejagt.\n\nIch würde dort gerne den Ring der Beobachtung sehen. Die Waisenmatrone hat mir gesagt, dass er in der Mitte der Knochenwüste liegt, auf der südlichen Seite der Wälder von Terokkar.\n\nKönnen wir dort bitte hingehen, <Herr/Frau> {name}?", sourceObjective = "Bringt Euer Waisenkind Dornaa zum Versammlungsstein beim Ring der Beobachtung in der Mitte von Auchindoun. Auchindoun liegt inmitten der Knochenwüste der Wälder von Terokkar. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt.", completion = "Oh, es ist wundervoll! Es sieht zwar ziemlich alt aus... und man sieht, dass es in die Luft gesprengt wurde. Aber schaut Euch doch nur um!\n\nOh, und habt Ihr Euch den Himmel angeschaut?\n\nKlasse!", sourceObjectiveStatus = "unverified-source-field" }
quests[10951] = { id = 10951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Reise zum Dunklen Portal", description = "Wie können wir uns all die interessanten Orte anschauen und dabei das Dunkle Portal vergessen?!\n\nDie Erwachsenen versuchen immer, uns Gruselgeschichten darüber zu erzählen, und schildern, wie gefährlich es dort ist mit den vielen Dämonen und all dem Zeugs.\n\n<Salandria rollt mit den Augen.>\n\nAber Ihr seid hier, also kann es ja nicht so schlimm sein, oder?\n\nIch will es selbst sehen. Könnt Ihr Euch noch erinnern, wo genau es sich am östlichen Rand der Höllenfeuerhalbinsel befindet?", sourceObjective = "Geht mit Eurem Waisenkind Salandria die Stufen des Schicksals hinauf und besucht das Dunkle Portal auf der Höllenfeuerhalbinsel. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt.", completion = "Dieser Ort ist so viel cooler als in den Geschichten. Es ist beeindruckend!\n\nIst es wahr, dass ein mächtiger Zauberer namens Medivh es erschaffen hat?\n\nIch frage mich, was wohl auf der anderen Seite ist. Ihr wart schon dort, nicht wahr? Hm, wir sollten ganz sicher an einen Ort auf der anderen Seite des Dunklen Portals gehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10952] = { id = 10952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Reise zum Dunklen Portal", description = "Es gibt einen Ort, den wir auf jeden Fall anschauen müssen: das Dunkle Portal!\n\nDie Waisenmatronen versuchen uns immer Gruselgeschichten darüber zu erzählen und wie gefährlich es dort ist mit vielen Dämonen und Leuten wie Euch, die hindurch kommen.\n\n<Dornaa rollt mit den Augen.>\n\nAber Ihr seid hier und Ihr seid nett, also kann es ja nicht so schlimm sein, oder?\n\nIch will es selbst sehen. Könnt Ihr Euch noch erinnern, wo genau es sich am östlichen Rand der Höllenfeuerhalbinsel befindet?", sourceObjective = "Geht mit Eurem Waisenkind Dornaa die Stufen des Schicksals hinauf und besucht das Dunkle Portal auf der Höllenfeuerhalbinsel. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt.", completion = "Die Geschichten der Waisenmatrone kommen diesem Ort nicht einmal im Geringsten nahe! Es ist beeindruckend! Sie hat gesagt, dass ein mächtiger Zauberer namens Medivh es erschaffen hat.\n\nWas ist auf der anderen Seite? Ihr wart schon dort, nicht wahr? Hm, wir sollten ganz sicher an einen Ort auf der anderen Seite des Dunklen Portals gehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10953] = { id = 10953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besuch beim Thron der Elemente", description = "Habt Ihr vom Thron der Elemente gehört? Er soll angeblich in Nagrand sein wo all die mächtigen Elementare sind.\n\nIch werde bald eine große Magierin oder eine Hexenmeisterin! Daher werde ich lernen müssen, wie man diese Elemente bändigt.\n\nKönnen wir vielleicht dorthin gehen?\n\n<Salandria schaut Euch listig an.>\n\nDas wäre fast schon eine Bildungsreise. Der Thron soll angeblich nördlich von Garadar sein, auf der anderen Seite des Himmelsweisensees.", sourceObjective = "Bringt Euer Waisenkind Salandria zum Thron der Elemente in Nagrand. Ruft sie herbei, falls sie nicht bei Euch sein sollte, wenn Ihr dort ankommt. Sprecht dann mit Elementaristin Sharvak.", completion = "Ihr bringt ein Kind hierher? Das ist ganz schön gewagt, aber ich verspreche Euch, dass Ihr nichts zustoßen wird, zumindest wenn sie Incineratus nicht zu nahe kommt.\n\nHm, welch Pech, dass sie eine Blutelfe ist. Könnte sie eine tiefere Verbindung zur Welt erlangen, könnten wir ihr vielleicht etwas beibringen, damit sie dabei helfen kann, die Wunden dieser Erde zu schließen. Aber vielleicht wird die Gegenwart der Elemente ihr ein paar Einblicke in ihre Natur geben.\n\nGeht in Frieden und kümmert Euch gut um sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[10954] = { id = 10954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jheel ist beim Aerissteg!", description = "Ich vermisse meinen Bruder Jheel. Er ist ein paar Jahre älter als ich und hat eine Ausbildung bei den Astralen in Nagrand angefangen.\n\nEs wäre so schön ihn einmal zu besuchen. Er liebt Geologie und so was, daher hat er bestimmt sehr viel Spaß.\n\nDie Waisenmatrone hat mir gesagt, dass er an einem Ort namens Aerissteg in Nagrand in Ausbildung ist. Er soll sich an der Straße weit westlich von Telaar und nordwestlich des großen Bergs Oshu'gun befinden.", sourceObjective = "Bringt Euer Waisenkind Dornaa zum Aerissteg in Nagrand. Ruft sie herbei, falls sie nicht bei Euch sein sollte, wenn Ihr dort ankommt. Sprecht dann mit Jheel.", completion = "Oh, ich habe Dornaa so sehr vermisst. Vielen Dank, dass Ihr mich mit ihr besuchen kommt. Ich bin hier nur von Astralen umgeben und fühle mich oft einsam. Sie sind sehr streng was die Geschäfte am Oshu'gun angeht.\n\nAber sobald mein Juwelenschleiferexamen abgeschlossen ist, werde ich auf einen Besuch ins Waisenhaus zurückkehren. Letzte Woche hätte ich fast bestanden, aber morgen werde ich es ganz sicher schaffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10955] = { id = 10955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morthis Flügelraunen", description = "Bevor die druidischen Orden sich zum Zirkel des Cenarius zusammenschlossen, brachten die Druiden der Kralle aufstrebenden jungen Druiden die Kunst des Fliegens bei. Nach der Auflösung des Ordens wurden die früheren Mitglieder was ihre Schüler angeht sehr wählerisch.\n\nMorthis Flügelraunen sucht noch immer nach einem würdigen Lehrling. Nur wenige Druiden haben je alle Formen beherrscht, die ihnen zur Verfügung stehen, doch Ihr versprecht das zu haben, wonach Morthis sucht. Sucht ihn bei der Zuflucht des Cenarius in den Zangarmarschen auf.", sourceObjective = "Sucht nach Morthis Flügelraunen in der Zuflucht des Cenarius in den Zangarmarschen.", completion = "<Morthis sieht Euch skeptisch an.>\n\nIch suche schon lange nach einem Schüler, dem ich mein Wissen weitergeben kann. Obwohl die Druiden der Kralle kein offizieller Orden mehr sind, werde ich bis ans Ende meiner Tage einer von ihnen sein.\n\nVon diesem Moment an nehme ich Euch als Schüler an. Ich werde Euch in die Geheimnisse der Sturmkrähe einweihen. Ihr müsst im Gegenzug bereit sein, alles, worum ich Euch bitte, zu tun. Habt Ihr das verstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[10956] = { id = 10956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sitz der Naaru", description = "Wisst Ihr etwas über die Naaru? Das sind diese engelhaften Wesen, die den Draenei schon lange Zeit helfen. Ich habe ein paar von ihnen in Shattrath gesehen.\n\nMan sagt, dass der Naaru O'ros dabei war, als die Exodar in Eure Heimatwelt gereist ist. Ich würde das gerne selbst sehen.\n\nKönnt Ihr mich dorthin bringen? Ich wette, wenn wir eines dieser Portale im Tempel des Mondes in Darnassus benutzen, sind wir ganz schnell! Und wenn wir da sind, können wir einfach Eure Karte anschauen, wenn wir uns verirren.", sourceObjective = "Bringt Euren Schützling Dornaa zu O'ros im unteren Teil des Sitzes der Naaru in der Exodar auf der Azurmythosinsel. Ruft sie herbei, falls sie nicht bei Euch sein sollte, wenn Ihr dort ankommt.\n\nVergesst nicht, dass Ihr in der Stadt Eure Karte verwenden könnt.", progress = "Ich habe Euch erwartet.", completion = "<Ihr spürt O'ros' melodische Stimme in Eurem Geist.>\n\nVielen Dank, dass Ihr dieses Kind zu mir gebracht habt, {name}. Sie ist in der Tat etwas ganz Besonderes und wird einst eine wichtige Persönlichkeit für die Draenei werden. Dies verdankt sie nicht zuletzt Eurer Freundlichkeit und dem Eindruck, den Ihr auf sie gemacht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10957] = { id = 10957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erlösung der Aschenzungen", description = "Als Illidan die Treue der Zerschlagenen erlangt hat, war Akama der Weiseste unter uns. Er wusste, dass eine direkte Konfrontation mit dem Verräter das Ende unseres Volkes bedeuten würde.\n\nStattdessen hat er diesen Moment in aller Verstohlenheit geplant und vorbereitet. Ein Versagen wäre eine Katastrophe... nicht nur für Akama, nicht nur für die Zerschlagenen, sondern für die gesamte Scherbenwelt. Niemand, der Illidan so nahe stand, war je in der Lage gewesen, ihm einen solchen Schlag zu versetzen.\n\nHelft Akama dabei, seine Seele zu befreien. Dann wird er Euch Zutritt zu Illidans Sanktum gewähren.", sourceObjective = "Helft Akama die Kontrolle über seine Seele wieder zu erlangen, indem Ihr Akamas Schemen im Schwarzen Tempel besiegt. Kehrt anschließend zu Seher Kanai zurück.", progress = "Ja, {name}?", completion = "Es ist vollbracht, {name}. Nun ist es an der Zeit, Illidan zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10958] = { id = 10958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht die Aschenzungen auf", description = "<Als Ihr zu Xi'ri aufblickt, schärft sich Euer Geist und Euer Wille wird stark. Eure Arbeit hier ist noch nicht vorüber. Ihr müsst in den Schwarzen Tempel gehen und Akamas Anhänger finden.>\n\n<Es hängt sehr viel von Akamas Erfolg ab.>", sourceObjective = "Sucht Akamas Todeshörige im Schwarzen Tempel.", completion = "Wir haben Euch bereits erwartet, {name}. Akama braucht dringend Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10959] = { id = 10959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sturz des Verräters", description = "Jetzt, da Illidans Leutnants besiegt sind, wird Akama die Türen zu Illidans Sanktum aufbrechen. Haltet Euch und Eure Streitkräfte bereit, um sofort hinein zu stürmen, sobald Akama es geschafft hat.\n\nWir wissen immer noch nicht, was aus Maiev geworden ist, aber wir müssen ohne sie beginnen.\n\nIch hoffe, dass Eure Streitkräfte der Sache gewachsen sind. Illidan wird nicht sehr erfreut sein, wenn er Akama zu Gesicht bekommt.", sourceObjective = "Seher Kanai möchte, dass Ihr Illidan im Schwarzen Tempel besiegt.", progress = "Ja, {name}?", completion = "Es ist geschehen, wie es vorherbestimmt war, {name}. Illidans Leutnants sind einer nach dem anderen gefallen... und sogar der Verräter fand den Tod!\n\nWisset eines, {name}: bei jeder Entscheidung, die Akama seit der Ankunft Illidans in seinem Leben getroffen hat, war dieser Augenblick sein Ziel. Illidan ist nun endlich tot und unser Volk... ist frei!", sourceObjectiveStatus = "unverified-source-field" }
quests[10960] = { id = 10960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn ich groß bin...", description = "Wusstet Ihr in meinem Alter schon, dass Ihr später mal <ein/eine:c> {class} werden wollt?\n\nIch weiß noch nicht, was ich einmal werden will. Vielleicht ein Magier oder Hexenmeister, wie ich vorhin schon sagte - oder vielleicht ein Paladin der Blutritter! Ja, ich will auf jeden Fall Blutritter werden!\n\nMan sagt, dass die echten Blutritter in Silbermond in Eurer Welt ausgebildet werden. Könnt Ihr mich dorthin bringen? Die Geschichten, die ich gehört habe, besagen, dass die Paladinlehrer sich auf dem Platz der Weltenwanderer in dieser Stadt aufhalten.\n\nBitte bringt mich dorthin. Bitte!", sourceObjective = "Bringt Euren Schützling Salandria zu den Paladinlehrern auf dem Platz der Weltenwanderer in Silbermond. Ruft sie zu Euch, falls sie nicht anwesend sein sollte, wenn Ihr ankommt. Sprecht danach mit Lady Liadrin, der Matriarchin der Blutritter.\n\nVergesst nicht, dass Ihr in der Stadt Eure Karte verwenden und die Wachen nach den Paladinlehrern fragen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10961] = { id = 10961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zauber des Erwachens", description = "Vor langer Zeit wurden die Relikte, mit deren Hilfe man den Weg der Sturmkrähe lehrte, einem uralten Druiden anvertraut.\n\nWir werden diese Relikte für Eure Ausbildung brauchen, daher müssen wir den Wächter aus seinem Schlummer erwecken.\n\nIch werde Euch einen Trank zubereiten, mit dessen Hilfe Ihr den Vorgang erleichtern könnt. Für das Gebräu benötige ich gewöhnliche Kräuter und Sumpfblüten, die auf den höchsten Pilzen in den Marschen wachsen. Fliegt an ihnen hoch und seid beim Sammeln der Blüten vorsichtig, {name}, sie sind ziemlich empfindlich und könnten bei falscher Handhabung heftig explodieren.", sourceObjective = "Bringt 10 Sumpfblüten, 10 Urflechten und 10 Traumwinden zu Morthis Flügelraunen in der Zuflucht des Cenarius.", progress = "Habt Ihr alle Zutaten, die ich für die Zubereitung des Tranks benötige? Vorsicht, bringt nur keine Pollen in meine Nähe, bitte. Ich muss deswegen immer furchtbar niesen.\n\n<Morthis schnüffelt gedemütigt bei einem Niesen.>", completion = "<Morthis nimmt die Kräuter entgegen und untersucht sie. Er holt eine Phiole hervor und beginnt den Trank zu mischen.>\n\nEs dauert nur einen Moment, {name}. Dann müsst Ihr zur Mondlichtung reisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10962] = { id = 10962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit die Höhlen zu besuchen", description = "Im Waisenhaus erzählt der alte Priester, der uns immer besuchen kommt, oft Geschichten über die Höhlen der Zeit. Er sagt, dass sie im Zentrum der Zeit liegen und unheimlich wichtig sind, damit alle Dinge ihren gewohnten Gang gehen.\n\nIch weiß nicht genau, was das heißt, aber er hat gesagt, dass es da Drachen gibt, die dabei helfen die Welt zu retten! Ich will einen Drachen sehen!\n\nKönnten wir da hingehen? Er sagte, dass der Eingang sich am östlichen Rand einer großen Wüste namens Tanaris befände.\n\nVielleicht könnt Ihr mir ja auch ein Andenken kaufen, während wir da sind?", sourceObjective = "Bringt Euren Schützling Dornaa zu Zaladormu, dem Drachen auf der Anhöhe in den Höhlen der Zeit. Ruft sie zu Euch, falls sie nicht anwesend ist, wenn Ihr ankommt.\n\nErwerbt danach für sie einen Spielzeugdrachen bei Alurmi, dem Rüstmeister der Hüter der Zeit, in der Nähe des Endes des Eingangstunnels.", progress = "Meint Ihr, dass die Geschichten über die Höhlen der Zeit stimmen?", completion = "Supi! Mein eigener Drache! Ich hoffe, dass ich eines Tages das Glück haben werde, einen Drachen zum Freund zu haben.\n\n<Dornaa springt fröhlich auf und ab und presst ihr neues Spielzeug fest an sich.>\n\nDas war der beste Ausflug meines ganzen Lebens! Hoffentlich ist er nie vorbei!", sourceObjectiveStatus = "unverified-source-field" }
quests[10963] = { id = 10963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit die Höhlen zu besuchen", description = "Im Waisenhaus erzählt der stinkende alte Priester, der uns immer besuchen kommt, oft Geschichten über die Höhlen der Zeit. Er sagt, dass sie im Zentrum der Zeit liegen und unheimlich wichtig sind, damit alle Dinge ihren gewohnten Gang gehen.\n\nIch weiß nicht genau, was das heißt, aber er hat gesagt, dass es da Drachen gibt, die dabei helfen die Welt zu retten! Ich will einen Drachen sehen!\n\nKönnten wir da hingehen? Er sagte, dass der Eingang sich am östlichen Rand einer großen Wüste namens Tanaris befände.\n\nVielleicht könnt Ihr mir ja auch ein Andenken kaufen, während wir da sind?", sourceObjective = "Bringt Euren Schützling Salandria zu Zaladormu, dem Drachen auf der Anhöhe in den Höhlen der Zeit. Ruft sie zu Euch, falls sie nicht anwesend ist, wenn Ihr ankommt.\n\nErwerbt danach für sie einen Spielzeugdrachen bei Alurmi, dem Rüstmeister der Hüter der Zeit, in der Nähe des Endes des Eingangstunnels.", progress = "Wenn das, was man über die Höhlen der Zeit sagt, stimmt, muss dieser Ort sehr mächtig sein!", completion = "Klasse! Mein eigener Drache! Eines Tages will ich einen echten besitzen.\n\n<Salandria schaut ihr neues Spielzeug scharf an. Fast hört man die Räder in ihrem Kopf rattern.>\n\nDas war der beste Ausflug meines ganzen Lebens! Ich hoffe, er geht nie vorbei!", sourceObjectiveStatus = "unverified-source-field" }
quests[10964] = { id = 10964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schläfer wecken", description = "Nehmt den Zauber mit Euch und reist zu Sturmgrimms Grabhügel auf der Mondlichtung. Im südlichsten Teil von Sturmgrimms Grabhügel, der von den Traumwächtern bewacht wird, werdet Ihr Clintar Traumwandler finden.\n\nGebt ihm den Zaubertrank und beschützt ihn, während er erwacht. Er wird sehr leicht verwundbar sein, während sein Geist sich mit seinem Körper verbindet, und Euch sicher nicht erkennen. Erklärt ihm, wer Ihr seid, wenn er zu Kräften kommt, {name}. Er wird Eure Hilfe brauchen, um die Relikte für das Ritual zu sammeln.", sourceObjective = "Benutzt den Zauber des Erwachens um Clintar Traumwandler aus dem Smaragdgrünen Traum zu holen. Sprecht mit ihm, sobald er zu sich kommt.", progress = "<Ihr bereitet Euch darauf vor, dem schlafenden Druiden den Zaubertrank zu verabreichen.>", completion = "<Der {class} erwacht aus seinem Schlaf und wirkt benommen und ausgezehrt. Sein Blick wandert auf der Suche nach unsichtbaren Verfolgern im Raum herum.>\n\nMorthis?\n\nNein, Ihr seid nicht Morthis... Wer seid Ihr, {race}, und warum stört Ihr meine Ruhe?", sourceObjectiveStatus = "unverified-source-field" }
quests[10965] = { id = 10965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als ein Traum", description = "<Clintar hört Euch nickend zu, als Ihr Morthis Anweisungen weitergebt, aber er scheint Angst zu haben.>\n\nIch kann mich nicht vollständig aus dem Smaragdgrünen Traum zurückziehen, um Euch zu helfen. Ich werde Euch jedoch ein Fragment meiner Seele auf der Suche nach den Relikten mitgeben. Passt gut darauf auf, {race}, denn mein Geist ist sehr zerbrechlich.\n\nDer Smaragdgrüne Traum selbst ist zu einem fremdartigen und gefährlichen Ort geworden. Er hält mich fest umklammert. Ich werde mich nicht lösen können, bis der Smaragdgrüne Traum wieder normal geworden ist. Was Ihr um Euch herum seht ist nur ein Nachhall der Wirklichkeit im Traum selbst!", sourceObjective = "Beschützt Clintar Traumwandlers Geist während er die Relikte von Aviana sammelt. Sprecht danach mit Traumwächter Lurosa.", progress = "Beeilt Euch, {race}. Wenn diese Kreaturen aus dem Grabhügel entkommen, ist nicht nur Clintar Traumwandler in Gefahr!", completion = "Ihr hattet Glück, dass Clintar stark genug war, seine Essenz so lange am Leben zu erhalten, {name}. Nur wenige Druiden schaffen das, während sie im Smaragdgrünen Traum angegriffen werden. Gebt gut auf die Relikte Acht!", sourceObjectiveStatus = "unverified-source-field" }
quests[10966] = { id = 10966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Waisenhaus", description = "Verdammt! Ich glaube, wir müssen zum Waisenhaus in Shattrath zurück.\n\nIch hatte so viel Spaß! Ihr seid <der/die> Tollste aller Welten, {name}! Ihr seid jetzt <mein großer Bruder/meine große Schwester>!\n\n<Dornaas Augen füllen sich mit Tränen.>\n\nIch werde Euch so vermissen! Wenn ich groß bin, will ich genauso sein wie Ihr!!!", sourceObjective = "Kehrt zum Waisenhaus in Shattrath zurück und übergebt die Pfeife Eures Schützlings an Waisenmatrone Gnädig im Unteren Viertel.", completion = "Es ist Balsam für die Seele zu wissen, dass es Helden wie Euch gibt, die ihre Zeit so selbstlos opfern.\n\nIch sehe jetzt schon, dass die Zeit mit Euch einen großen Eindruck auf Dornaa gemacht hat. Es ist schön, dass die Kinder eine Gelegenheit bekommen, einmal aus der Stadt heraus zu kommen und die Welt zu sehen.\n\nSie möchte, dass Ihr Euch um einen ihrer Lieblingsbegleiter kümmert, genauso, wie Ihr Euch um sie gekümmert habt. So könnt Ihr Euch immer an sie erinnern.\n\nSchaut doch ab und zu mal vorbei!", sourceObjectiveStatus = "unverified-source-field" }
quests[10967] = { id = 10967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Waisenhaus", description = "Verdammt! Ich glaube, wir müssen zum Waisenhaus in Shattrath zurück.\n\nIch hatte so viel Spaß! Ihr seid <der/die> Tollste aller Welten, {name}! Ihr seid jetzt <mein großer Bruder/meine große Schwester>!\n\n<Salandrias Augen füllen sich mit Tränen.>\n\nIch werde Euch so vermissen!!!", sourceObjective = "Kehrt zum Waisenhaus in Shattrath zurück und übergebt die Pfeife Eures Schützlings an Waisenmatrone Gnädig im Unteren Viertel.", progress = "Schön, Euch wiederzusehen, {class}. Hatten die kleine Salandria und Ihr eine schöne Zeit zusammen?", completion = "Es ist Balsam für die Seele zu wissen, dass es Helden wie Euch gibt, die ihre Zeit so selbstlos opfern.\n\nIch sehe jetzt schon, dass die Zeit mit Euch einen großen Eindruck auf Salandria gemacht hat. Es ist schön, dass die Kinder eine Gelegenheit bekommen, einmal aus der Stadt heraus zu kommen und die Welt zu sehen.\n\nSie möchte, dass Ihr Euch um einen ihrer Lieblingsbegleiter kümmert, genauso, wie Ihr Euch um sie gekümmert habt. So könnt Ihr Euch immer an sie erinnern.\n\nSchaut doch ab und zu mal vorbei!", sourceObjectiveStatus = "unverified-source-field" }
quests[10968] = { id = 10968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besucht den Scharfseher", description = "Ich spüre, dass dieses Kind etwas ganz besonderes ist.\n\nIhr solltet sie zu Scharfseher Nobundo hier auf der Exodar bringen. Ich glaube, dass er Euch beide schon erwartet.\n\nIhr findet Nobundo auf der höchsten Terrasse in der Kristallhalle.", sourceObjective = "Bringt Euren Schützling Dornaa zu Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel. Ruft sie zu Euch, falls sie nicht anwesend sein sollte, wenn Ihr ankommt.\n\nVergesst nicht, dass Ihr in der Stadt Eure Karte verwenden könnt.", completion = "Ich habe gehofft, doch gleichzeitig befürchtet, dass sie nur in meiner Fantasie existiert. Dieses Kind ist erstaunlich!\n\nBisher hat kein Draenei in diesem Alter und ohne Ausbildung eine so tiefe Verbindung zu den Elementen gezeigt. Sie muss ihre Fähigkeiten von einem uralten Vorfahren geerbt haben.\n\nIch werde der Weisenmatrone in Shattrath einen Brief schicken und sie darum bitten, dass das Kind bei uns bleiben kann.\n\nBitte sorgt bis dahin für ihr Wohlergehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10969] = { id = 10969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Ameer!", description = "Es scheint als ob eine außenstehende Macht Interesse an den Geschäftsmethoden des Konsortiums gewonnen hat. In den letzten beiden Tagen wurden fünf Händler des Konsortiums als vermisst gemeldet. Es besteht großer Grund zur Annahme, dass das Astraleum etwas damit zu tun hat. Wenn Ihr helfen möchtet, sucht nach Kommandant Ameer beim Wachposten des Protektorats.\n\nIhr findet den Wachposten des Protektorats östlich von hier auf der nächsten Insel.", sourceObjective = "Sucht Kommandant Ameer beim Wachposten des Protektorats auf.", completion = "Ja, das stimmt. Doch das Konsortium ist nicht die einzige Gruppierung, die Verluste zu vermelden hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10970] = { id = 10970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein barmherziger Auftrag", description = "Wir haben diese Gefängniskugel auf unserer letzten Spähermission im Gebiet des Astraleums sichergestellt. Hätte sie nicht dieses schwache Störsignal gesendet, hätten wir sie vielleicht nie gefunden.\n\nWir glauben, dass einer von uns darin eingesperrt ist, aber wir haben keine Möglichkeit die Kugel zu öffnen ohne den Inhalt zu verletzen.\n\nWir wissen nur, dass praktisch jedes Mitglied des Astraleums den Schlüssel dazu haben könnte. Beschafft Euch einen Schlüssel und bringt ihn zu uns, damit wir das Geheimnis der Kugel entschlüsseln können.", sourceObjective = "Beschafft Euch den sichergestellten Gefängnisschlüssel des Astraleums und bringt ihn zu Kommandant Ameer beim Wachposten des Protektorats im Nethersturm.", progress = "Hattet Ihr Glück?", completion = "Tretet zurück, {name}. Es könnte auch eine Falle des Astraleums sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10971] = { id = 10971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Astraleums", description = "<Ameer hält eine Marke hoch.>\n\nIch habe diese Identifizierungsmarke eines Gefangenen bei den Überresten des gefallenen Vorpostens gefunden. Ich gehe davon aus, dass alle ihre Gefangenen auf diese Weise markiert werden.\n\nIch werde damit anfangen, alle Marken zu katalogisieren. Vielleicht kann ich so etwas über das System ihrer Gefangennahmen herausfinden. Falls Ihr auf Euren Abenteuern noch mehr Gefängnisschlüssel des Astraleums finden solltet, könnt Ihr damit die Gefängnisse des Astraleums beim Stützpunkt des Astraleums direkt südlich von hier aufschließen. Bringt mir alle Identifizierungsmarken, die Ihr finden könnt!", sourceObjective = "Kommandant Ameer beim Wachposten des Protektorats im Nethersturm möchte, dass Ihr ihm eine Identifizierungsmarke eines Gefangenen des Astraleums bringt.", progress = "Habt Ihr ein paar Identifizierungsmarken finden können?", completion = "Es scheint sich hierbei um mehr als eine einfache Identifizierungsmarke zu handeln. Auf den Marken ist eine Art Code zu sehen. Ich stehe kurz davor, ihn zu entschlüsseln. Wenn ich doch nur mehr Marken hätte!", sourceObjectiveStatus = "unverified-source-field" }
quests[10972] = { id = 10972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katalog der Gefangenen des Astraleums", description = "Ich brauche mehr Identifizierungsmarken, {name}. Ich konnte bisher herausfinden, dass sie nicht nur die Gefangenen katalogisieren, sondern auch Aussagen über ihre Aufenthaltsorte machen!\n\nSobald wir diesen Code entschlüsselt haben, können wir genau feststellen, wo unsere Verbündeten festgehalten werden und sie mit minimalem Gewalteinsatz befreien.", progress = "Ich brauche mehr Identifikationsmarken, {name}. Ich konnte bisher herausfinden, dass sie nicht nur die Gefangenen katalogisieren, sondern auch Aussagen über ihre Aufenthaltsorte machen!\n\nSobald wir diesen Code entschlüsselt haben, können wir genau feststellen, wo unsere Verbündeten festgehalten werden und sie mit minimalem Gewalteinsatz befreien.", completion = "Wir sind der Wahrheit auf der Spur, {name}." }
quests[10973] = { id = 10973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tausend Welten", description = "Ich habe den Code entschlüsselt! Jede Marke ist in verschiedene Segmente geteilt. Die Vorderseite der Marke ist immer gleich. Darauf steht: \"Tausend Welten...\". Ich bin mir nicht sicher, was das zu bedeuten hat, aber es klingt irgendwie heimtückisch.\n\nAuf der Rückseite der Marke stehen die wichtigen Angaben. Die erste Gruppe von Runen gibt den Aufenthaltsort an, die zweite die Art der Gefangenschaft. Des Weiteren sieht es aus, als ob die Schlüssel zu einem besonderen Schlüssel zusammengefügt werden können, mit dem man eine andere Art von Gefängnis öffnen kann. Jetzt brauche ich noch mehr Schlüssel...", sourceObjective = "Kommandant Ameer am Wachposten des Protektorats im Nethersturm möchte, dass Ihr ihm 5 Gefängnisschlüssel des Astraleums bringt.", progress = "Ich weiß, dass ich Euch um viel bitte, aber denkt an all die Leben, die wir retten könnten!", completion = "<Ameer fügt die Schlüssel geschickt zusammen und betrachtet die Markierungen auf der so hergestellten Schlüsseltafel.>\n\n\"Tausend Welten zerschlagen, tausend weitere noch zu bezwingen... So lautet der Wille des Nexuskönigs.\"\n\n<Ameer dreht die Tafel um und liest die Rückseite.>\n\nStasiskammern von Bash'ir?", sourceObjectiveStatus = "unverified-source-field" }
quests[10974] = { id = 10974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stasiskammern von Bash'ir", description = "Das Astraleum hat eine kleine Siedlung am nördlichsten Rand des Schergrats, die als Landeplatz von Bash'ir bekannt ist. Laut der Schlüsseltafel soll es in Bash'ir noch größere Gefängnisse geben. Die Anhänger des Astraleums nennen sie Stasiskammern.\n\nDie Schlüsseltafel gewährt Zugang zu einer ganz bestimmten Stasiskammer am Landeplatz, die als Stasiskammer Alpha bekannt ist. Nehmt den Schlüssel und kundschaftet sie aus.\n\nMein Bild wird neben dem Landeplatz von Bash'ir auf Eure Rückkehr warten. Sprecht mit mir, wenn Ihr fertig seid.", sourceObjective = "Benutzt die Schlüsseltafel des Astraleums - Alpha um die Stasiskammer Alpha im Landeplatz von Bash'ir im Schergrat zu öffnen.\n\nBringt Beweisstücke aus Alpha zum Bild von Kommandant Ameer beim Landeplatz von Bash'ir.", progress = "Ihr habt es geschafft! Hattet Ihr Glück?", completion = "<Das Bild von Kommandant Ameer kramt in den Beweisstücken.>\n\nEs ist schlimmer als ich dachte... Diese Kammern enthalten wilde Bestien und Kreaturen von vielen verschiedenen Welten. Das Astraleum hofft, eines Tages Kontrolle über diese Bestien zu gewinnen und sie ihrem Willen zu unterwerfen. Wir müssen sie alle vernichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[10975] = { id = 10975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung der Kammern von Bash'ir", progress = "Wir sitzen in der Sackgasse, {name}. Die Daten, die Ihr gesammelt habt, haben uns genügend Informationen geliefert, um unsere Verbündeten aus den kleineren Gefängnissen des Nethersturms retten zu können. Wir müssen uns jedoch dringend um die Bedrohung kümmern, die von den Kammern hier im Ladeplatz von Bash'ir ausgeht.\n\nSchließt Euch dem Kampf gegen das Astraleum an! Bringt mir die Gefängnisschlüssel des Astraleums, damit ich Stasiskammerschlüssel für die Stasiskammern von Bash'ir für Euch herstellen kann.", completion = "Es gibt immer noch mehr Arbeit, die erledigt werden muss, {name}. Begebt Euch nun auf die Suche nach einer Stasiskammer und vernichtet, was auch immer darin lauern mag!" }
quests[10976] = { id = 10976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Abzeichen des Nexuskönigs", description = "Jetzt muss ich wissen, was das Astraleum in der Managruft in Auchindoun gefangen hält.\n\nVielleicht ist Euch in Euren Kämpfen gegen die Bestien der Stasiskammern von Bash'ir ein Gegenstand untergekommen, der als Abzeichen des Nexuskönigs bekannt ist. Wenn Ihr einen solchen Gegenstand finden solltet, bringt ihn sofort zu mir! Dieses Abzeichen ist der letzte Teil, den ich zur Herstellung eines Schlüssels brauche, der Euch Zugang zu der Stasiskammer in der Managruft gewähren wird.", sourceObjective = "Das Bild von Kommandant Ameer beim Landeplatz von Bash'ir im Schergrat möchte, dass Ihr ihm ein Abzeichen des Nexuskönigs bringt.", progress = "Dies wird Eure furchteinflößendste Aufgabe sein, {name}.", completion = "Endlich!\n\n<Kommandant Ameer liest die Inschrift auf dem Abzeichen des Nexuskönigs.>\n\nZwei Gefängnisse? Schon der Gedanke an die Schrecken, die darin hausen mögen, lässt mich erzittern...", sourceObjectiveStatus = "unverified-source-field" }
quests[10977] = { id = 10977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stasiskammern der Managruft", description = "Ich habe aus dem Abzeichen des Nexuskönigs einen neuen Schlüssel hergestellt, mit dem Ihr die Stasiskammern in der Managruft betreten könnt.\n\nLaut den Glyphen auf dem Abzeichen gibt es gleich zwei davon: eine in der Nähe der Vorderseite, eine weitere in der Nähe von Nexusprinz Shaffar. Der Schlüssel, den ich Euch nun geben werde, öffnet die Stasiskammer in der Nähe der Vorderseite.\n\nIch möchte, dass Ihr in die Managruft von Auchindoun reist und die Stasiskammer der Managruft öffnet.", sourceObjective = "Das Bild von Kommandant Ameer beim Landeplatz von Bash'ir im Schergrat möchte, dass Ihr den Stasiskammerschlüssel der Managruft verwendet, um die Stasiskammer in der Managruft Auchindouns zu öffnen.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ich könnte verstehen, wenn Ihr lieber nicht weitermachen wollt, {name}.", completion = "Ich habe von Euren Heldentaten erfahren, {name}. Haramad und ich sind uns beide einig, dass Ihr dafür eine großartige Belohnung verdient habt.\n\nObwohl... Ach, Ihr habt schon genug getan. Ich kann Euch nicht guten Gewissens um noch mehr bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10978] = { id = 10978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Morthis Flügelraunen", description = "Jetzt, da die Relikte geborgen wurden, müsst Ihr diesen Ort so schnell wie möglich wieder verlassen. Clintar hat seine eigene Sicherheit sowie die der Traumwächter für Euch aufs Spiel gesetzt, {name}. Nun muss er sich vollkommen auf den Kampf gegen die Macht konzentrieren, die in den Smaragdgrünen Traum eingedrungen ist.\n\nBringt die Relikte zu Morthis Flügelraunen und berichtet ihm, was Ihr hier gesehen habt. Vielleicht kann er uns dabei helfen herauszufinden, mit wem Clintar es zu tun hat.", sourceObjective = "Bringt die Relikte von Aviana zu Morthis Flügelraunen in der Zuflucht des Cenarius in den Zangarmarschen.", progress = "Hat Clintar Euch bei der Beschaffung der Relikte geholfen?", completion = "<Morthis nimmt Euch die Relikte ab, während Ihr Eure Erlebnisse in den Grabhügeln schildert.>\n\nDas sind äußerst beunruhigende Nachrichten, {name}. Es gab ein paar Störungen im Smaragdgrünen Traum, aber ich kann mich nicht entsinnen, dass je von einer außenstehenden Macht gesprochen wurde, die ihre Finger im Spiel hat. Seid Ihr sicher, dass Clintar es genau so gemeint hat?", sourceObjectiveStatus = "unverified-source-field" }
quests[10979] = { id = 10979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Ewigen Hain", description = "Seid Ihr sicher, dass Ihr einen Raben im Grabhügel gesehen habt?\n\nDas ist eine erschreckende Entwicklung. Wir können Clintar und den Traumwächtern nicht direkt helfen. Wenn wir jedoch herausfinden, was den Smaragdgrünen Traum bedroht, können wir es vielleicht aufhalten.\n\nWir haben erfahren, dass ein alter Arakkoakult im Schergrat wiederauflebt, der den Rabengott anbetet. Geht zum Ewigen Hain und sucht nach Arthorn Windweise. Vielleicht besteht zwischen den Geschehnissen dort und dem Angriff auf den Smaragdgrünen Traum eine Verbindung.", sourceObjective = "Sprecht mit Arthorn Windweise im Ewigen Hain im Schergrat.", completion = "<Arthorn hört aufmerksam zu. Ihr erklärt, dass Morthis Flügelraunen Euch geschickt hat, um zu untersuchen, ob zwischen dem Kult des Rabengottes und den merkwürdigen Geschehnissen auf der Mondlichtung ein Zusammenhang besteht. Die Nachricht erschüttert sie zwar, jedoch scheint es mehr an der Art und Weise der Botschaft selbst zu liegen.>\n\nOh mein...\n\nIch habe Timeon bei seinen Nachforschungen über den Rabenkult unterstützt. Ich hätte jedoch nie gedacht, dass der Rabe auch außerhalb des Schergrats Einfluss hätte!", sourceObjectiveStatus = "unverified-source-field" }
quests[10980] = { id = 10980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Buch des Raben", description = "Euren Erzählungen nach scheint Morthis mit seinen Verdächtigungen doch richtig gelegen zu haben. Wir brauchen jedoch Gewissheit.\n\nBei seinen Nachforschungen ist Timeon auf ein 'Buch des Raben' gestoßen, das angeblich ein altes Schriftstück des Kultes sein soll.\n\nDie Arakkoageister werden sich Euren Augen nicht zu erkennen geben. Begebt Euch mit diesem Stein zu den höchsten Gipfeln im westlichen Teil des Schergrats südlich des Rabenwaldes, beschafft Euch das Auge eines Ätherrochen und kombiniert beides, um Eure Sicht zu verstärken. Sucht nach dem Geist, den Timeon als Geist von Sai'kkal dem Ältesten identifiziert hat.", sourceObjective = "Benutzt das Auge eines Ätherrochen in Verbindung mit Eurem Stein des Sehers, um die Geister des Rabenkultes sehen zu können. Sucht beim Vortexgipfel nach dem Geist von Sai'kkal dem Ältesten und fragt ihn über das 'Buch des Raben' aus. Kehrt danach zu Arthorn Windweise zurück.", progress = "<Arthorn schaut Euch hoffnungsvoll an.>\n\nKonntet Ihr an Informationen über das Buch gelangen?", completion = "Ist es nicht erstaunlich, dass diese Kultisten sogar unter den Arakkoa als Ketzer galten? Dass der Hass der traditionellen Priester auf sie groß genug war um ihren heiligen Text zu zerstören ist unglaublich! Wir müssen an dieses Buch herankommen, {name}. Es ist der Schlüssel zum Geheimnis des Rabengottes. Damit werden wir verhindern können, dass er den Smaragdgrünen Traum an sich reißt.\n\nSollten wir Erfolg haben, wird Morthis mich vielleicht endlich als seinen Schüler akzeptieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[10981] = { id = 10981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nexusprinz Shaffars persönliche Kammer", progress = "Nur die standhaftesten und erfahrensten Abenteurer würden auf ein solches Angebot eingehen, {name}. Falls Ihr Euch den Schrecken der zweiten Stasiskammer der Managruft stellen wollt, kann ich einen Schlüssel dazu herstellen. Bringt mir ein Abzeichen des Nexuskönigs! Dann werde ich tun, worum Ihr bittet.", completion = "Und hier habt Ihr den versprochenen Schlüssel zu Shaffars persönlicher Stasiskammer." }
quests[10982] = { id = 10982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge des Haramad", sourceObjective = "Ihr habt viel für das Protektorat und das Konsortium getan, {name}. Daher ist es nur gerecht, dass einer unserer neuen Schlüssel an Euch geht. Mit diesem Schlüssel könnt Ihr Shaffars persönliche Stasiskammer jederzeit öffnen, ohne den Schlüssel dabei zu zerstören.\n\n\n\nEr ist von Dauer und wird auf ewig Euch gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[10983] = { id = 10983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mog'dorg der Weise", description = "Mog'dorg weise! Er schicken Grok in Stadt, Hilfe holen. Blutschlägerklan brauchen Hilfe.\n\nMog'dorg sagen, schicken mächtige Kleine zu ihm in Schergrat. Er stehen auf Turm bei Zirkel des Blutes. Mog'dorg weise!", sourceObjective = "Besucht Mog'dorg den Weisen auf einem der Türme außerhalb des Zirkels des Blutes im Schergrat.", completion = "Grok sagt, ich bin weise? Ich weiß ja nicht so recht.\n\nVielleicht liegt das daran, dass ich der Einzige meines Klans bin, der aufrichtig versucht uns vor der Vernichtung durch den Speerspießerklan zu retten. Und natürlich vor Gruul und seinen Söhnen, die sie unterstützen.\n\nIch hoffe, dass Ihr gekommen seid, um uns aus der unaufhaltsamen Verdammnis zu erretten, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10984] = { id = 10984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit dem Oger", description = "<V'erus Stimme erfüllt Euren Geist mit kristallener Melodie und Klarheit.>\n\nEs streunt ein Oger im Unteren Viertel umher, der alle Passanten um Hilfe anfleht. Doch keiner will seiner Not Gehör schenken. Könntet Ihr ihm vielleicht helfen?\n\nSein Name ist Grok. Er sitzt in der Nähe der Händler im Südwesten.\n\nSeid bedankt, {name}.", sourceObjective = "Sprecht mit dem Oger Grok im Unteren Viertel von Shattrath.", completion = "Ihr helfen Grok? Grok brauchen Hilfe! Blutschläger brauchen Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[10985] = { id = 10985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ablenkungsmanöver für Akama", description = "<Licht pulsiert um Xi'ri herum während die Streitkräfte der Aldor und der Seher seine Befehle ausführen. Xi'ris Armee ist bereit, Illidans Streitkräfte zurückzudrängen und Akama das nötige Ablenkungsmanöver zu verschaffen. Der Naaru wartet auf Eure Aufforderung den Angriff durchzuführen.>", sourceObjective = "Stellt sicher, dass Akama und Maiev den Schwarzen Tempel im Schattenmondtal betreten, nachdem Xi'ris Streitkräfte ihr Ablenkungsmanöver durchgeführt haben.", progress = "<Xi'ri registriert Eure Anwesenheit.>", completion = "<Xi'ri pulsiert vor Energie, Ihr fühlt, wie ein Gegenstand in Euren Händen Gestalt annimmt. Es ist das Medaillon, das Ihr A'dal im Namen von Akama gegeben habt. Seine Macht hat sich durch die Magie der Naaru noch verstärkt. Die Sha'tar haben Euch das Medaillon von Karabor anvertraut, und damit den Zugang zum Schwarzen Tempel.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10986] = { id = 10986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blick zum Himmel", description = "Alle Teile des Buchs des Raben zu finden wird schwierig. Wenn sie es überhaupt überleben. Wir benötigen schärfere Augen als Eure dafür.\n\nUnten im westlichen Nagrand, am östlichen Rand der Zwielichthöhe, untersucht Behüterin Elaira die lokalen Vogelarten. Sucht sie auf und schaut, ob sie Eure Vogelperspektive etwas verbessern kann, damit Ihr die Teile des Buchs des Raben finden könnt.", sourceObjective = "Sprecht mit Behüterin Elaira bei der Zwielichthöhe in Nagrand.", completion = "<Elaira hört Euch aufmerksam zu, als Ihr ihr von Eurer Suche nach dem Buch des Raben und Arthorns Vorschlag berichtet, die verschollenen Teile des Buchs mit Hilfe von Vögeln zu finden.>\n\nDas ist eine ausgezeichnete Idee. Nagrand ist voll von geeigneten Kandidaten für diese Aufgabe, aber welchen sollen wir wählen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10987] = { id = 10987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Spatz in der Hand", description = "Die wilden Sperber Nagrands haben von allen Raubvögeln hier die schärfsten Augen. Wegen Ihrer Größe wurden sie von den größeren Windrocs aus den meisten Gegenden verdrängt.\n\nDie meisten Sperber nisten hier auf der Zwielichthöhe. Wenn Ihr einen davon fangt, kann ich ihn so trainieren, dass er die Teile Eurer vergrabenen Tafel entdecken kann.\n\nDas wird allerdings nicht so einfach. Die Sperber sind sehr scheu und werden fliehen, sobald sie Euch sehen. Ich schlage vor, dass Ihr einen davon in die Enge treibt oder Euch nahe genug anschleicht, damit Ihr ihn mit einem Netz fangen könnt.", sourceObjective = "Benutzt das Sperbernetz um einen wilden Sperber zu fangen und bringt ihn zu Behüterin Elaira auf der Zwielichthöhe.", progress = "Habt Ihr einen Sperber fangen können?", completion = "Gut gemacht! Ich versuche immer noch, das Vertrauen der Sperber zu gewinnen, aber meine Kenntnisse über sie reichen bereits aus, um diesen hier für Eure Zwecke auszubilden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10988] = { id = 10988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rabensteine", description = "Ich habe Euren Sperber so dressiert, dass er auf einen bestimmten Pfeifton reagiert. Wenn er diesen Ton hört, wird der Vogel zu Euch fliegen und Euch zu dem nächsten Tafelfragment führen. Arthorn berichtete, dass die Tafelfragmente im Gebiet von Skettis in den südöstlichen Wäldern von Terokkar vergraben sind. Dort wird der Vogel auf Euch warten.\n\nBringt die Pfeife zurück zu Arthorn, wenn Ihr alle Steine zusammen habt. Sie wird sich darum kümmern, dass es dem Vogel gut geht und ihn in die Freiheit entlassen.\n\nRichtet Arthorn meine Grüße aus, wenn Ihr sie seht.", sourceObjective = "Sammelt 8 Rabensteine in Skettis und bringt sie zu Arthorn Windweise im Ewigen Hain im Schergrat.", progress = "Habt Ihr genügend Fragmente gesammelt, damit ich das Buch des Raben rekonstruieren kann?", completion = "<Arthorn nimmt Euch die Fragmente des Buchs des Raben ab und setzt sie zusammen.>\n\nEin Teil der Schrift ist verwittert, aber ich sollte das meiste davon entziffern können...", sourceObjectiveStatus = "unverified-source-field" }
quests[10989] = { id = 10989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mog'dorg der Weise", description = "Mog'dorg der Weise wartet auf Euch auf Spitze des Turms. Er mir aufgetragen, nach fähigen Helden wie Euch Ausschau zu halten. Ihr ihn in einer sehr wichtigen Sache sprechen müsst.\n\nGeht jetzt, aber erzählt niemandem davon! Es ist ein Geheimnis!", sourceObjective = "Sprecht mit Mog'dorg dem Weisen auf der Spitze des Turms außerhalb des Zirkels des Blutes im Schergrat, bei dem Chort sich aufhält.", completion = "Endlich hat Chort mir jemanden geschickt, der in der Lage sein könnte, mir zu helfen. Ich bin bemüht, die Blutschläger vor der Auslöschung durch die Speerspießer zu bewahren. Und natürlich durch Gruul und seine Söhne, die sie unterstützen.\n\nIch vertraue fest darauf, dass Ihr unserer Geheimorganisation helfen und uns in die Freiheit führen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10990] = { id = 10990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz des Adlers", description = "Das Buch des Raben berichtet, dass die Anhänger des Raben die Geister seiner Rivalen eingefangen und in kleinen Schreinen aus Stein gebannt haben. Jedem Schrein wurde ein Wächter zugeteilt, um zu verhindern, dass die Feinde des Raben sie befreien.\n\nDer erste dieser Schreine ist der des Adlers und befindet sich in den Hügeln südlich des Jorunesees und westlich der Steinbrecherfeste in den Wäldern von Terokkar.\n\nDie Tafel besagt, dass der Adler tapfer gekämpft hat, jedoch von einem Schwarm von Feinden überwältigt wurde. Die Rüstung und Belastbarkeit Eurer Bärenform ist für einen solchen Kampf bestens geeignet.", sourceObjective = "Besiegt den Wächter des Adlers und erlangt die Essenz des Adlers. Benutzt Arthorns Sperberpfeife, um Arthorns Sperber zu rufen, damit dieser die Kunde von Eurem Erfolg übermittelt.\n\nWenn Ihr die Pfeife verloren habt und Ersatz benötigt, sucht Arthorn Windweise im ewigen Hain auf.", progress = "<Der Sperber scheint mit Arthorns Stimme zu sprechen.>\n\nKonntet Ihr die Essenz des Adlergeistes befreien?", completion = "<Arthorn scheint die Macht der Essenz über die Sinne des Sperbers wahrzunehmen.>\n\nAuch tausende von Jahren der Gefangenschaft konnten die Macht des Adlergeistes nicht schmälern. Wenn die anderen Essenzen genauso stark sind wie die des Adlers, hat der Rabengott allen Grund Euch zu fürchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10991] = { id = 10991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz des Falken", description = "<Der Vogel spricht mit Arthorns Stimme.>\n\nDer zweite Geist, der von den Anhängern des Raben gebannt wurde, war der Geist des Falken.\n\nEr wurde zum Gedenken an die Priester des Raben, als sie noch über Macht verfügten, in der Nähe von Skettis eingesperrt.\n\nAm Ufer des Sees von Ere'Noru, im Nordwesten von Skettis, werdet Ihr den Schrein des Falken finden.\n\nUm den Wächter des Falken zu bezwingen, müsst Ihr die Kräfte des Falken zu Eurem Vorteil nutzen. Setzt die Schnelle und Anmut Eurer Katzengestalt ein, um den Wächter zu besiegen, bevor dieser seine volle Macht erlangt!", sourceObjective = "Besiegt den Wächter des Falken und erlangt die Essenz des Falken. Benutzt Arthorns Sperberpfeife, um Arthorns Sperber zu rufen, damit dieser die Kunde von Eurem Erfolg übermittelt.\n\nWenn Ihr die Pfeife verloren habt und Ersatz benötigt, sucht Arthorn Windweise im ewigen Hain auf.", progress = "<Wieder einmal erklingt Arthorns Stimme aus dem Schnabel des Sperbers.>\n\nHabt Ihr die Essenz des Falken?", completion = "<Der Sperber übermittelt Arthorns Worte.>\n\nGut gemacht, {name}. Ich hatte schon Angst, dass das Gefängnis des Falken bei der Explosion von Auchindoun zerstört wurde. Wir sind schon fast auf die Begegnung mit Anzu vorbereitet, {name}. Ich würde gerne mit Euch gehen, um da zu sein, wenn dieser selbst ernannte 'Gott' zurück in seine Grube getrieben wird, aus der er gekrochen ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[10992] = { id = 10992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz des Habichts", description = "<Arthorns Stimme richtet sich an Euch.>\n\nDer letzte und mächtigste Geist, der im Buch des Raben erwähnt wird, ist der Geist des Habichts. Man sperrte ihn in einen Schrein, fern von Skettis, auf einer entlegenen Insel südöstlich von Auchindoun.\n\nIch vermute, dass mit der Beschreibung nur eine Insel gemeint sein kann, die Stätte der Gramschwingen.\n\nDie Tafel beschreibt, dass die Krallen des Vogel dem Wächter des Habichts kaum einen Kratzer zufügen können. Verzichtet daher in dieser Schlacht auf körperliche Angriffe und beschwört zum Bezwingen dieses Feindes den Zorn der Sterne. Wiederholt den Fehler des Habichts nicht!", sourceObjective = "Besiegt den Wächter des Habichts und bringt die Essenz des Habichts zu Arthorn Windweise im Ewigen Hain.", progress = "Konntet Ihr den Wächter des Habichts besiegen und die Essenz besorgen?", completion = "Endlich haben wir alle Essenzen zusammen. Morthis Flügelraunen muss einen Weg finden, um sie in einem Amulett zu vereinen. Mit diesem Amulett könnt Ihr den Rabengott herausfordern, ihn aus dem Smaragdgrünen Traum locken und schließlich besiegen. Ich werde ihm meine Aufzeichnungen über die Geister zusenden, in der Hoffnung, dass er den Wert meiner Erkenntnisse zu schätzen weiß.\n\nEin jeder der Geister hat einen Glücksbringer gesegnet, den ich für Euch bereit hielt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10993] = { id = 10993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Zuflucht des Cenarius", description = "Bringt die Essenzen zu Morthis Flügelraunen und berichtet ihm von unseren Erkenntnissen über den Rabengott.\n\nMorthis weiß am besten, wie man die Essenzen und Informationen einsetzen kann, um Anzu hervorzulocken. Macht Euch schnell auf den Weg zu ihm. Keiner weiß, wie lange Clintar und die Traumwächter den Angriffen des Raben noch standhalten können!\n\n<Arthorn greift nach Eurem Arm als Ihr Euch zum Gehen abwendet.>\n\nBitte, {name}, erzählt Morthis wie sehr ich Euch geholfen habe. Ich fürchte, dass er mein Mitwirken nicht selbst erkennt!", sourceObjective = "Bringt Arthorns Päckchen zu Morthis Flügelraunen in der Zuflucht des Cenarius.", progress = "Ich habe auf Nachricht von Arthorn gewartet. Was habt Ihr herausgefunden?", completion = "<Morthis nimmt das Päckchen entgegen, entdeckt Arthorns Notizen und überfliegt sie, ohne etwas über den Absender verlauten zu lassen.>\n\nEinerseits ist es eine Erleichterung endlich zu wissen, wer unser Feind ist, doch dieser Anzu ist ein Wesen von nicht zu unterschätzender Macht. Es ist wichtig, das Wesen und den Namen seines Feindes zu kennen, aber wir sind noch nicht bereit, ihm entgegen zu treten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10994] = { id = 10994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Jagd nach dem Mondstein", description = "Wenn man die Essenzen mit einem seltenen Edelstein wie dem Mondstein des Südstroms verbindet, habt Ihr die Möglichkeit, sie im Kampf gegen Anzu freizulassen.\n\nDas einzige Problem dabei ist, dass die Mondsteine des Südstroms nur auf der Azsharaseite des Flusses auf den Klippen nahe der Flussquelle gefunden werden können.\n\nDen letzten Nachtelfenspähern, die nach den Steinen suchten, ist großes Unheil widerfahren. Ihr Boot liegt noch immer in der Nähe der Stelle, wo sie den Stein gesichtet haben, im Fluss. Haltet Eure Augen offen und nähert Euch der Fundstelle von Seiten Azsharas.", sourceObjective = "Bringt einen Mondstein des Südstroms zu Morthis Flügelraunen in der Zuflucht des Cenarius.", progress = "Ihr seht aus, als hättet Ihr einiges durchgemacht! War der Mondstein wirklich so schwer zu finden?", completion = "<Morthis scheint hin- und hergerissen. Einerseits möchte er über Eure Geschichte lachen, andererseits ist ihm bewusst, wie knapp Ihr mit dem Mondstein entkommen seid. Er begnügt sich damit, den leuchtenden Stein anzustarren.>\n\nIch werde mich daran machen, den Stein mit den Essenzen der Vögel zu erfüllen. Bald werdet Ihr bereit sein, den Rabengott herauszufordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[10995] = { id = 10995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grulloc hat zwei Schädel", description = "Im Osten, am Rand von Drachenend, könnt Ihr das Verfluchte Dunkel finden. An diesem Ort schmiedet Grulloc, Sohn des Gruul, seine dümmlichen Pläne.\n\nIch habe gehört, dass er trickreich um eines seiner Besitztümer gebracht wurde. Wart Ihr das etwa? Nur zu schade, dass er bei dieser Gelegenheit nicht gleich umgebracht wurde.\n\nWenn wir unsere Freiheit wiedererlangen wollen, müsst Ihr ihm seinen wertvollsten Besitz rauben: einen Drachenschädel, den er als Erinnerung an das Gemetzel seines Vaters am schwarzen Drachenschwarm bewahrt. Doch um an den Schädel heranzukommen, werdet Ihr ihn töten müssen.", sourceObjective = "Beschafft Euch Grullocs Drachenschädel.", progress = "Ist Grulloc schon Geschichte?", completion = "Das muss ein harter Kampf gewesen sein, {class}. Ich bin sehr erleichtert, dass er uns nun nicht mehr auf die Pelle rücken wird.\n\nIch werde diesen Schädel zu Chort schicken, damit er auf ihn aufpasst. Ich glaube, dass wir unser Ziel mit eurer Hilfe erreichen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[10996] = { id = 10996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maggocs Schatztruhe", description = "Im Messergrat über uns und im Südosten zieht Maggoc seine Kreise. Sein Vater hat ihn zum Wächter des östlichen Teils der Berge erkoren, und er benutzt sein Amt, um jegliches Wesen zu terrorisieren, das ihm in die Quere kommt.\n\nAls Sohn des Gruul muss auch er verschwinden, damit mein Klan überleben kann. Und da kommt Ihr ins Spiel.\n\nMaggoc trägt stets eine Schatztruhe bei sich. Beweist mir, dass Ihr ihn umgebracht habt, indem Ihr mir seine teure Truhe bringt. Was auch immer Ihr darin finden mögt, dürft Ihr gerne behalten.", sourceObjective = "Beschafft Euch Maggocs Schatztruhe.", progress = "Habt Ihr die Truhe?", completion = "Sie war leer? Was ein Pech! Aber nun habt Ihr eine Ahnung von der sinnlosen Gewalt, unter der wir leiden müssen.\n\nJetzt, da Maggoc tot ist, sind wir meinem Traum von einem Zuhause, in dem wir Oger unser Schicksal selbst schmieden können, einen entscheidenden Schritt näher gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10997] = { id = 10997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sogar ein Gronn hat Standards", description = "Kennt Ihr Euch in Shattrath aus, {class}? Über der Stadt im Nordwesten gibt es einen Ort, den man die Hügelwand nennt. Man kann nur mit einem fliegenden Reittier dorthin gelangen.\n\nEiner der Söhne Gruuls, Slaag, hat sich selbst ins Exil dorthin begeben und die Herrschaft über die Oger der Gordunni, die dort leben, an sich gerissen. Auch wenn er so weit entfernt lebt, können wir ihn nicht am Leben lassen. Er könnte zurückkommen, wenn er erfährt, dass seine Brüder tot sind!\n\n{name}, Ihr müsst dorthin reisen und seine Standarte als Beweis für seinen Tod mitbringen.", sourceObjective = "Beschafft Euch Slaags Standarte.", progress = "Haltet Ihr Slaags Standarte schon in Euren Händen?", completion = "Ich bin erleichtert, dass Slaag nicht mehr unter uns weilt. Nun müssen wir nicht länger in Angst vor seiner drohenden Rückkehr leben!\n\nWenn Ihr nichts dagegen habt, würde ich die Standarte gerne als Symbol der Hoffnung für alle Oger dieser Berge entgegennehmen.\n\nVielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10998] = { id = 10998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den übelsten Kreisen", description = "Es gibt einen weiteren Gronn, der getötet werden muss: Skulloc Seelenschänder. Er weiß sich zu verstecken, doch es gibt einen Weg, ihn hervorzulocken.\n\nEr wurde von einem Ogerhexenmeister namens Vim'gol der Üble ausgebildet, an dessen Zauberfolianten Ihr gelangen müsst!\n\nMan beschwört Vim'gol, indem man innerhalb eines Feuerkreises bei seinem Zirkel steht. Findet Vim'gols Kreis in den Bergen im Nordosten, nahe der Zerschlagenen Wildnis.", sourceObjective = "Beschafft Euch Vim'gols üblen Zauberfolianten.", progress = "Habt Ihr Vim'gol den Üblen beschworen und seinen toten Klauen den Zauberfolianten entrissen?", completion = "Ich scheue mich davor, ein Ding von solcher Abscheulichkeit auch nur anzufassen. Und doch müssen wir den Folianten lesen, wenn wir sein Wissen erkunden und Skulloc aus seinem Versteck locken möchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10999] = { id = 10999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schuss, ein Treffer", description = "Bringt mir 8 Troggsteinzähne." }
quests[11000] = { id = 11000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schänder der Seelen", description = "Der Zauberfoliant ist der Schlüssel zu Skullocs Untergang.\n\nUm das Ritual zu beginnen, müsst Ihr am Hügel des Seelenschänders laut aus dem Buch vorlesen. Daraufhin werden der Geist des Seelenschänders sowie die Geister seiner Opfer erscheinen. Sie werden versuchen, den Seelenschänder zu vernichten. Ihr müsst sie so lange daran hindern, bis Skulloc vollständig in diese Welt übergetreten ist.\n\nDurchquert den Dolchrachenklamm Richtung Norden. Ihr findet den Grabhügel auf der anderen Seite des Zirkels des Blutes auf der rechten Seite vor Gruuls Unterschlupf.\n\nBringt mir Skullocs Seele!", sourceObjective = "Beschafft Euch Skullocs Seele.", progress = "Habt Ihr Skullocs Seele schon geraubt?", completion = "Es ist also vorüber. Ihr habt uns von den Fesseln der Sklaverei durch die Söhne von Gruul befreit. Ihr habt den Klan der Blutschläger vor der sicheren Auslöschung bewahrt.\n\nEs gibt keine Worte um zu beschreiben, wie tief ALLE Oger des Schergrats, Blutschläger wie Speerspießer, in Eurer Schuld stehen, {name}.\n\nSchaut dort, wie all die Oger sich versammeln um Euch Tribut zu zollen! Sollen Gruul und seine Marionette, der alte König Maulgar, sich ruhig in ihrem Unterschlupf verkriechen. Geht zu den Ogern als ihr neuer König!", sourceObjectiveStatus = "unverified-source-field" }
quests[11001] = { id = 11001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet den Rabengott", description = "Wir haben bei der Vernichtung des Rabengottes keine Zeit zu verlieren. Ihr müsst den mit Essenz erfüllten Mondstein zu einem Ort von großer Macht bringen, um den Gott aus der relativen Sicherheit des Smaragdgrünen Traums zu locken.\n\nSteigt in die Sethekkhallen hinab und setzt den Mondstein in die Fänge der Rabenklaue ein. Ihr findet den Raum vor der Halle des Klauenkönigs.\n\nAnzu muss glauben, dass seine Anhänger sich versammelt haben, um ihn wieder in dieser Welt willkommen zu heißen. Zeigt keine Gnade, sobald er sich manifestiert hat!", sourceObjective = "Tötet den Rabengott und kehrt dann zu Morthis Flügelraunen bei der Zuflucht des Cenarius zurück.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Was gibt es neues aus den Sethekkhallen? Habt Ihr Anzu besiegt?", completion = "Schön, Euch wiederzusehen, {name}. Euer Sieg über den Rabengott ist weit mehr als nur ein Test oder ein Aufnahmeritual.\n\nIhr habt Euch als würdig bewiesen, das Wissen, das die Druiden der Klaue seit unzähligen Generationen bewahren, zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11002] = { id = 11002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magtheridons Untergang", description = "Nun ist die Quelle von Illidan Sturmgrimms Höllenorcarmee versiegt. Die Manufaktur hat die Produktion ihres üblen Erzeugnisses gestoppt - zumindest fürs Erste. Jetzt sind nur noch Schrott und dieser abgetrennte Kopf übrig. Welch passende Trophäe für einen Helden der Allianz!\n\nBringt Magtheridons Kopf zu Danath Trollbann in der Ehrenfeste.", sourceObjective = "Bringt Magtheridons Kopf zu Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", progress = "Zum ersten Mal seit ich mich erinnern kann herrscht Stille.", completion = "Dieser Sieg ist nicht nur ein Schlag gegen Illidan, {name}. Auch die Legion schwankt... Ein Kommandant der Grubenlords wurde vernichtet. Die Belagerung der Höllenfeuerzitadelle ist jetzt für die Brennende Legion nicht länger von Bedeutung. All ihre Bemühungen werden sich nun ohne Zweifel auf den Schwarzen Tempel konzentrieren.\n\nFür Illidan kommt der Tag der Abrechnung... schon bald.", sourceObjectiveStatus = "unverified-source-field" }
quests[11003] = { id = 11003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magtheridons Untergang", description = "Nun ist die Quelle von Illidan Sturmgrimms Höllenorcarmee versiegt. Die Manufaktur hat die Produktion ihres üblen Erzeugnisses gestoppt - zumindest fürs Erste. Jetzt sind nur noch Schrott und dieser abgetrennte Kopf übrig. Welch passende Trophäe für einen Helden der Horde!\n\nBringt Magtheridons Kopf zu Nazgrel in Thrallmar.", sourceObjective = "Bringt Magtheridons Kopf zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Zum ersten Mal seit ich mich erinnern kann herrscht Stille.", completion = "Dieser Sieg ist nicht nur ein Schlag gegen Illidan, {name}. Auch die Legion schwankt... Ein Kommandant der Grubenlords wurde vernichtet. Die Besetzung der Höllenfeuerzitadelle ist jetzt für die Brennende Legion nicht länger von Bedeutung. All ihre Bemühungen werden sich nun ohne Zweifel auf den Schwarzen Tempel konzentrieren.\n\nFür Illidan kommt der Tag der Abrechnung... schon bald.", sourceObjectiveStatus = "unverified-source-field" }
quests[11004] = { id = 11004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenwelt", description = "Himmelskommandant Adaris wurde bei einem Überfall der Skettis schwer verletzt. Seitdem hat er immer und immer wieder sein Bewusstsein verloren.\n\nIch befürchte, dass er Opfer einer Fieberphantasie wurde. In seinen wenigen wachen Momenten bat er mich darum, ein Elixier aus Schattenstaub herzustellen, wie ihn die Arakkoa bei sich tragen. Er scheint zu glauben, dass er dank des Elixiers in eine Art \"Schattenwelt\" sehen könne, in welcher die wahren Anführer der Arakkoa hausen.\n\nIch schenke diesem Unsinn natürlich keinen Glauben, fürchte jedoch, dass er nicht eher ruhen wird, bis er eines dieser Elixiere in Händen hält. Werdet Ihr uns helfen?", sourceObjective = "Severin möchte, dass Ihr nach Skettis reist und 6 Einheiten Schattenstaub von den dort lebenden Arakkoa sammelt.", progress = "Habt Ihr den Staub, {name}?", completion = "Ich danke Euch, {name}. Ich werde dem Kommandanten eine kleine Menge zukommen lassen... damit er seinen Willen bekommt. Ihr könnt den Rest behalten, vielleicht findet Ihr ja eine Verwendung dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[11005] = { id = 11005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse der Krallenpriester", description = "Danke, dass Ihr mir im Fieberwahn zugehört habt. Schon seit geraumer Zeit versuchen wir die Kommandokette der Skettis aufzudecken und sie zu zerschlagen. Wir wussten von der Existenz dreier Kleriker, den Krallenpriestern, jedoch haben wir niemals einen von ihnen zu Gesicht bekommen. Nun wissen wir warum.\n\nSprecht mit Severin und beschafft Euch mehr von seinem Elixier. Verwendet das Elixier, um die drei Krallenpriester, Ishaal, Skizzik und Zellek ausfindig zu machen und zu töten. Gerüchten zur Folge findet man sie im Ala'rakversteck, am östlichen Ufer des Schattenwindsees.", sourceObjective = "Beschafft Euch von Severin ein Elixier der Schatten und verwendet es, um Krallenpriester Ishaal, Krallenpriester Skizzik und Krallenpriester Zellek in Skettis ausfindig zu machen und sie zu töten. Kehrt nach Abschluss Eurer Aufgabe zu Kommandant Adaris zurück.", completion = "Ihr habt Euch mit Bravour geschlagen, {name}. Durch den Verlust der Krallenpriester wurde dem Feind ein empfindlicher Schlag versetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11006] = { id = 11006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Schattenstaub", progress = "Der Kommandant scheint doch nicht aus einem Fieberwahn heraus gesprochen zu haben. Bringt mir mehr Staub und ich werde ein weiteres Elixier für Euch herstellen.", completion = "Ihr könnt mir auch weiterhin noch Staub bringen. Ich werde so viele Elixiere für Euch herstellen, wie Ihr benötigt.\n\nAuf Befehl des Kommandanten." }
quests[11007] = { id = 11007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kael'thas und die tiefgrüne Sphäre", description = "Die Luft um Euch herum ist von einem Summen erfüllt - einem freundlichen Summen. Die Naaru wissen von Eurem Sieg. Vielleicht sind sie der Grund für Euer Bedürfnis, die Sphäre inmitten der immer noch zuckenden Überreste von Kael'thas Sonnenwanderer aufzuheben. Welche Geheimnisse mögen darin stecken?\n\nVielleicht weiß A'dal in Shattrath mehr über diesen Gegendstand.", sourceObjective = "Bringt die tiefgrüne Sphäre zu A'dal in Shattrath.", progress = "Ihr habt meinen Ruf vernommen? Ja...", completion = "<A'dals Gedanken vermischen sich mit den Euren.>\n\nDie Sphäre... Sonderbar. Wusstet Ihr, dass er überlebt hat? Ja. Hier drin, in der Sphäre selbst. Ganz sicher verstümmelt. Er gehorcht nun einer höheren Macht. Nein, nicht Illidan.\n\nHöher.\n\nKil'jaeden der Betrüger kommt...\n\nNicht hierher...\n\n<A'dal führt Euren Geist an einen anderen Ort.>\n\nAzeroth. Unbekannt.\n\nRuht Euch aus. Eure Brüder und Schwestern werden die Festung der Stürme wieder übernehmen.\n\n<A'dal summt eine Kriegshymne.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11008] = { id = 11008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer über Skettis", description = "Glaubt Ihr, dass Ihr das Zeug dazu habt, ein Teil der Himmelswache zu sein? Wir werden überprüfen müssen, wie gut Ihr in der Luft zurechtkommt.\n\nDie Arakkoa züchten eine gigantische Menge von ihren Kampfvögeln, die sie auf unsere Späher hetzen! Ich möchte, dass Ihr diese Sprengladungen nehmt und ihre Brutstätten über den Siedlungen der Arakkoa zerstört. Macht aber einen Bogen um die monströsen Kaliri, welche die Brutstätten bewachen. Sie werden Euch vom Reittier holen, bevor Ihr wisst, wie Euch geschieht!", sourceObjective = "Haltet nach monströsen Kalirieiern oben in den Siedlungen von Skettis Ausschau und benutzt die Sprengladungen der Himmelswache, um sie in die Luft zu sprengen. Kehrt danach zu Himmelsoffizier Doryn zurück.", progress = "Habt Ihr Euren Auftrag schon erledigt?", completion = "Ausgezeichnete Arbeit, {name}! Das wird diesen Vogelwesen zeigen, wer die wahren Herren der Lüfte sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[11009] = { id = 11009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerhimmel", description = "Jetzt, da Ihr uns aus der Knechtschaft befreit habt, können wir mit der Wiedervereinigung der Klans beginnen. Es wird einige Zeit dauern; lange geschürter Zorn kühlt nur langsam wieder ab.\n\nEs ist umso eiliger, dass Ihr nach Ogri'la, hoch oben im Westen, reist. Verteidigt es und uns so gut, wie Ihr könnt. Schützt uns vor den Mächten, wie es einst die Gronn taten: Astrale, Dämonen und noch viel schlimmer, der schwarze Drachenschwarm, erwarten Euch.\n\nSolltet Ihr den Himmel der Oger gefunden haben, ersucht Chu'a'lor um Rat für die weitere Vorgehensweise.", sourceObjective = "Mog'dorg der Weise hat Euch gebeten, mit Chu'a'lor in Ogri'la im Schergrat zu sprechen.", completion = "Mog'dorg hat eine Nachricht voraus geschickt, um mich über Euer Kommen zu informieren. Ich bin froh, dass Ihr hier seid.\n\nNach dem Fall der Söhne des Gruul, ist es nur noch eine Frage der Zeit - es dürfte nicht sehr lange dauern - bevor die unterschiedlichen Bewohner dieser Bergterrasse und die des Nordens beginnen, Jagd auf unsere Ogerbrüder dort unten zu machen.\n\nDies gilt es zu verhindern und ich vertraue auf Eure Unterstützung, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11010] = { id = 11010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomberangriff", description = "Ihr habt ein fliegendes Reittier... ja und! Glaubt Ihr denn, dass Ihr das Zeug dazu habt, es gekonnt einzusetzen?\n\nDas Konstruktionslager: Wut und das Konstruktionslager: Terror, im Norden und im Süden, sind mir schon seit langem ein Dorn im Auge und obendrein bedrohen sie das friedliche Ogri'la. Mit all diesen Teufelskanonen, die die Himmelswache von rechts und links unter Beschuss nehmen, gibt es einfach kein Hindurchkommen und unser Unterfangen ist zum Scheitern verurteilt.\n\nWürdet Ihr Euch gerne unter Beweis stellen? Nehmt diese Bomben und vernichtet ihre Munitionsvorräte. Lasst Euch aber nicht auch noch vom Himmel herunterholen!", sourceObjective = "Vernichtet mithilfe der Bomben der Himmelswache 15 Stapel mit Teufelskanonenkugeln.", progress = "Habt Ihr schon ihre Stapel mit Teufelskanonenkugeln vernichtet?", completion = "Gut, gut, scheinbar seid Ihr doch härter im Nehmen als ich dachte. Ausgezeichnete Arbeit. Möglicherweise hatte der alte Keller doch Unrecht, was Euch anbelangt.\n\n<Himmelsoffizier Vanderlip grinst.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11011] = { id = 11011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Wachsamkeit", description = "Euer Sieg über Anzu, den Rabengott, ist eine wahrhaft heldenhafte Leistung. Ich fürchte allerdings, dass er nicht aufgeben und weiterhin versuchen wird, in die Scherbenwelt zurückzukehren.\n\nSolange seine Gefolgsleute am Leben sind, wird er sich immer wieder erheben. Daher solltet Ihr den mit Essenz erfüllten Mondstein stets bei Euch haben, falls Anzu sich erneut regt.", sourceObjective = "Sprecht mit Morthis Flügelraunen, um einen mit Essenz erfüllten Mondstein zu erhalten.", completion = "Behaltet den Mondstein bei Euch, {name}. Wenn Ihr glaubt, dass Anzu seine Kräfte sammelt, um in diese Welt zurückzukehren, verwendet den Stein um ihn zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11012] = { id = 11012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blutschwur der Netherschwingen", sourceObjective = "Unser Land ist verloren. Man entführt unsere Kinder in der Nacht, versklavt sie - oder schlimmer...\n\n<Mordenais Stimme wird angespannt.>\n\nEs ist an der Zeit, mein Freund. Zeit, uns wieder das zu nehmen, was einst unser war! Ihr habt Euch als tapferer Kämpfer und verständnisvolle Seele erwiesen.\n\nWerdet Ihr schwören, dem Drachenschwarm der Netherschwingen beim Kampf um unser Land und den Wiederaufbau unserer Heimstätten zu helfen? Werdet Ihr schwören, über den Schwarm zu wachen, damit unser Fleisch und Blut aufs Neue zum Leben erwachen kann? Schwört und lasst uns im Namen unserer Heimat und unserer Familien kämpfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11013] = { id = 11013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste der Illidari", description = "Die Netherschwingenscherbe... Was einst eine Feste der Zuflucht für die Netherschwingen war, ist nun das Zuhause des Drachenmalklans. Die Orcs haben vielleicht die Kontrolle über unser Land gewonnen, unsere Magie ist dort jedoch noch stark. Stark genug, um Eure wahre Identität zu verschleiern und um Euch in die Ränge des Drachenmalklans einzuschleusen.\n\nIch habe dieses Schreiben für Euch aufgesetzt, überreicht es ihrem Anführer, Oberanführer Mor'ghor. Fliegt den Fängen unseres Feindes entgegen, reist zum Basislager des Drachenmals und beginnt Euer neues Leben als Höllenorc Illidan Sturmgrimms.", sourceObjective = "Reist zur Netherschwingenscherbe und überreicht Oberanführer Mor'ghor beim Basislager des Drachenmals das Empfehlungsschreiben der Illidari.", progress = "<Mor'ghor grunzt.>\n\nIhr seid spät...", completion = "<Mor'ghor überfliegt das Schreiben und lacht.>\n\nEin Todesritter? Ihr könnt einem Todesritter nicht mal das Wasser reichen, Wurm.\n\n<Mor'ghor mustert Euch scharf.>\n\nNun gut... Ihr könntet es vielleicht noch zum Peon schaffen. Im schlimmsten Fall werfe ich Euch in die Grube und lasse Euch dort verrotten...", sourceObjectiveStatus = "unverified-source-field" }
quests[11014] = { id = 11014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Höhle des Löwen", description = "<Mor'ghor zerknüllt das Empfehlungsschreiben und wirft es beiseite.>\n\nAlso Grunzer, eins nach dem anderen. Wenn Ihr meiner teuren Armee des Drachenmals beitreten wollt, dann müsst Ihr arbeiten. Jeder arbeitet hier auf der Scherbe. Sucht Euch Arbeit und seht zu, dass Ihr Euch nicht zu dämlich anstellt. Eventuell werde ich Euch später mit interessanteren Dingen beauftragen.\n\nSprecht mit Zuchtmeister Varkule Drachenodem, er steht in der Mitte des Lagers. Nach Einschätzung Eurer Fertigkeiten, wird er Euch eine entsprechende Arbeit zuteilen.\n\nUnd jetzt verschwindet!", sourceObjective = "Sprecht mit Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals.", completion = "Varkule findet schon was für Euch, Grunzer. Euch steht eine Aufgabe zu, die Euren Fertigkeiten am besten gerecht wird und unserer Kristallförderung zu Gute kommt. Ihr müsst Euren Arbeitsauftrag einmal am Tag ausfüllen.\n\nJa, es gibt da einen Haufen Drecksarbeit zu erledigen, aber auch die Ahnen haben mal als Peon begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11015] = { id = 11015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristalle der Netherschwingen", description = "Ihr taugt zu nichts, was? In Ordnung, auch Vollidioten wie Ihr können uns hier noch zur Hand gehen. Sucht auf der Scherbe einfach nach Kreaturen und tötet sie. Manchmal befinden sich auf ihren Körpern Kristalle der Netherschwingen. Sammelt und bringt sie mir, dann habt Ihr Euren Arbeitsauftrag für heute erledigt.", sourceObjective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 30 Kristalle der Netherschwingen bringt.", progress = "Kristalle der Netherschwingen werden für vielerlei Dinge verwendet. Hauptsächlich zur Herstellung von Waffen und Rüstungen...", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11016] = { id = 11016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balg eines Netherminenschinders", description = "Ein Kürschner, ja? Nun, Ihr werdet hier mehr als genug Häutbares finden! Sucht in der Nähe der Kristallformationen nach Schindern. Tötet sie und nehmt ihre Bälge an Euch. Vielleicht sind die ein oder anderen sogar etwas wert, bringt mir genau diese.", sourceObjective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 35 Bälge eines Netherminenschinders bringt.", progress = "Wir verwenden die Bälge von Schindern zum Ausfüttern von Rüstungen und die Herstellung von Planen.", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11017] = { id = 11017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netherstaubpollen", description = "Ein Blümchenpflücker?! Köstlich... bedauerlicherweise benötigen unsere Magier und Schamanen Eure Dienste. Die Netherstaubbüsche, die hier auf der Scherbe wachsen, besitzen spezielle Pollen, die bei magischen Angelegenheiten wohl recht nützlich sind. Bringt mir das Zeug, dann habt Ihr Euren Arbeitsauftrag für heute erledigt.", sourceObjective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 40 Netherstaubpollen bringt.", progress = "Wie ich schon sagte, Netherstaubpollen werden von unseren Zauberern verwendet.", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11018] = { id = 11018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netheriterz", description = "Ein Minenarbeiter!\n\n<Varkule nickt Euch zu.>\n\nEin Orc ganz nach meinem Geschmack! So hat Varkule auch einmal angefangen - mit Bergbau! Es gibt doch nichts Besseres als runter in die Mine zu gehen und richtig schmutzig zu werden, nicht wahr?\n\nGeht jetzt und sucht nach Netheritablagerungen. Holt alles, was wertvoll ist, heraus und bringt mir das Erz.", sourceObjective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 40 Einheiten Netheriterz bringt.", progress = "Gug dort drüben verwendet das Erz zum Verstärken unserer Waffen und Rüstungen.", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11019] = { id = 11019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund unter Feinden", sourceObjective = "Ihr habt doch nicht etwa geglaubt, dass wir Euch den Armeen der Höllenorcs ganz alleine überlassen würden, oder?\n\n<Yarzills Augen flackern in einem durchscheinenden Blau.>\n\nGenau, wir sind hier an Eurer Seite, {name}. Bei jedem Dienst, den Ihr den Höllenorcs bei Eurem Versuch, die Weiten der Netherschwingen zurückzuerobern, erweist, werden wir dafür sorgen, dass sie einen ausreichenden Rückschlag erleiden.\n\nIhr müsst Euch sehr unauffällig verhalten, um keinerlei Aufmerksamkeit während Euren Sabotageeinsätzen auf Euch zu ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11020] = { id = 11020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein langsamer Tod", description = "Die Anhänger des Drachenmals haben bei fast allen Kristallformationen hier oben Peons stationiert. Ein bloßes Töten, würde Euch bei weitem zu viel unerwünschte Aufmerksamkeit einbringen. Wir können ihre Reihen aber auch auf eine andere Art und Weise lichten, ohne bei dem misstrauischen Mor'ghor Verdacht zu erwecken.\n\nReist in die Wildnis des Schattenmondtals und tötet die besudelten Tiere. Nehmt ihre verderbten Teufelsdrüsen an Euch. Wendet die Teufelsdrüsen in der Nähe der Peons auf den Hammel an, den ich Euch geben werde. Ein Biss und sie sind tot!", sourceObjective = "Yarzill der Söldner beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr Yarzills Hammel zusammen mit den Teufelsdrüsen verwendet, um 12 Peonlager des Drachenmals zu vergiften.", progress = "Es ist eine schmutzige Arbeit, {name}.", completion = "<Yarzill flüstert ganz leise.>\n\nAusgezeichnete Arbeit, {name}. Verhaltet Euch fürs Erste ruhig. Kommt morgen wieder zu mir, dann können wir das Ganze noch einmal machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11021] = { id = 11021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ishaals Almanach", description = "Dieser geheimnisvolle Foliant lag bei Krallenpriester Ishaals Leichnam. Die darin abgebildeten arkanen Symbole und Schaubilder von Himmelskörpern sind Euch völlig fremd.\n\nSämtliche Aufzeichnungen wurden in einer für Euch unverständlichen Sprache verfasst; vermutlich eine uralte Form der Arakkoaschriftsprache. Vielleicht solltet Ihr damit zu Himmelskommandant Adaris gehen.", sourceObjective = "Bringt Ishaals Almanach zu Himmelskommandant Adaris im Norden von Skettis.", progress = "Ihr wollt mir etwas zeigen?", completion = "Was habt Ihr mir da gebracht? Die Sprache dieses Folianten ist mir fremd, {name}... mein Blutverlust... muss meinen Geist verschleiert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11022] = { id = 11022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Mog'dorg", description = "<König/Königin> {name}! Bevor Ihr uns verlasst und nach Ogri'la geht, sprecht mit Mog'dorg dem Weisen!", sourceObjective = "Sprecht mit Mog'dorg dem Weisen. Er steht oben auf dem Turm auf der Ostseite des Zirkels des Blutes im Schergrat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11023] = { id = 11023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und wieder ein Bombenangriff!", description = "Diese Flakgeschütze bereiten uns noch immer Sorgen, {name}.\n\nVersteht mich bitte nicht falsch - Ihr habt das letzte Mal hervorragende Arbeit geleistet, aber das ändert leider nichts an der Tatsache, dass diese verdammten Dämonen ihre Munitionsvorräte schneller wieder aufzufüllen vermögen, als wir sie vernichten können. Unsere Männer da hineinzuschleusen ist momentan also ein mehr als riskantes Unterfangen, ganz zu schweigen von dem Risiko, das die Dämonen für Ogri'la darstellen.\n\nWas sagt Ihr? Wollt Ihr es noch einmal versuchen?", sourceObjective = "Vernichtet mithilfe der Bomben der Himmelswache 15 Stapel mit Teufelskanonenkugeln.", progress = "Wie steht es mit dem Bombenangriff?", completion = "Hervorragend, {name}! Ich würde Euch ja sofort wieder in die Luft schicken und ein paar Bomben werfen lassen, aber unsere Richtlinien hier schreiben vor, dass unsere Piloten ausreichend Ruhe und Erholung erhalten müssen. Es tut mir leid, ich mache die Regeln nicht, aber lasst Euch versichern, dass ich sie durchsetzen werde!\n\nSehen wir uns morgen wieder, Sportskanone?", sourceObjectiveStatus = "unverified-source-field" }
quests[11024] = { id = 11024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Verbündeter im Unteren Viertel", description = "Im Unteren Viertel gibt es einen Arakkoa namens Rilak... ihm kann Vertrauen geschenkt werden. Nehmt das Buch... und bringt es zu ihm.\n\n<Adaris gibt Euch das Buch wieder und verliert daraufhin das Bewusstsein.>", sourceObjective = "Bringt Ishaals Almanach zu Rilak dem Erlösten im Unteren Viertel in Shattrath.", progress = "Ihr seid mit dem Geruch Skettis' behaftet! Was hat das zu bedeuten?", completion = "Das kann nicht sein... dies war einst Eigentum eines Krallenpriesters. Wie ist es nur in Eure Hände gelangt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11025] = { id = 11025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kristalle", description = "Beim richtigen Umgang mit den Kristallen der Berge, weisen diese seltsame Kräfte auf, wie zum Beispiel die Klarheit des Geistes, die wir hier in Ogri'la entdeckt haben.\n\nAlle Kreaturen oben auf den Bergen begehren danach und benutzen die Splitter, um ihre eigenen Ziele voranzutreiben. Der Wert dieser Kristalle hat sogar eine regelrechte Wirtschaft aufkommen lassen.\n\nUm uns helfen zu können, müsst Ihr zunächst etwas über die Apexissplitter lernen. Bringt mir ein paar Exemplare. Nicht nur die Kreaturen hier besitzen welche, gelegentlich findet man sie auch bei den großen Kristallen, dort, wo die Hetzer graben.", sourceObjective = "Chu'a'lor möchte, dass Ihr 5 Apexissplitter einsammelt. Bringt sie zu ihm in Ogri'la hoch oben im Schergrat.", progress = "Wenn Ihr mehr über die Splitter und Kristalle lernt, werdet Ihr uns und unsere Ogerbrüder dort unten besser beschützen können.\n\nDie Splitter selbst wurden nach einer uralten und mittlerweile ausgelöschten Arakkoazivilisation benannt, die einst auf den Spitzen dieser Berge lebte.\n\nNun, habt Ihr die Splitter bei Euch?", completion = "<Chu'a'lors linker Kopf beginnt zu sprechen.>\n\nDiese sind genau richtig.\n\nDenkt daran, {name}, der Wert dieser Splitter liegt nicht in ihrem Verkaufspreis. Es ist nicht einmal das, was sie für Euch tun können, sobald sie ordnungsgemäß zusammengeschmiedet wurden... auch wenn sich darüber streiten lässt.\n\n\n\nDer wahre Wert liegt in dem Unterfangen, das es auf sich zu nehmen gilt, um in den Besitz dieser Splitter zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11026] = { id = 11026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bannt die Dämonen", description = "Ihr seid genau zur rechten Zeit hier eingetroffen! Wir brauchen dringend Unterstützung. Als Gegenleistung werden wir Euch etwas sehr seltenes und von beiderseitigem Wert für Euch und für uns überlassen.\n\nWir sind keine gewalttätigen Oger mehr, aber die nahegelegenen Dämonen drohen uns und die Himmelswache zu überrennen. Das Problem mit Dämonen ist, hat man sie erst einmal getötet, tauchen sie wenig später in einem neuen Körper wieder auf!\n\nWenn Ihr allerdings mit diesem Kristall ein Bannportal beschwört und ein Dämon in dessen Nähe stirbt, wird seine Essenz in das Portal gezogen und er in seine Heimatebene verbannt!", sourceObjective = "Setzt den Bannkristall ein, um 15 Dämonen beim Konstruktionslager: Wut oder Konstruktionslager: Terror zu bannen.", progress = "Wir nehmen an, Ihr habt den Bannkristall dazu benutzt, eine ganze Reihe dieser Dinger der Brennenden Legion zum Packen zu bewegen?", completion = "Das wird ihnen eine Lehre gewesen sein! Kommen wir nun zu Eurer Belohnung.\n\nDie Dämonen des Konstruktionslagers: Wut im Norden haben an ihrer südlichen Grenze einen besonderen Transporter errichtet. Sie verwenden dieses experimentelle Transporttor, um den Einfluss des Lagers weiter auszudehnen. Wir brauchen Euch wohl nicht erst erklären, was passieren wird, wenn sie sich zu weit ausbreiten.\n\nAlso, wenn wir Ihr wären, würden wir diese Rune der Dunkelheit zu Gahk schaffen und ihn Fragen, wie Ihr helfen könnt. Geht es langsam mit ihm an, {name}, er ist ebenfalls neu hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[11027] = { id = 11027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Habt Ihr die Rune der Dunkelheit?" }
quests[11028] = { id = 11028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Countdown des Schicksals", description = "Dieser Almanach prophezeit die Rückkehr von Terokk, dem mächtigsten und furchtbarsten Skettiskönig der Arakkoageschichte.\n\nIch habe dies immer für eine Legende gehalten, {name}. Die Wiederkehr der Krallenpriester und Eure Entdeckung dieses Folianten belehren mich jedoch eines Besseren.\n\nMit jedem Tag wächst die Macht Terokks und seine Ankunft naht. Die einzige Chance, die Ihr habt, ist ihn vorzeitig in unsere Welt zu holen. Geht zurück nach Skettis und sprecht mit Adaris über das Ganze. Lasst uns hoffen, dass er die Weisheit besitzt, um die richtige Entscheidung zu treffen.", sourceObjective = "Kehrt zu Himmelskommandant Adaris ins Schattenwindlager in den Wäldern von Terokkar zurück und erzählt ihm die Neuigkeiten über Terokks Rückkehr.", completion = "Die Arakkoa möchten Terokk zurück aus dem Jenseits der Zeit holen und Rilak... möchte einen Weg finden, um diesen Vorgang zu beschleunigen? Hat er denn seinen Verstand verloren?\n\n<Adaris legt sich geschwächt nieder.>\n\nIhr habt Eure Pflicht erfüllt, {name}. Es ist an der Zeit, dass Ihr die Sache meinen Männern überlasst. Das ist jetzt eine rein militärische Angelegenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11029] = { id = 11029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schäbige Verkleidung", description = "Öffnet das Päckchen, {name}. Es ist eine Verkleidung. Sie sieht nicht sehr überzeugend aus, oder?\n\nIch fertige sie für astrale Schmuggler an, auf der Suche nach seltenen Büchern. Es gibt einen Schreiber der Arakkoa, der auf der zentral gelegenen Insel in Skettis lebt, die als Terokks Ruh bekannt ist; sein Name ist Sahakk. Er ist alt und fast blind.\n\nVerwendet die Verkleidung, um mit ihm zu sprechen und besorgt Euch das Buch, den Stammbaum der Feinde. Seid auf der Hut, {name}. Andere Arakkoa lassen sich von der Verkleidung nicht täuschen.", sourceObjective = "Verwendet die schäbige Arakkoaverkleidung, um den Stammbaum der Feinde von Sahaak zu beschaffen. Kehrt anschließend zu Hazzik zurück.", progress = "Das Buch, {name}. Habt Ihr es?", completion = "Ausgezeichnet! Das Buch beinhaltet eine Aufstellung der Nachfahren von Terokks alten Feinden. Es wurde vorhergesagt, dass ihr Tod Terokks Rückkehr ankündigen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11030] = { id = 11030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Junge möchte der Himmelswache beitreten", description = "Wir haben ein kleines Problem, {class}: Wir haben eine Menge Söhne. Seit die Himmelswache bei uns in der Nähe stationiert wurde, wünschen sie sich nichts sehnlicher, als der Wache beizutreten.\n\nAls stolzer Vater möchten wir natürlich, dass sie zum Zeitpunkt ihrer Bewerbung alle Vorteile haben, die sie kriegen können. Würdet Ihr also für uns die Teufelskristallschmiede in einem der beiden Lager im Norden oder im Süden aufsuchen und ein magisches Fläschchen für unsere Söhne beschaffen? Ihr könnt ihren grünen Rauch kaum verfehlen.\n\nWir denken, die Herstellung eines Fläschchens erfordert zehn Apexissplitter. Gerne würden wir Euch Splitter mitgeben, aber leider haben wir keine mehr zur Hand.", sourceObjective = "Beschafft ein instabiles Fläschchen der Bestie.", progress = "Habt Ihr das magische Fläschchen schon bekommen? Es würde Torkus Junior alles bedeuten.", completion = "Ihr seid ein Lebensretter, {name}!\n\nUnsere Jungs werden von dieser Neuigkeit begeistert sein!\n\nOk, eines geschafft und eines fehlt noch. Wir haben Euch doch bestimmt von dem anderen Fläschchen erzählt, das sie benötigen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[11031] = { id = 11031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Erzmagier", progress = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", completion = "Trefft Eure nächste Entscheidung mit Bedacht. Wir versuchen unseren Verbündeten so gut wie möglich entgegen zu kommen, aber auch Dalarans Ressourcen sind nicht grenzenlos." }
quests[11032] = { id = 11032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Beschützer", progress = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", completion = "Trefft Eure nächste Entscheidung mit Bedacht. Wir versuchen unseren Verbündeten so gut wie möglich entgegen zu kommen, aber auch Dalarans Ressourcen sind nicht grenzenlos." }
quests[11033] = { id = 11033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Assassine" }
quests[11034] = { id = 11034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Bewahrer", progress = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", completion = "Trefft Eure nächste Entscheidung mit Bedacht. Wir versuchen unseren Verbündeten so gut wie möglich entgegen zu kommen, aber auch Dalarans Ressourcen sind nicht grenzenlos." }
quests[11035] = { id = 11035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schatten am Horizont", description = "Am nordöstlichen Ende dieser Insel gibt es ein Dock, das dem Verpacken und dem Transport der Kristalle und Relikte der Netherschwingen dient. Transporter des Drachenmals transportieren die Güter vom Dock zu der Festung des Drachenmals, während die Ahnen des Drachenmals den Boden vor möglichen Angreifern schützen.\n\nUm dem Drachenmal einen Schlag zu versetzen, bleibt nur ein Angriffspunkt offen: der Himmelspfad des Drachenmals.\n\nFliegt zu den zerschlagenen Inseln des Himmelspfads des Drachenmals und lauert den Transportern auf, die diesen Weg einschlagen. Bringt unsere gestohlenen Relikte wieder in Sicherheit!", sourceObjective = "Yarzill der Söldner beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr 10 Relikte der Netherschwingen sicherstellt.", progress = "Tote Orcs singen nicht, {name}. Stellt sicher, dass keiner der Transporter des Drachenmals entkommt.", completion = "<Yarzill flüstert.>\n\nIhr habt den Netherschwingen einen großen Dienst erwiesen, {name}. Der Fall des Drachenmals rückt in greifbare Nähe. Von innen heraus breitet sich nun eine Krankheit aus - eine unheilbare Krankheit...\n\nSolltet Ihr wieder an Arbeit bei dem Himmelspfads des Drachenmals interessiert sein, so kommt morgen wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11036] = { id = 11036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außerirdische Früchte!", description = "Ich muss ganz ehrlich zugeben, dass ich nicht die leiseste Ahnung habe, wozu diese Lieferung dienen soll, aber Raketenchef Doppeldeckers Anweisungen waren sehr genau - nur die besten Früchte, konserviert, um eine lange Reise zu überstehen und gut versiegelt sollen sie sein.\n\nEs gab noch weitere Anweisungen, irgendetwas über Schwerelosigkeit hier und Niedrigdruck da. Ich gebe nicht mal vor, alles zu verstehen, aber der Preis stimmt, also kriegt er seine Supernahrung. Bringt diese Kiste zu ihm in der Area 52. Nachdem Ihr den Nethersturm betreten habt, folgt der Straße, bis Ihr die Stadt seht.", sourceObjective = "Bringt die konservierten Früchte zu Raketenchef Doppeldecker in Area 52 im Nethersturm.", progress = "Ist das die Lieferung vom alten Orok?", completion = "<Der Raketenchef überprüft den Inhalt der Kiste.>\n\nSieht soweit gut aus. Wieder etwas, dass ich von der Liste streichen kann. Nun müssen wir noch nur dafür sorgen, dass die Rakete vom Boden abhebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11037] = { id = 11037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltsame Vision", description = "{name}, ich hatte eine höchst ungewöhnliche Vision, auf die ich mir keinen Reim machen kann. Ich sah einen Pfeil, einen gigantischen Pfeil, der sich auf einem Feuerschweif gen Himmel erhob. Für einen geübten Magier wäre es ein Leichtes etwas derartiges zu erschaffen, doch ein Gefühl sagt mir, dass dieses Objekt nicht das Produkt von Magie ist.\n\nEs wird anders sein, als alles, was die Völker von Azeroth je erschaffen haben. Ihr müsst diejenigen finden, die an diesem Wunderwerk arbeiten, {name}. Gewährt ihnen Eure Hilfe, denn ohne sie werden sie versagen.", sourceObjective = "Sprecht mit Raketenchef Doppeldecker in Area 52.", completion = "<Der Raketenchef hört Euch aufmerksam zu, als Ihr ihm von der Vision des Sehers erzählt.>\n\nNun, das ist alles völlig neu für mich, aber Eure Hilfe können wir allemal gebrauchen. Seht Euch die Rakete hinter mir an! Das ist die X-52...\n\nIst sie nicht das Schönste, was Ihr je gesehen habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11038] = { id = 11038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung für Exarch Orelis", description = "Vor nicht allzu langer Zeit entsandte Hohepriesterin Ishanah eine kleine Gruppe von Anachoreten unter dem Kommando von Exarch Orelis in den Nethersturm. Sie hatten den Auftrag, die Aktivitäten von Kael'thas und seinen Gefolgsleuten zu untersuchen, doch bisher haben wir keinerlei Nachricht von ihnen erhalten.\n\nIch habe die Befürchtung, dass unsere Präsenz im Zielgebiet nicht stark genug ist, um diesen Auftrag erfolgreich abzuschließen. Sicherlich würde der Exarch von Eurem Wissen und Eurer Erfahrung profitieren. Wäret Ihr bereit zur Area 52 zu reisen und ihn zu unterstützen?", sourceObjective = "Sprecht mit Exarch Orelis in Area 52.", completion = "So, Ihr seid also hierher gekommen, um unsere Untersuchungen über Kael'thas Pläne zu unterstützen? Eure Hilfe ist uns sehr willkommen. Der Nethersturm ist voll von Agenten der Blutelfen, die nichts unversucht lassen, um das Land ins Chaos zu stürzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11039] = { id = 11039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Spionagemeister Thalodien", description = "Vor einiger Zeit schickte Voren'thal eine kleine Einheit in den Nethersturm, um Kael'thas' Aktivitäten genauer zu beobachten. Unser Anführer hat vollstes Vertrauen in die Fähigkeiten von Spionagemeister Thalodien und seinen Männern und hat sich daher entschlossen, seiner Bitte um Verstärkung nachzukommen.\n\nThalodiens Bericht fiel recht knapp aus, doch geht daraus eindeutig hervor, dass er eine Entdeckung von größter Wichtigkeit gemacht hat. Erstattet ihm in der Area 52 Meldung und unterstützt ihn soweit es Euch möglich ist, {name}.", sourceObjective = "Meldet Euch bei Spionagemeister Thalodien in Area 52.", completion = "<Einen Augenblick lang huscht ein Ausdruck der Enttäuschung über das Gesicht des Spionagemeisters.>\n\nIch hatte wenigstens auf eine ganze Einsatzgruppe gehofft, aber wenn Voren'thal es für sinnvoll hielt, Euch alleine zu entsenden, werde ich meine Pläne entsprechend anpassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11040] = { id = 11040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzteile für den Raketenchef", description = "Wie oft ich mit einem Goblin zusammengearbeitet habe, kann ich an einer Hand abzählen. Normalerweise konkurrieren wir mit ihnen, aber als ich Raketenchef Doppeldeckers Anfrage erhielt, konnte ich sie nicht einfach so ablehnen.\n\nDiese Kiste ist voller Einzelteile für die ich hier keine Verwendung habe, aber die für das Projekt des Raketenchefs sehr nützlich sein könnten. Wäret Ihr so freundlich und würdet Sie bei ihm abgeben, wenn Ihr an der Area 52 vorbeikommt?\n\nWer weiß, vielleicht schaffen es einige gnomische Teile, seine Erfindung vor der Zerstörung zu bewahren!", sourceObjective = "Bringt Bossis Ersatzteile zu Raketenchef Doppeldecker nach Area 52 im Nethersturm.", progress = "Diese Kiste sieht aus, als stamme sie von einem Goblinmeisteringenieur. Hat Bossi Euch geschickt?", completion = "Ich weiß nicht einmal, was einige dieser Teile bewirken! Einige von ihnen werden mir sicherlich sehr nutzen. Ich hätte niemals gedacht, dass ich mal lernen müsste, wie ein Gnom zu denken!", sourceObjectiveStatus = "unverified-source-field" }
quests[11041] = { id = 11041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unerledigte Aufgabe...", description = "Im Namen unseres großen Meisters... zum Ruhme Illidans!\n\nIm Auftrag von Oberanführer Mor'ghor soll das große Plateau der Netherschwingenscherbe gesichert werden. Da fast alle Drachen der Netherschwingen eingefangen oder vom Land vertrieben wurden, nehmen die Felsklauen langsam überhand und bedrohen unsere Kristallernte.\n\nVernichtet sie alle, ihre Höhlenmutter und ihren Gefährten, Arvoar.\n\nMor'ghor befiehlt es so!\n\n<Es scheint ganz so, als hätte der Orc beim Absichern des Plateaus versagt. Es ist an der Zeit, dass Ihr Euch bei Mor'ghor als würdig erweist!>", sourceObjective = "Tötet 10 Felslandschinder und Barash die Höhlenmutter. Kehrt nach erfolgreicher Erledigung zu Oberanführer Mor'ghor beim Basislager des Drachenmals zurück.", progress = "Wer wagt es, an Mor'ghor heranzutreten? Ich hoffe für Euch, dass es von Wichtigkeit ist.", completion = "Ihr habt also bei den Überresten einer meiner Aufseher eine Anordnung gefunden und die Sache selbst in die Hand genommen? Ihr habt es geschafft, Mor'ghor zu beeindrucken. Gut gemacht...", sourceObjectiveStatus = "unverified-source-field" }
quests[11042] = { id = 11042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verblüffende Vision", description = "Mich verfolgt eine seltsame Vision, {name}. Ich sehe eine riesige Rauchwolke, die gen Himmel steigt, und ein gigantisches Feuer, welches sich noch weit höher erhebt. Es ist weder ein natürliches Phänomen, noch ein Werkzeug des Bösen; so viel ist sicher.\n\nIch habe keine Vorstellung davon, wie es aussieht, ich weiß nur, dass es das Werk Vieler ist. Dennoch, ohne weitere helfende Hände, wird diese Vision wohl nie Realität werden.\n\nReist in den Nethersturm, {class}. Findet die Erschaffer dieser Erscheinung und bietet ihnen Eure Hilfe an.", sourceObjective = "Sprecht mit Raketenchef Doppeldecker in Area 52.", completion = "<Der Raketenchef hört Euren Ausführungen über die Vision des Sehers aufmerksam zu.>\n\nNun, das ist alles völlig neu für mich, aber Eure Hilfe können wir allemal gebrauchen. Seht Euch das Ungetüm hinter mir an. Das ist die X-52...\n\nIst sie nicht das Schönste, was Ihr je gesehen habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11043] = { id = 11043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besserer Greif", description = "Wie ich hörte, unterhalten die Wildhammerzwerge in ihrer Festung im südlichen Schattenmondtal einen Greifenhorst. Könntet Ihr, wenn Ihr Euch dorthin begebt, in meinem Namen mit ihnen sprechen? Ich habe da einige Ideen, wie man ihre Greifen noch verbessern könnte!\n\nWarum sie nur mit einer Rüstung ausstatten, wenn man sie noch mit einem Höhenmesser, einem Rückspiegel und einer Rakete bestücken kann? Stellt Euch nur vor, welche Geschwindigkeiten ein Greif mit einer, auf seinem Rücken festgeschnallten, Rakete erreichen würde! Ich nenne meine Erfindung den Turbogreifen 8000!", sourceObjective = "Sprecht mit Brunn Flammenbart in der Wildhammerfeste im Schattenmondtal.", completion = "<Brunns Gesicht errötet, bis es nicht länger von seinem Bart zu unterscheiden ist.>\n\nEr möchte WAS mit meinen Greifen anstellen?\n\nWenn diese kleine Ratte auch nur versucht, irgendetwas anderes als einen Sattel auf meinen Greifen zu befestigen, reise ich persönlich zum Schergrat und stopfe ihm mit seinen Raketen das Maul!", sourceObjectiveStatus = "unverified-source-field" }
quests[11044] = { id = 11044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen voller Zerstörung", description = "Eine Vision voller Zerstörung reißt mich oft aus dem Schlaf. - Ein Regen aus grünem Feuer, der auf die Erde herabregnet und die tapferen Verteidiger einer mächtigen Festung verbrennt. Seit Wochen schon verfolgt mich dieser Traum, doch erst kürzlich ist mir seine Bedeutung offenbart worden.\n\nWeit im Osten, im Schattenmondtal, erwehren sich die Wildhammerzwerge den ständigen Angriffen der Brennenden Legion und zahlloser anderer Feinde. Sie kämpfen tapfer, doch wenn sie nicht bald Entsatz erhalten, werden ihre Feinde triumphieren. {name}, Ihr müsst ihnen zur Seite stehen. Helft ihnen in ihrem verzweifelten Kampf.", sourceObjective = "Sprecht mit Schwadronskommandant Nuainn in der Wildhammerfeste.", completion = "Eine Vision sagt Ihr? Es interessiert mich nicht, ob er es in einer Vision gesehen, in einem Brief gelesen oder es aus dem Mund eines Grubenlords vernommen hat, aber er hat den Nagel auf den Kopf getroffen! Was führt Euch hierher, Freund? Oh, und wir sind für jede Unterstützung dankbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[11045] = { id = 11045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorus der Richter", description = "Die Geschichte des Schattenmondtals reicht lange zurück und ist von Tragödien durchzogen. Aus Furcht davor, alte Schrecken zu neuem Leben zu erwecken, wagen es nur wenige, sich näher mit ihr zu beschäftigen.\n\nDoch nicht alle sind so furchtsam. Zorus der Richter versucht die Schleier der Vergangenheit des Schattenmondtals zu lüften. Dies ist eine große Herausforderung und ich bin sicher, dass ihm jede Hilfe willkommen ist.\n\nSolltet Ihr ins Tal reisen, haltet Ausschau nach Zorus bei der Wildhammerfeste, sie liegt zentral im Süden des Tals.", sourceObjective = "Sprecht mit Zorus dem Richter in der Wildhammerfeste.", completion = "Fantei spricht die Wahrheit, Eure Hilfe kommt mir sehr gelegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11046] = { id = 11046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chefapothekerin Hildagard", description = "Die Geschichte des Schattenmondtals reicht lange zurück und ist von Tragödien durchzogen. Aus Furcht davor, alte Schrecken zu neuem Leben zu erwecken, wagen es nur wenige, sich näher mit ihr zu beschäftigen.\n\nDoch nicht alle sind so furchtsam. Chefapothekerin Hildagard versucht die Schleier der Vergangenheit des Schattenmondtals zu lüften. Dies ist eine große Herausforderung und ich bin sicher, dass ihr jede Hilfe willkommen ist.\n\nFalls Ihr Euch jemals dorthin begebt, sucht Hildagard beim Dorf Schattenmond auf, es liegt im nordwestlichen Teil des Tals.", sourceObjective = "Sprecht mit Chefapothekerin Hildagard in Schattenmond.", completion = "Fantei hat ein gutes Gedächtnis. Es ist schon Monate her, dass ich in Shattrath war, um Zutaten zu kaufen. Allerdings hat er Recht. Ich könnte etwas Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11047] = { id = 11047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bitte des Gesellen", description = "Als ein Windreitermeisterlehrling gehört es zu meinen Aufgaben, die Tiere zu versorgen, wenn sie nicht gerade fliegen. Das Problem ist, dass die Windreiter sich kaum erholen können, da wir über so wenige von ihnen verfügen.\n\nIch fürchte, dass wenn wir nicht bald Ersatz erhalten, sie sich alle zu Tode fliegen werden. Im westlichen Schattenmondtal, im Dorf Schattenmond, gibt es einen großen Stall. Dama Wildmähne überwacht dort die Ausbildung und Versorgung der dortigen Windreiter.\n\nWürdet Ihr in meinem Namen mit ihr sprechen und ihr von unserer Situation berichten?", sourceObjective = "Sprecht mit Dama Wildmähne im Dorf Schattenmond im Schattenmondtal.", completion = "<Dama hört sich Agadais Bitte an.>\n\nIch kann nicht dafür garantieren, dass wir über genügend Windreiter verfügen, aber ich werde sehen, was ich tun kann. In der momentanen Situation haben wir Schwierigkeiten, die Nachfrage der verschiedenen Käufer und Außenposten abzudecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[11048] = { id = 11048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kroghans Bericht", description = "Meine ursprünglichen Befehle sahen vor, dass ich für kurze Zeit in Garadar bleibe und ich mich anschließend bei Blutwache Gulmok im Dorf Schattenmond melden sollte. In meiner Zeit hier ist mir klar geworden, dass Garadar von einer langfristigen Zusammenarbeit mit der Horde profitieren würde.\n\nIch weiß, dass Blutwache Gulmok alle verfügbaren Truppen braucht, aber er wird auch einsehen müssen, dass meine Mission hier noch nicht zu Ende ist. Reist nach Schattenmond, im nordwestlichen Teil des Schattenmondtals, und informiert Blutwache Gulmok über meine verspätete Ankunft.", sourceObjective = "Sprecht mit Blutwache Gulmok im Dorf Schattenmond.", completion = "<Gulmok beginnt zu murren, als er von Kroghans Entscheidung hört.>\n\nIch verstehe durchaus seinen Standpunkt, doch unsere Schützengräben besetzen sich nicht von selbst! Die Legion bombardiert uns Tag und Nacht mit Höllenbestien. Wenn Kroghan sich verspätet, könnt Ihr ja seinen Platz auf dem Schlachtfeld einnehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11049] = { id = 11049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Eierjagd", description = "Solltet Ihr bei Euren Erkundungen auf Eier der Netherschwingen stoßen, bringt sie zu mir.\n\nEines ist sicher, ein Ei der Netherschwingen ist ein seltener Fund. Lasst den Kopf nicht hängen, falls Ihr keine Eier finden könnt. Die Anhänger des Drachenmals waren beim Einsammeln recht gründlich. Sie haben fast alle aufgespürt und an unbekannte Stellen versendet.\n\nMan findet die Eier im Besitz von Kreaturen der Insel, in der Nähe von Kristallformationen, in den Minen oder auch in Netheritansammlungen oder Netherstaubbüschen.\n\nHaltet Euch bedeckt. Mor'ghor soll wenn möglich nichts von Eurem Unterfangen erfahren.", sourceObjective = "Yarzill der Söldner beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ein Ei der Netherschwingen einsammelt.", progress = "Was macht die Eierjagd?", completion = "Neltharaku wird höchst erfreut sein, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11050] = { id = 11050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer her mit den Eiern", progress = "Diese Eier dürfen auf keinen Fall in die falschen Hände geraten, {name}. Wenn Ihr noch mehr Eier findet, bringt sie mir.\n\nVerhaltet Euch auf jeden Fall unauffällig und erregt bloß keinen Verdacht!", completion = "Ihr seid ein wahrer Held, {name}." }
quests[11051] = { id = 11051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bannt mehr Dämonen", description = "Wenn wir die Dämonen richtig einschätzen, was sehr wahrscheinlich ist, da wir sie ausgiebig studiert haben, werden sie versuchen, den Schaden an ihrem kostbaren Transporter so schnell wie möglich zu reparieren.\n\nAlso, wenn Ihr Eure Chance auf eine weitere Rune der Dunkelheit wahrnehmen möchtet, nehmt den Bannkristall und erledigt dort draußen noch mehr Dämonen für uns. Schließlich wollt Ihr uns doch dabei helfen, die Bedrohung durch die Dämonen in den Griff zu kriegen, nicht wahr?\n\nWir sagten Chance, weil der von uns angewandte Herstellungsprozess nicht immer einwandfrei funktioniert. Manchmal kommt eine Rune der Dunkelheit dabei heraus, dann wieder etwas völlig anderes.", sourceObjective = "Setzt den Bannkristall ein, um 15 Dämonen beim Konstruktionslager: Wut oder Konstruktionslager: Terror zu bannen.", progress = "Jemand mit Eurer Erfahrung dürfte keine Probleme damit haben, ein paar Dämonen zu bannen. Ihr habt doch keine Schwierigkeiten damit, oder {race}?", completion = "Wir wünschten uns, der Herstellungsprozess für Runen der Dunkelheit wäre narrensicher, {name}. Unglücklicherweise ist er das nicht. Nehmt bitte diesen Sack und seht mal, was wir heute hergestellt haben. Wir haben es nicht übers Herz gebracht, selbst nachzusehen.\n\nWenn Ihr eine Rune der Dunkelheit erhaltet, vergesst nicht, Gahk aufzusuchen und sie bei ihm gegen eine kristallgeschmiedete Rune der Dunkelheit einzutauschen. Mit ihr könntet Ihr Shartuuls Transporter erneut ausschalten.\n\nOh, und {name}, denkt daran, morgen wiederzukommen und den Bannkristall abzuholen. Es sind genug Dämonen da, die gebannt werden möchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11052] = { id = 11052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akamas Versprechen", description = "<Akama setzt den Kristall in das Medaillon in seiner Hand ein.>\n\nIch bin nicht mehr so stark wie einst, {name}. All die Jahre, die ich so nahe am Bösen verbracht habe... Ich weiß nicht, ob ich mir selbst mit einem so mächtigen Artefakt wie diesem trauen würde.\n\nNehmt dies als mein Versprechen, dass ich auf Eurer Seite sein werde, wenn Ihr Euch Illidan stellt. Bringt es zu dem Wesen, dem wir seine Macht anvertrauen können. Bringt das Medaillon zu A'dal in Shattrath.", sourceObjective = "Bringt das Medaillon von Karabor zu A'dal in Shattrath.", progress = "<A'dal bemerkt Euch und umarmt Euch mit einem warmen Licht. Er scheint zu wissen, dass Ihr etwas für ihn habt.>", completion = "<Als Ihr A'dal das Medaillon übergebt, verschwindet es mit einem Lichtblitz in seinem Geist.>\n\n<Für einen kurzen Moment erscheint eine Szene vor Euch... vielleicht aus der Zukunft. Ihr seht, wie Akama und Maiev aus dem Kerker des Wächters heraustreten und sich zum Schwarzen Tempel durchschlagen. Eine dritte, in Schatten gehüllte Gestallt hilft ihnen dabei. Als Ihr genauer hinschaut, erkennt Ihr, dass Ihr diese Gestalt seid.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11053] = { id = 11053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Aufseher!", description = "Es ist selten, dass ein Peon so lange überlebt wie Ihr. Es ist allerdings noch seltener, dass sich ein Peon vom Abschaum abhebt und in einen neuen Rang aufsteigt.\n\n<Varkule klatscht.>\n\nDer Oberanführer hat nach Euch verlangt, Grunzer. Sicherlich erwartet Euch ein neuer Rang.", sourceObjective = "Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal.", completion = "Ich habe Eure Handlungen mit einem wachsamen Auge verfolgt, {name}. Ihr habt bewiesen, dass Ihr ein unschätzbarer Gewinn für das Drachenmal seid. Daher werde ich Euch zum Aufseher befördern. Ein neuer Rang bedeutet natürlich auch neue Verantwortungen, denen Ihr gerecht werden müsst.\n\nErhebt Euch, Aufseher {name}! Erhebt Euch und sucht diejenigen auf, die Eure Hilfe hier im Basislager brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11054] = { id = 11054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufsehen und Ihr: Die richtige Wahl treffen", description = "Ihr seid also der neue Aufseher, was? Tja, es gibt da eine Sache, die jeder gute Aufseher braucht: die richtige Ordnungswaffe. Bevor Ihr dort hinausgehen und diesen Peons etwas Verstand einprügeln könnt, braucht Ihr Eure \"Waffe\". Jeder Aufseher muss die Materialien zur Herstellung seiner eigenen \"Waffe\" sammeln und Ihr seid da keine Ausnahme.\n\nIch benötige Knotenhautleder und den gehärteten Balg von Tyrantus. Ihr findet Tyrantus in der Biokuppel Fernfeld, welche in der nördlichen Gegend des Nethersturms zu finden ist.", sourceObjective = "Chefvorarbeiter Lehmklump beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 10 Einheiten Knotenhautleder und 1 gehärteten Balg von Tyrantus bringt.", progress = "Es gilt Peons zur Ordnung zu rufen, {name}! Beeilt Euch!", completion = "Ahh! Vielleicht habt Ihr ja doch das Zeug zum Aufseher. Diese übergroße Echse war schon das Leid vieler Orcs!\n\n<Chefvorarbeiter Lehmklump beginnt mit der Herstellung der Waffe.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11055] = { id = 11055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schuhmerang: Das Mittel gegen den wertlosen Peon", description = "Dies hier ist Euer Schuhmerang. Es gibt viele andere, aber dieser ist Eurer.\n\nAls Aufseher werdet Ihr diesen Schuhmerang verwenden, um Furcht in die Herzen aufsässiger Peons zu pflanzen. Der richtige Einsatz des Schuhmerangs wird für Gehorsam und Unterwürfigkeit sorgen.\n\nGeht weit hinaus zu den Kristallfeldern und diszipliniert jeden Peon, den Ihr beim Faulenzen erwischt. Zeigt ihnen die Macht des Schuhmerangs!", sourceObjective = "Chefvorarbeiter Lehmklump beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr 20 faule Peons des Drachenmals zur Ordnung ruft. Gebt anschließend auch Euren Schuhmerang wieder zurück.", progress = "Der Trick liegt im Handgelenk, {name}.", completion = "Ein Tag harter Arbeit! Es zahlt sich aber aus, oder? Beim Anblick der schuftenden Taugenichtse bei den Kristallen wird einem richtig Warm um's Herz... Nun ja, das ist alles für heute. Kommt morgen wieder, dann könnt Ihr ein weiteres Mal den Schuhmerang schwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11056] = { id = 11056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hazziks Handel", description = "Erwähnt unsere Unterhaltung nicht. Adaris würde nichts davon gutheißen.\n\nIch gehöre der niedrigsten Kaste der Arakkoa an, {name}. Während Terokks Herrschaft hätte man mich den dunklen Mächten geopfert, die von den Krallenpriestern verehrt werden. Sollte was Ihr sagt, wahr sein und sollten die Krallenpriester wirklich Terokks Rückkehr herbeisehnen, dann müsst Ihr dies unbedingt verhindern - ganz egal, was Euer Anführer sagt!\n\nIch habe etwas für Euch, das Ihr sehr nützlich finden werdet. Bei meiner alten Behausung im Oberen Shil'akversteck liegt ein Päckchen. Bringt es mir.", sourceObjective = "Sucht nach Hazziks Päckchen bei seiner Behausung im östlichen Skettis und kehrt damit zu ihm zurück.", progress = "{name}, Ihr seid zurück! Ich dachte schon, Ihr hättet mich im Stich gelassen.", completion = "Ausgezeichnet, {name}. Ihr werdet sehen, dass ich mein Wort halte.", sourceObjectiveStatus = "unverified-source-field" }
quests[11057] = { id = 11057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwierigkeiten in der Tiefe", description = "Wir wissen Euren Eifer, uns hier in Ogri'la unterstützen zu wollen, sehr zu schätzen, {class}. Doch bevor wir Euer großzügiges Angebot annehmen können, müssen wir Euch zunächst um einen Gefallen bitten.\n\nUnsere Brüder dort unten sind Sklaven der Söhne von Gruul. Bitte, sprecht mit Mog'dorg dem Weisen. Er ist der Anführer einer Widerstandsbewegung der dort heimischen Oger gegen die Gronn.\n\nIhr findet ihn auf dem Turm, auf der östlichen Seite der Arena des Zirkels des Blutes.", sourceObjective = "Sprecht mit Mog'dorg dem Weisen. Ihr findet ihn auf einem der Türme außerhalb des Zirkels des Blutes im Schergrat.", completion = "Man hat Euch von hoch oben zu mir geschickt? Wahrlich, meine Mission ist gesegnet! Ich versuche die Blutschläger vor der Ausrottung durch den Speerspießerklan und Gruuls Söhne zu bewahren.\n\nIch nehme an, dass Ihr unsere geheime Organisation unterstützen und uns die Freiheit bringen werdet?", sourceObjectiveStatus = "unverified-source-field" }
quests[11058] = { id = 11058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Apexisrelikt", description = "Vor langer Zeit lebte hier eine Sekte der Arakkoa, die Apexis. Überreste ihrer seit langem ausgestorbenen Zivilisation sind auch heute noch allgegenwärtig. Wir nennen sie Apexisrelikte.\n\nDas Einzige, was wir mit Sicherheit wissen, ist, dass sie bei richtiger Benutzung einen Segen gewähren. Jedes Relikt repräsentiert eine farbige Sequenz, welche, wenn man die Kristalle in der richtigen Reihenfolge drückt, zu einer Serie von Stufen führen, eine schwieriger als die andere.\n\nEs wird ein Apexissplitter benötigt, um das Relikt zu aktivieren. Kehrt zurück, wenn Ihr mehr über die Apexisschwingungen erfahren habt.", sourceObjective = "Erlangt Apexisschwingungen von einem Apexisrelikt.", completion = "<Chu'a'lors Köpfe nicken Euch anerkennend zu.>\n\nIhr habt einen scharfen Verstand, {name}. Wir haben erheblich länger gebraucht, um das Relikt erfolgreich zu benutzen.\n\nNun, da Ihr wisst wie, könnt Ihr es so oft Ihr wollt verwenden. Denkt jedoch daran, dass für die Aktivierung eines Relikts immer ein Apexissplitter erforderlich ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11059] = { id = 11059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wächter des Monuments", description = "Ihr habt erfolgreich herausgefunden, wie man die Ein-Personen-Relikte benutzt. Aber wie Ihr wahrscheinlich schon bemerkt habt, umgeben die kleineren noch größere Relikte.\n\nDiese großen Apexismonumente funktionieren auf die exakt gleiche Weise, allerdings werden 35 Apexissplitter benötigt, um sie zu aktivieren.\n\nViel größere Sorgen bereiten uns die Wächter, die bei der Benutzung eines Relikts beschworen werden. Diese Kristallkonstrukte haben sich vor langer Zeit gegen ihre Arakkoameister gewendet und gefährden nun Ogri'la.\n\nWir möchten Euch bitten, einen von ihnen zu zerstören und uns einen Beweis Eurer Tat zu bringen.", sourceObjective = "Beschafft den Kopf eines Apexiswächters.", progress = "Wir verabscheuen Gewalt, aber wenigstens ist das Konstrukt, das Ihr vernichten sollt, kein lebendiges Wesen.\n\nWo wir schon davon sprechen, habt Ihr den Kopf?", completion = "<Chu'a'lor mustert Euch voller Respekt.>\n\nEure und die geistige Gewandtheit Eurer Freunde ist wahrlich beeindruckend. Dafür, dass Ihr uns und unsere Lebensweise verteidigt habt, stehen wir, nein, stehen ganz Ogri'la und die Himmelswache in Eurer Schuld.\n\nDenkt daran {name}, Ihr könnt jederzeit mit einer Gruppe zurückkehren, um die großen Apexismonumente zu benutzen. Bringt aber genügend Apexissplitter mit, um sie aktivieren zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11060] = { id = 11060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kristallgeschmiedete Rune der Dunkelheit", progress = "Die Dämonen machen das Konstruktionslager: Wut größer. Bald sie zu stark sind und uns vernichten werden. Ihr sie zuerst schlagen müsst!\n\nShartuuls Transporter sein Schlüssel zu Sieg, aber er werden beschützt von magischem Schild und mächtigen Dämon, einem Zerrütter. Wir mächtiger Hexenmeister und wir Euch herstellen werden eine besondere Rune der Dunkelheit, mit der Ihr Zerrütter kontrollieren könnt. {race} geben GahkRune der Dunkelheit, wir geben {race} kristallgeschmiedete Rune der Dunkelheit.\n\nIhr übernehmen den Zerrütter und übernehmen Herrschaft über so viele aus dem Portal kommende Dämonen wie möglich, um sie aufzuhalten!", completion = "Kleiner {race}, nicht vergessen, wenn Ihr einen Zerrütter kontrollieren, Ihr müssen seinen Hammer dazu benutzen, um die Schilde von Warptor zu zerschlagen und den gefangenen Dämonen freizulassen.\n\nDann Ihr müssen zerschlagen diesen Dämon und ihn beherrschen. Dann kommen neuer Dämon, den Ihr auch beherrschen müssen, bis der Aufseher der Eredar auftauchen.\n\nDann Ihr auch ihn erschlagen werdet!!!" }
quests[11061] = { id = 11061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflichten eines Vaters", description = "Was das andere magische Fläschchen angeht, man bekommt es ausschließlich an einem Ort: der Landeplatz von Bash'ir. Es handelt sich um einen Stützpunkt der Astralen und sie sind Fremden gegenüber nicht gerade freundlich eingestellt, daher könnte es etwas gefährlich werden.\n\nSicherlich fragt Ihr Euch jetzt, wo man diesen Landeplatz von Bash'ir findet? Steigt auf Euer fliegendes Reittier und reist in Richtung Nord, Nordosten, bis Ihr ein gutes Stück hinter dem Konstruktionslager: Wut seid, dann müsstet Ihr den besagten Landeplatz sehen. Die Kristallschmiede von Bash'ir befindet sich in der nordöstlichen Ecke des Stützpunkts.\n\nDanke für Eure Hilfe, {name}. Es bedeutet unseren Söhnen alles!", sourceObjective = "Beschafft ihm ein instabiles Fläschchen des Zauberers.", progress = "Dieses Fläschchen des Zauberhexers wird meine Jungs sicherlich noch intelligenter machen, als sie es ohnehin schon sind. Damit sollten ihnen die täglichen Pflichten in der Himmelswache der Sha'tari etwas leichter fallen.", completion = "Wir können Euch gar nicht genug danken, {name}!\n\nSo instabil diese zwei Fläschchen auch sein mögen, mit ihrer Hilfe können wir nun einen unserer Jungs nach Norden zum Außenposten der Himmelswache schicken.\n\nWartet einen kleinen Augenblick, während wir einen von ihnen rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11062] = { id = 11062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Außenposten der Himmelswache", description = "{name}, wir haben uns gefragt, ob Ihr vielleicht nach Norden aufbrechen würdet, um unseren Freunden beim Außenposten der Himmelswache einen Besuch abzustatten?\n\nKommandant Keller und seine Himmelswache führen zu unserem Schutz diverse Unternehmungen durch und erst kürzlich bat er uns, jeden vorbeizuschicken, der Willens ist, sie bei ihrer Arbeit zu unterstützen.\n\nDas wäret dann wohl Ihr!\n\nBrecht so schnell wie möglich dorthin auf und übermittelt ihnen unsere besten Grüße.", sourceObjective = "Sprecht mit Himmelskommandant Keller beim Außenposten der Himmelswache im Schergrat.", completion = "Willkommen im Außenposten der Himmelswache. Wisst Ihr, ich habe den gesamten Posten mit meinen eigenen Händen errichtet.\n\nSchon richtig gehört, alles was Ihr hier vor Euch seht!\n\n<Dem Himmelskommandanten scheint es ernst zu sein.>\n\nIhr müsst ja ganz schön scharf auf einen Kampf sein, wenn Ihr extra hierher gekommen seid, um mit mir zu sprechen. Es war nett vom alten Chu'a'lor, Euch vorbeizuschicken. Wir können hier immer etwas Frischfleisch gebrauchen.\n\nWenn es Euch nichts ausmacht, würde ich vorschlagen, Ihr unterhaltet Euch ein wenig mit meinem Himmelsoffizier Vanderlip. Stört Euch nicht an ihrem Gebaren, ihre Zunge ist womöglich schärfer als das Breitschwert, das sie bei sich trägt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11063] = { id = 11063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich Flügel verdienen...", sourceObjective = "Ihr möchtet also zu den Himmelsteilern gehören, ja? Ihr habt Euch mit Sicherheit als fähiger Anhänger des Drachenmals bewiesen, aber in den Lüften der Scherbenwelt ist dies bedeutungslos. Es gibt eine Frage zu klären: KÖNNT IHR FLIEGEN?\n\nUnd ich frage nicht etwa, ob Ihr auf einen Netherdrachen steigen und wie diese Transportertrottel eine Ladung Kristalle zu der Festung liefern könnt. Ich rede davon, der Beste zu sein... der Toporc...\n\nDort drüben im Westen gibt es sechs Reiter. Besiegt sie alle und ich werde Euch Flügel der Himmelsteiler geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11064] = { id = 11064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Murg \"Grufti\" Moorbiss", description = "Lasst Euch von dem grauen Haar nicht täuschen, Grunzer. Ich bin trotz allem ein zehnmal so guter Reiter! Glaubt bloß nicht, dass dieser Totgesagte keine Tricks mehr im Ärmel hat.\n\nVersucht mir zu folgen und nicht von Eurem Reittier geworfen zu werden, das ist alles. Wenn Ihr das fertig bringt, wird Grufti seine Niederlage eingestehen.\n\nWir heben ab, sobald Ihr bereit seid.", sourceObjective = "Folgt Murg \"Grufti\" Moorbiss und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Murg \"Grufti\" Moorbiss besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Ein Kinderspiel? Was ist nur aus den Helden geworden... Ich bin mir sicher, dass die anderen Reiter eine größere Herausforderung sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11065] = { id = 11065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bändigt ein paar Ätherrochen!", description = "Wollt Ihr der Himmelswache und Ogri'la aushelfen?\n\nHört mir erst zu, bevor Ihr einfach davonrennt, <Junge/Mädel>. Wir benötigen dringend mehr Reittiere. Die Missionen und Bombenangriffe auf den Landeplatz von Bash'ir haben uns so manches Reittier gekostet.\n\nDie Ätherrochen, die beim Vortexgipfel und am Kristallrücken herumfliegen, sollten für unsere Zwecke genügen. Ihr müsst sie nicht einmal hierher zurückbringen, obwohl das nett wäre. Bändigt sie einfach und bindet sie irgendwo an, wir holen sie dann später ab.\n\nSeid Ihr dieser Aufgabe gewachsen?", sourceObjective = "Bändigt mithilfe des Bändigungsseils 5 Ätherrochen.", progress = "Habt Ihr schon ein paar Ätherrochen gebändigt? Ihr seht so aus, als könntet Ihr mit einem Lasso umgehen. Sicher habt Ihr Euren Auftrag schnell abgeschlossen.", completion = "Juhuu! Gute Arbeit, {name}! Diese Rochen werden ein paar hervorragende Reittiere abgeben!\n\nBleibt ruhig noch ein wenig, die Himmelswache der Sha'tari kann Männer mit Euren Talenten immer gut gebrachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11066] = { id = 11066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bändigt noch mehr Ätherrochen!", description = "Ich hoffe Ihr seid bereit, noch ein paar mehr Ätherrochen zu bändigen! Soweit ich das beurteilen kann, liegt Euch der Umgang mit dem Seil im Blut!\n\nUnd es dient einem guten Zweck, denn so kriegen wir nicht nur frische Reittiere, sondern Ihr helft uns auch noch Ogri'la zu beschützen, wofür die Oger dankbar sind.\n\nNicht vergessen, die Ätherrochen fliegen beim Vortexgipfel und am Kristallrücken im Nordosten herum.\n\nSchafft Ihr es, noch ein paar mehr für mich zu bändigen?", sourceObjective = "Bändigt mithilfe des Bändigungsseils 5 Ätherrochen.", progress = "Ihr leistet hervorragende Arbeit für uns, {name}! Ich möchte Euch nur wissen lassen, dass wir Eure Bemühungen, uns mit frischen Reittieren zu versorgen, sehr zu schätzen wissen!", completion = "Ihr erstaunt mich immer wieder! Ich sage Euch was, warum lasst Ihr das Lasso nicht für heute ruhen und wir sehen uns morgen wieder?\n\n<Khatie lacht.>\n\nNochmals vielen Dank, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11067] = { id = 11067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Trope der Rußhuster", description = "Das Drachenmal behandelt einen richtig, {name}. Selbst so ein ausgelaugtes und gezeichnetes Wesen wie ich bekommt seine Chance. Wenn Ihr Euch den Himmelsteilern als würdig erweisen wollt, dann müsst Ihr mich besiegen.\n\nIch werde Euch wie einen Schwarm lästige Fliegen abschütteln...\n\nWir heben ab, sobald Ihr bereit seid.", sourceObjective = "Folgt Trope dem Rußhuster und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Trope den Rußhuster besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Interessant... Euer nächstes Rennen wird sich zweifellos als viel schwieriger erweisen. Corlok ist kein Weichei.", sourceObjectiveStatus = "unverified-source-field" }
quests[11068] = { id = 11068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Corlok der Veteran", description = "Ihr fordert MICH heraus? Jetzt muss ich aber lachen!\n\nIst das Euer Ernst? Na gut! Achtet lediglich darauf, nicht zu sterben. Ihr schafft das doch, nicht zu sterben, oder?? Auch wenn ich Schädel nach Euch werfe und in Kreisen um Euch und Eure erbärmlichen Flugkünste fliege?\n\nLasst mich einfach wissen, wann's losgehen kann, dann heben wir ab.", sourceObjective = "Folgt Corlok dem Veteranen und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Corlok den Veteranen besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Die nächsten zwei Reiter sind die besten Piloten, die die Zwerge und Orcs von Azeroth zu bieten hatten. Ihr habt keine Chance!", sourceObjectiveStatus = "unverified-source-field" }
quests[11069] = { id = 11069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Schwadronskommandant Ichman", description = "Drei Jahre habe ich in diesem Loch zugebracht. Drei Jahre lang war ich Kriegsgefangener des verdammten Frostwolfklans. Ich musste in ihrem Turm sitzen und ihr endloses Gejammer über die Brücke nach Dun Baldar ertragen. Wie \"ungerecht\" es doch sei, dass bla, bla, bla, bla... Im Krieg gibt es keine Gerechtigkeit! Zur Hölle mit ihnen allen!\n\nIn dem Augenblick, in dem ich befreit wurde, habe ich diesen Ort für immer verlassen und bin hierhergekommen, um ein neues Leben zu beginnen. Mulv und ich konkurrieren jetzt um den Platz des Toporcs. Sollte das auch Euer Ziel sein, dann müsst Ihr erstmal an mir vorbei, Anfänger.\n\nEs geht los, wenn Ihr bereit seid.", sourceObjective = "Folgt Schwadronskommandant Ichman und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Schwadronskommandant Ichman besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Ich glaube es nicht! Mulverick ist Eure nächste Herausforderung. Dieses Rennen werdet Ihr auf keinen Fall überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11070] = { id = 11070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Schwadronskommandant Mulverick", description = "Drei Jahre lang Blut, Schweiß und Tränen. Hauptsächlich Tränen... Es ist erstaunlich, wie viele Tränen selbst ein hartgesottener Soldat vergießt, wenn es im Krieg zur Sache geht.\n\n\"Sie springen mit ihren Pferden in unseren Turm!\" \"Warum muss die feindliche Basis so gut verteidigt sein?\" \"Verdammt, der Feind hat die Heilerhütte erobert, ich mache mich vom Acker!\"\n\nVerdammte Feiglinge...\n\nKaum war das Dunkle Portal offen, hab' ich die Möglichkeit beim Schopfe gepackt und mich aus dem Land der Weicheier verabschiedet. Jetzt arbeite ich als Toppilot für die Jungs des Drachenmals. Wenn Ihr also der Toporc werden wollt, müsst Ihr mich erst einmal schlagen.\n\nEs geht los, sobald Ihr bereit seid.", sourceObjective = "Folgt Schwadronskommandant Mulverick und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Schwadronskommandant Mulverick besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Nun Grunzer, es sieht ganz so aus, als gäbe es jetzt nur noch Euch und den Hauptmann. Viel Glück! Ihr werdet es brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11071] = { id = 11071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Hauptmann Himmelsdonner", description = "Ihr wagt es, Himmelsdonner herauszufordern? Die Welt um Euch herum wird in Dunkelheit versinken, wenn meine Meteore den Horizont zerreißen.\n\nIhr habt keine Chance, Soldat. Offenbar ist es jedoch Euer Wunsch, zu sterben...\n\nIch werde bei Eurem morbiden Vorhaben mitspielen. Vielleicht kann ich anderen Narren, die nach der gleichen Verrücktheit streben, zumindest eine Lehre erteilen.\n\nWir reiten los, wenn Ihr bereit seid!", sourceObjective = "Folgt Hauptmann Himmelsdonner und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Hauptmann Himmelsdonner besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Ich hätte es mir nie träumen lassen, dass es jemanden gibt, der talentiert genug ist und Himmelsdonner besiegen kann. Wisst Ihr was das bedeutet, ja? Ihr seid jetzt der Toporc! Ihr müsst Euren Titel verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11072] = { id = 11072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindesblut", description = "Die Nachfahren, die von den Krallenpriestern von Skettis gefangen gehalten werden, sind alle in diesem Buch aufgeführt. Gezzarak die Jägerin, Karrog der Kristallriese, der Ketzer namens Dunkelkreischer Akkarai und Vakkiz der Windzürner. Sie alle müssen getötet werden, bevor Terokk in diese Welt zurückkehrt.\n\nIhr werdet die Schriftrollen benötigen, die die zeitverlorenen Arakkoa bei sich tragen. Benutzt sie bei den Beschwörungskreisen, die es in Skettis gibt. Bringt mir von einem jeden ein Beweisstück. Eure Gegner sind mächtige Wesen; Ihr tätet gut daran, ein paar Freunde mitzunehmen.", sourceObjective = "Findet die Schädelhaufen innerhalb der Beschwörungskreise in Skettis. Beschwört die Nachfahren, indem Ihr 10 zeitverlorene Schriftrollen am Schädelhaufen benutzt und bezwingt sie. Kehrt mit einem Beweisstück von jedem zu Hazzik am Schattenwindlager zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[11073] = { id = 11073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokks Fall", description = "Ich... ich habe bezüglich Eures Verhaltens gegenüber dem Arakkoagefangenen ein Auge zugedrückt, {name}. Es sieht ganz so aus, als hätte Euch Euer Instinkt nicht getäuscht. Es war richtig, mit ihm zusammenzuarbeiten.\n\nBitte versteht... Ich hätte mich in der jetzigen Lage inmitten eines Aufruhrs wiedergefunden, hätte ich Eure Bemühungen, Terokk in diese Welt zu bringen, gebilligt.\n\nNehmt die Gegenstände, die Hazzik für Euch zusammengestellt hat und führt Euren Plan weiter fort. Ich werde meinen Männern befehlen, Euch Rückendeckung zu geben, wenn es an der Zeit dafür ist. Ich rate Euch, auch selbst Verstärkung mit Euch zu bringen. Ich fürchte Ihr habt nur diese eine Chance.", sourceObjective = "Bringt die Zeitverlorene Opfergabe, die Hazzik angefertigt hat, zu dem Schädelhaufen im Zentrum von Skettis. Beschwört Terokk und bezwingt ihn. Habt Ihr Eure Aufgabe erfüllt, kehrt zu Himmelskommandant Adaris zurück.", completion = "Ihr habt uns alle sehr stolz gemacht, {name}. Ich werde die Kunde von Euren Taten in Shattrath verbreiten. Die Himmelswache steht für immer in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[11074] = { id = 11074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen der Nachfahren", description = "Die Nachfahren, die von den Krallenpriestern von Skettis gefangen gehalten werden, sind alle in diesem Buch aufgeführt. Gezzarak die Jägerin, Garogg der Kristallriese, der Ketzer namens Dunkelkreischer Akkarai und Vakkiz der Windzürner. Sie alle müssen getötet werden, bevor Terokk in diese Welt zurückkehrt.\n\nIhr werdet die Schriftrollen benötigen, die die zeitverlorenen Arakkoa bei sich tragen. Verbrennt sie bei den Beschwörungskreisen, die es überall in Skettis gibt. Bringt mir von einem jeden ein Beweisstück. Eure Gegner sind mächtige Wesen; Ihr tätet gut daran, ein paar Freunde mit Euch zu bringen.", sourceObjective = "Sammelt zeitverlorene Schriftrollen von den zeitverlorenen Arakkoa in Skettis ein und bringt sie zu den Schädelhaufen innerhalb der Beschwörungskreise in Skettis. Beschwört und bezwingt die Nachfahren der Gegner Terokks und kehrt zu Hakkiz mit Akkarais Kralle, Garokks Stachel, Vekkaz' Schuppe und Gezzaraks Klaue zurück.", progress = "Ich benötige einen Gegenstand von jedem der Nachfahren von Terokks ärgsten Feinden. Nur dann können wir Terokk beschwören.", completion = "Hervorragend! Hier, nehmt dies. Ich habe dieses Bündel aus den Gegenständen erstellt, die Ihr mir gebracht habt. Damit werdet Ihr Terokk beschwören können.\n\nSeid auf der Hut, {name}. Er ist der mächtigste Arakkoa aller Zeiten. Unterschätzt ihn nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[11075] = { id = 11075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Netherschwingenminen", description = "Wir benötigen Eure Hilfe bei den Netherschwingenminen, Aufseher {name}.\n\nVor zwei Tagen machten wir eine düstere Entdeckung und daraufhin kamen unsere Minenarbeiten zum Stillstand. Ein Minenarbeiter arbeitete in den Tiefen der Mine und hieb seine Hacke in eine ungewöhnliche Kristallformation. Unglücklicherweise war diese Kristallformation mit einem sehr verärgerten Netherdrachen verbunden. Die Bestie erwachte aus ihrem Schlaf und tötete all unsere Arbeiter.\n\nErstattet bei der Herrin der Minen Bericht. Man erwartet Euch beim Eingang der Minen, südwestlich von hier.", sourceObjective = "Sucht die Herrin der Minen auf der Netherschwingenscherbe auf.", completion = "Die Minenarbeiter leisten harte Arbeit, aber keiner von ihnen wagt es, einen Schritt tiefer in die Minen zu setzen. Sie sterben lieber, als dass sie sich tiefer in die Minen zwingen lassen! Es wird Eure Aufgabe sein, die von ihnen vernachlässigten Pflichten zu erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11076] = { id = 11076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dinge in den Griff bekommen...", description = "Die Mühen unserer harten Arbeit liegen überall in diesen Minen verstreut. Wagenladungen voller Fracht bedecken jeden Zentimeter dieser Mine! Auf Grund der Plage kommen wir nur an nichts von alledem heran.\n\nGenau hier kommt Ihr ins Spiel, {name}. Eure tägliche Arbeit bei der Mine wird aus dem Einsammeln der von den Minenarbeitern und Tiefenminenarbeitern zurückgelassenen Fracht bestehen.\n\nSammelt die Fracht der Netherminen ein und kehrt zu mir oder meiner Schwester zurück.", sourceObjective = "Die Herrin der Minen bei den Netherschwingenminen im Schattenmondtal möchte, dass Ihr 15 Kisten mit Fracht der Netherminen einsammelt.", progress = "Habt Ihr die Fracht eingesammelt?", completion = "Gut gemacht, {name}. Kommt morgen für einen weiteren Einsatz in den Tiefen der Mine wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11077] = { id = 11077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachen sind unsere geringste Sorge", description = "Als der Drache erwachte, schreckte er in diesen Minen noch ganz andere bösartige Kreaturen auf. Insbesondere zwei Arten sind dem Drachenmal ein Dorn im Auge: Netherminenschinder und Netherminenhetzer. Ihr müsst uns helfen, sie alle zu töten. Ich bitte Euch lediglich einmal pro Tag um Eure Mithilfe.\n\nGeht hinein und vernichtet so viele, wie Ihr nur könnt!", sourceObjective = "Der Vorarbeiter des Drachenmals bei den Netherschwingenminen im Schattenmondtal möchte, dass Ihr 15 Netherminenschinder und 5 Netherminenhetzer tötet.", completion = "Das sollte für heute reichen, Aufseher. Kommt morgen für eine weitere Aufräumrunde wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11078] = { id = 11078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Himmel beherrschen", description = "Während Ihr herumgeflogen seid, sind Euch sicherlich die Drachen aufgefallen. Schätze, ihr Zorn blieb Euch bisher erspart. Helft uns, diese Biester ein für alle Mal zu erledigen, {name}!\n\nNachtreißer und Obsidia beherrschen dieses Plateau, während Insidion und Zornschwinge den Himmel über den Terrassen im Nordosten für sich beanspruchen. Jeder der Drachen hat ein Nest in seinem Revier gebaut. Ich frage mich, ob Ihr und Eure Freunde einen aufsuchen würdet, <Kumpel/Mädel>. Brecht ein Ei mit 35 Apexissplittern auf, um den Drachen herunterzulocken.\n\nBringt mir ein paar Zähne als Beweis.", sourceObjective = "Beschafft Euch Drachenzähne.", progress = "Wie geht es voran, {name}? Ich brauche Euch sicherlich nicht extra zu sagen, wie wichtig die ganze Angelegenheit für unsere Luftüberlegenheit ist.", completion = "Ja! Diese Zähne sehen scharf aus, als könnten sie beinahe alles wie Butter durchschneiden!\n\nErlaubt mir, Euch und Eure Freunde dazu zu ermuntern, weiterhin so gute Arbeit zu leisten! Diese Drachen sind gefährliche Raubtiere, die unseren Himmel lange genug unsicher gemacht haben.\n\nEuch sind sicherlich die Drachenschuppen aufgefallen. Wie ich hörte, kann man aus ihnen einen mächtigen Umhang herstellen, sofern man eine Schuppe von jedem der Drachen besitzt. Sollte Euch der Umhang nicht zusagen, bin ich jederzeit bereit, ihn gegen einen Apexiskristall einzutauschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11079] = { id = 11079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Teufelspeitsche für Gahk", description = "Gahk manchmal glauben, es nicht gut ist, schlau zu sein. Gahk möchten nicht so viel nachdenken müssen. Ich wollen, dass <kleiner/kleine:r> {race} große Dämonen totschlagen!\n\nSie haben einige Anführer und jeder von ihnen haben Peitschen, um den mickrigen Dämonen Verstand einzuprügeln. Gahk wollen so eine Peitsche!\n\nDazu Ihr herausfordern müssen einen Dämonenanführer in Konstruktionslager. Einen solchen Ihr finden bei brennenden, grünen kristallinen Teufelsprisma. Benutzen 35 Apexissplitter, um sie zu rufen. Sie hören auf Namen wie Galvanoth, Braxxus, Zarcsin und der Verbrenner der Mo'arg.", sourceObjective = "Beschafft Euch eine Teufelspeitsche.", progress = "Ihr haben Peitsche?", completion = "Gahk mögen Peitsche. Vielleicht Ghak nehmen Peitsche und bearbeiten ein paar Dämonen!\n\nMich sagen zu {race}, dass {race} kann jederzeit beschwören Dämonenanführer, solange {race} haben viele Freunde und 'ne Menge Splitter.", sourceObjectiveStatus = "unverified-source-field" }
quests[11080] = { id = 11080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Strahlung des Relikts", description = "Nachdem Ihr die erleuchtenden Schwingungen der Apexisrelikte am eigenen Leib erfahren habt, ist es an der Zeit, ein tieferes Verständnis für die Funktionsweise der Relikte zu bekommen. Wir würden von Euren Beobachtungen profitieren.\n\nJe mehr Eure Fähigkeiten wachsen, Euch auf die Kräfte der Relikte einzustellen, desto mehr Wissen werdet Ihr über sie erlangen. Ist es erst einmal soweit, wird Euch ein Strahlungsausstoß des Relikts Euren Erfolg anzeigen.\n\nKehrt zu uns zurück, wenn Ihr eine solche Strahlungsaura erlangt habt.", sourceObjective = "Erlangt Apexisstrahlung von einem Apexisrelikt.", progress = "Habt Ihr eine Aura der Apexisstrahlung von dem Apexisrelikt erlangt?", completion = "Euer Geschick im Umgang mit den Relikten erstaunt uns immer wieder, {name}. Dürften wir Euch vorschlagen, mindestens einmal am Tag den Gebrauch der Relikte zu üben, damit Euer Verstand seine Schärfe bewahrt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11081] = { id = 11081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Aufstand der Finsterblut", description = "Dieses Schriftstück beschreibt einen von den Zerschlagenen der Finsterblut geplanten Aufstand. Offenbar diente der Drache der allgemeinen Zerstreuung, um von ihrer Flucht abzulenken. Beim Betrachten der überall in der Mine herumliegenden Leichen, könnte man von einem Fehlschlag ihres Plans ausgehen.\n\nBringt die Fluchtpläne zur Herrin der Minen.", sourceObjective = "Bringt die Fluchtpläne der Finsterblut zur Herrin der Minen.", progress = "Was ist das?", completion = "Ausgezeichnete Arbeit, Aufseher. Man wird Mor'ghor von Euren herausragenden Taten für das Drachenmal berichten.\n\nLasst uns jetzt wieder auf diese Hunde der Finsterblut zu sprechen kommen. Sie planen ihre Flucht, ja? Sie wagen es, sich dem einzig wahren Fürsten der Scherbenwelt zu widersetzen? Ihre Meister werden dafür bezahlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11082] = { id = 11082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach der Wahrheit", description = "Diese Minenarbeiter sind viel zu dumm, als dass sie irgendeinen Fluchtplan aushecken könnten. Wir müssen die Quelle des Übels finden und bestrafen. Wagt Euch in die Tiefen der Minen und sucht nach den Aufpassern der Finsterblut. Wenn sie nicht schon von den Bewohnern der Minen überwältigt wurden, so halten sie sich zweifellos versteckt.\n\nSolltet Ihr einen von ihnen ausfindig machen, verhört ihn so lange, bis er das wahre Gehirn, das hinter diesem Fluchtplan steckt, preisgibt. Kehrt mit der Identität des Verräters und der Hand des Aufpassers zu mir zurück.", sourceObjective = "Findet einen Aufpasser der Finsterblut und verhört ihn. Kehrt mit den Informationen der Finsterblut und mit der Hand des Aufpassers zur Herrin der Minen zurück.", progress = "Nun? Warum dauert das so lange?", completion = "Nichts zu sagen? Vielleicht erinnert er sich ja, wenn er auf dem Boden dieser verfluchten Mine zu Tode blutet... Vergesst nie, was es bedeutet, die Mächte Illidans herauszufordern!", sourceObjectiveStatus = "unverified-source-field" }
quests[11083] = { id = 11083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrückt und verwirrt", description = "Sorgt Euch nicht wegen diesem Drachen, {name}. Wir haben bereits Pläne für ihn...\n\nTiefer in der Mine gibt es eine verrückte Schar der Finsterblut. Nachdem der Drache ausgebrochen ist, wurde ihnen der Weg zum Ausgang versperrt. Nach zwei Tagen der Abgeschiedenheit scheinen sie auf irgendeine Art und Weise jegliche Würde verloren zu haben.\n\nSie haben sich dem Kannibalismus und der Gewalt verschrieben. Dieser Wahnsinn ist hier alles andere als erwünscht. Findet und tötet sie. Alle!", sourceObjective = "Ronag der Sklaventreiber in den Netherschwingenminen im Schattenmondtal möchte, dass Ihr den verrückten Großknecht der Finsterblut und 5 verrückte Minenarbeiter der Finsterblut tötet.", completion = "Ja, ich verstehe das nicht... Man würde doch meinen, dass sie nach zwei Tagen nicht derart ausgehungert sein können. Finsterblut...\n\n<Ronag schüttelt den Kopf.>\n\nSowas von dämlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[11084] = { id = 11084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seid gegrüßt, Hauptmann!", description = "Nun sieh einer an... Ihr lebt also noch. Das trifft sich gut, denn Mor'ghor hat nach Eurer sofortigen Anwesenheit in seinem Turm verlangt. Los mit Euch!", sourceObjective = "Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal.", completion = "<Mor'ghor nickt.>\n\nGanz recht, ich habe Hauptmann gesagt. Ihr habt Euch eine weitere Beförderung verdient, {name}.\n\nIhr arbeitet wirklich wie keiner der Höllenorcs, die ich bis jetzt gesehen habe. Macht weiter so, dann schafft Ihr es vielleicht eines Tages zum Oberanführer.\n\nZieht jetzt los und übernehmt das Kommando. Ich schlage vor, dass Ihr versucht, Euch Eure Flügel der Himmelsteiler zu verdienen.", sourceObjectiveStatus = "unverified-source-field" }
